-- One-time generated atomic Studio installer. No explicit transaction boundary:
-- Supabase apply_migration owns its transaction; the single DO owns all17+ledger atomically.
-- Generator/inputs are private evidence; original17 source migrations remain immutable.
-- All missing: execute exact official-CLI statement vectors and insert only NEW canonical ledger rows.
-- All present: exact vectors and approved named function/ACL postconditions must match, then no-op.
-- Partial/mismatched state: REFUSE. No historical repair/upsert, activation, claim or provider command.
set local lock_timeout='2s';
set local statement_timeout='45s';

create temporary table studio_rehearsal_result(value jsonb) on commit drop;
create or replace function pg_temp.studio_canonical_access() returns jsonb language sql as $fn$
 select jsonb_object_agg(p.oid::text,jsonb_build_array(p.proacl,p.proconfig,p.prosecdef,p.proowner)) from pg_proc p
 where p.oid=any(array['private.invoice_email_generation_guard()'::regprocedure,'public.commercial_quote_prepare_delivery_email(uuid,bigint,text,text,uuid,uuid,text,jsonb,timestamptz)'::regprocedure,'public.commercial_email_mark_dispatching(uuid)'::regprocedure,'public.background_jobs_claim(text,integer,integer)'::regprocedure,'public.background_jobs_runtime_metrics()'::regprocedure]);
$fn$;
create or replace function pg_temp.studio_function_manifest(p_existing oid[]) returns jsonb language sql as $fn$
 select jsonb_agg(jsonb_build_object(
  'signature',n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')',
  'definitionSha256',encode(sha256(convert_to(replace(pg_get_functiondef(p.oid),chr(13),''),'UTF8')),'hex'),
  'owner',pg_get_userbyid(p.proowner),
  'acl',(select jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) from aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a)
 ) order by n.nspname,p.proname,oidvectortypes(p.proargtypes))
 from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname in ('public','private') and (not(p.oid=any(p_existing)) or p.oid=any(array['private.invoice_email_generation_guard()'::regprocedure,'public.commercial_quote_prepare_delivery_email(uuid,bigint,text,text,uuid,uuid,text,jsonb,timestamptz)'::regprocedure,'public.commercial_email_mark_dispatching(uuid)'::regprocedure,'public.background_jobs_claim(text,integer,integer)'::regprocedure,'public.background_jobs_runtime_metrics()'::regprocedure]));
$fn$;
create or replace function pg_temp.studio_schema_manifest() returns jsonb language sql as $fn$
 select jsonb_build_object(
 'tables',(select jsonb_agg(jsonb_build_object('name',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,
  'acl',(select jsonb_agg(jsonb_build_array(case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type,a.is_grantable) order by case when a.grantee=0 then 'PUBLIC' else pg_get_userbyid(a.grantee) end,pg_get_userbyid(a.grantor),a.privilege_type) from aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a),
  'columns',(select jsonb_agg(jsonb_build_array(a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull,pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
  'constraints',(select jsonb_agg(jsonb_build_array(k.conname,pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.conrelid=c.oid),
  'indexes',(select jsonb_agg(pg_get_indexdef(i.indexrelid) order by pg_get_indexdef(i.indexrelid)) from pg_index i where i.indrelid=c.oid),
  'policies',(select jsonb_agg(jsonb_build_array(p.polname,p.polcmd,p.polpermissive,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid)) order by p.polname) from pg_policy p where p.polrelid=c.oid)
 ) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and left(c.relname,7)='studio_' and c.relkind='r'),
 'triggers',(select jsonb_agg(jsonb_build_array(n.nspname,c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid)) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and left(t.tgname,7)='studio_' and not t.tgisinternal)
 );
$fn$;
create or replace function pg_temp.studio_metadata_fingerprint() returns jsonb language plpgsql as $fn$
declare item record; cols text; n bigint; h text; result jsonb:='{}'; clause text;
begin
 for item in select nspname,relname,c.oid from pg_class c join pg_namespace n on n.oid=c.relnamespace
  where (n.nspname='public' and c.relname=any(array['projects','estimates','quotes','quote_versions','quote_line_items','quote_send_logs','deposit_invoices','deposit_invoice_send_logs','file_artifacts','job_pack_generations','job_pack_sheet_overrides','background_jobs','background_job_kinds','background_job_rollouts','background_job_events','background_job_effects','background_job_workers','background_job_provider_receipts']))
   or (n.nspname='private' and c.relname='commercial_email_intents')
   or (n.nspname='pgmq' and c.relname in ('q_portal_background_jobs','a_portal_background_jobs'))
 loop
  select string_agg(format('%I',a.attname),',' order by a.attnum) into cols from pg_attribute a
   where a.attrelid=item.oid and a.attnum>0 and not a.attisdropped and a.atttypid not in ('json'::regtype,'jsonb'::regtype,'bytea'::regtype)
   and a.attname not in ('content_base64','protected_payload','request_payload','drawing_source');
  if cols is null then raise exception 'No protected scalar metadata columns: %',item.relname; end if;
  clause:=case when item.nspname='public' and item.relname='background_job_kinds' then ' where kind<>''studio_design_booklet_v1''' else '' end;
  execute format('select count(*),md5(coalesce(string_agg(h,'','' order by h),'''')) from(select md5(to_jsonb(d)::text) h from(select %s from %I.%I%s)d)x',cols,item.nspname,item.relname,clause) into n,h;
  result:=result||jsonb_build_object(item.nspname||'.'||item.relname,jsonb_build_object('count',n,'scalarMetadataMd5',h));
 end loop;return result;
end $fn$;
create or replace function pg_temp.studio_catalog_fingerprint() returns text language sql as $fn$
 select md5(coalesce(string_agg(v,chr(10) order by v),'')) from(
 select jsonb_build_array('function',n.nspname,p.oid,p.proname,p.proargtypes::text,p.prorettype,p.prosrc,p.prosecdef,p.proacl,p.proconfig)::text v from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private')
 union all select jsonb_build_array('relation',n.nspname,c.oid,c.relname,c.relkind,c.relrowsecurity,c.relforcerowsecurity,c.relacl)::text from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','pgmq')
 union all select jsonb_build_array('column',n.nspname,c.relname,a.attnum,a.attname,a.atttypid,a.atttypmod,a.attnotnull,pg_get_expr(d.adbin,d.adrelid))::text from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where n.nspname in ('public','private','pgmq') and a.attnum>0 and not a.attisdropped
 union all select jsonb_build_array('constraint',n.nspname,c.conname,pg_get_constraintdef(c.oid))::text from pg_constraint c join pg_namespace n on n.oid=c.connamespace where n.nspname in ('public','private')
 union all select jsonb_build_array('trigger',n.nspname,c.relname,t.tgname,t.tgenabled,pg_get_triggerdef(t.oid))::text from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and not t.tgisinternal
 union all select jsonb_build_array('policy',n.nspname,c.relname,p.polname,p.polroles,p.polcmd,p.polpermissive,pg_get_expr(p.polqual,p.polrelid),pg_get_expr(p.polwithcheck,p.polrelid))::text from pg_policy p join pg_class c on c.oid=p.polrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')
 ) entries;
$fn$;

do $studio_atomic_install$
declare
 sources jsonb:=$sources$[{"version":"20261020080001","name":"studio_authored_save","rawSha256":"a6950d045258e06a3c6ebcf486bfcfd7218309cc6f61ea14b7250c8a46d4d9c8","canonicalLfSha256":"a6950d045258e06a3c6ebcf486bfcfd7218309cc6f61ea14b7250c8a46d4d9c8","statements":["-- Install-only foundation. Studio authored revisions remain UNPRICED.\n-- The server validates the canonical spatial contract before calling this command.\ncreate table private.studio_authored_save_receipts (\n  estimate_id uuid not null references public.estimates(id),\n  request_id uuid not null,\n  -- Historical identity must survive removal of current Portal membership.\n  -- The command checks current staff access before every write or replay.\n  actor_user_id uuid not null,\n  request_payload jsonb not null,\n  revision bigint not null check (revision > 0),\n  saved_at timestamptz not null,\n  primary key (estimate_id, request_id)\n)","revoke all on private.studio_authored_save_receipts from public, anon, authenticated, service_role","-- Quote creation and studio save take the same estimate row lock. This closes\n-- the race between checking for quote references and attaching a new quote.\ncreate function private.studio_quote_source_guard() returns trigger\nlanguage plpgsql security definer set search_path = pg_catalog, pg_temp as $$\ndeclare v_outputs jsonb;\nbegin\n  if tg_op = 'UPDATE' and new.source_estimate_version_id is not distinct from old.source_estimate_version_id then return new; end if;\n  if new.source_estimate_version_id is null then return new; end if;\n  select e.outputs into v_outputs from public.estimates e where e.id=new.source_estimate_version_id for update;\n  if v_outputs ? 'studio_authored' then\n    raise exception 'studio_costing_required' using errcode='23514';\n  end if;\n  return new;\nend;\n$$","revoke all on function private.studio_quote_source_guard() from public, anon, authenticated, service_role","create trigger studio_quote_source_guard before insert or update of source_estimate_version_id\non public.quote_versions for each row execute function private.studio_quote_source_guard()","-- Generic estimate writers may change notes/name, but cannot strip or overwrite\n-- a studio revision and thereby make its retained price quoteable again.\ncreate function private.studio_estimate_write_guard() returns trigger\nlanguage plpgsql set search_path = pg_catalog, pg_temp as $$\nbegin\n  if (coalesce(old.outputs,'{}'::jsonb) ? 'studio_authored' or coalesce(new.outputs,'{}'::jsonb) ? 'studio_authored')\n    and (old.inputs is distinct from new.inputs or old.outputs is distinct from new.outputs)\n    and not (coalesce(current_setting('sanctuary.studio_command',true),'')='save'\n      and current_user = pg_get_userbyid((select p.proowner from pg_proc p where p.oid='public.studio_authored_save(uuid,uuid,uuid,uuid,timestamptz,bigint,jsonb,jsonb,jsonb,jsonb)'::regprocedure))) then\n    raise exception 'studio_command_required' using errcode='42501';\n  end if;\n  return new;\nend;\n$$","revoke all on function private.studio_estimate_write_guard() from public, anon, authenticated, service_role","create trigger studio_estimate_write_guard before update of inputs, outputs\non public.estimates for each row execute function private.studio_estimate_write_guard()","create function public.studio_authored_save(\n  p_project_id uuid, p_estimate_id uuid, p_actor_user_id uuid, p_request_id uuid,\n  p_expected_updated_at timestamptz, p_expected_revision bigint,\n  p_authored jsonb, p_spatial jsonb, p_validated_stored_authored jsonb, p_client_request jsonb\n) returns table (revision bigint, saved_at timestamptz, already_existed boolean)\nlanguage plpgsql security definer set search_path = pg_catalog, pg_temp as $$\ndeclare\n  v_estimate public.estimates%rowtype;\n  v_receipt private.studio_authored_save_receipts%rowtype;\n  v_request jsonb;\n  v_current jsonb;\n  v_revision bigint;\n  v_next bigint;\n  v_saved_at timestamptz;\n  v_previous_context text;\nbegin\n  if p_request_id is null or p_expected_revision is null or p_expected_revision < 0\n    or not exists(select 1 from public.portal_users u where u.user_id=p_actor_user_id and u.role in ('staff','admin')) then\n    raise exception 'studio_staff_required' using errcode='42501';\n  end if;\n  select * into v_estimate from public.estimates e where e.id=p_estimate_id and e.project_id=p_project_id for update;\n  if not found then raise exception 'studio_estimate_unavailable' using errcode='P0002'; end if;\n  -- The server reconstructs private retained fields from the current source.\n  -- Retry identity must use the exact browser command, never that reconstruction:\n  -- a later save may have changed private fields before an earlier retry arrives.\n  if jsonb_typeof(p_client_request) is distinct from 'object' then\n    raise exception 'studio_invalid_payload' using errcode='22023';\n  end if;\n  v_request := jsonb_build_object('projectId',p_project_id,'expectedUpdatedAt',p_expected_updated_at,\n    'expectedRevision',p_expected_revision,'clientRequest',p_client_request);\n  select * into v_receipt from private.studio_authored_save_receipts r where r.estimate_id=p_estimate_id and r.request_id=p_request_id;\n  if found then\n    if v_receipt.actor_user_id<>p_actor_user_id or v_receipt.request_payload is distinct from v_request then\n      raise exception 'studio_request_conflict' using errcode='23505';\n    end if;\n    return query select v_receipt.revision,v_receipt.saved_at,true;\n    return;\n  end if;\n  -- JSONB concatenation with a scalar/array would hide the marker inside an\n  -- array, defeating marker-based readers. Preserve unsupported source data.\n  if v_estimate.outputs is not null and jsonb_typeof(v_estimate.outputs)<>'object' then\n    raise exception 'studio_schema_unsupported' using errcode='22023';\n  end if;\n  if not exists(select 1 from public.projects p where p.id=p_project_id and p.archived_at is null)\n    or v_estimate.status is distinct from 'draft' then\n    raise exception 'studio_estimate_unavailable' using errcode='P0002';\n  end if;\n  -- A quote's source stays unchanged, even for a prepared draft quote. The UI\n  -- creates a new estimate revision instead of modifying any referenced source.\n  if exists(select 1 from public.quote_versions q where q.source_estimate_version_id=p_estimate_id) then\n    raise exception 'studio_estimate_referenced' using errcode='23514';\n  end if;\n  if v_estimate.updated_at is distinct from p_expected_updated_at then\n    raise exception 'studio_stale' using errcode='PT409';\n  end if;\n  if jsonb_typeof(p_authored) is distinct from 'object' or jsonb_typeof(p_spatial) is distinct from 'object'\n    or octet_length(v_request::text)>2097152\n    or p_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n    or p_authored->>'spatialOutputKey' is distinct from 'drawing_object_first'\n    or jsonb_typeof(p_authored->'revision') is distinct from 'number'\n    or p_authored->>'revision' !~ '^[1-9][0-9]*$'\n    or (p_authored->>'revision')::numeric <> greatest(1,p_expected_revision) then\n    raise exception 'studio_invalid_payload' using errcode='22023';\n  end if;\n  v_current := v_estimate.outputs->'studio_authored';\n  if v_current is distinct from p_validated_stored_authored then\n    raise exception 'studio_schema_unsupported' using errcode='22023';\n  end if;\n  v_revision := 0;\n  if coalesce(v_estimate.outputs,'{}'::jsonb) ? 'studio_authored' then\n    if v_current->>'schemaVersion' is distinct from 'studio_authored.v1'\n      or jsonb_typeof(v_current) is distinct from 'object'\n      or (select count(*) from jsonb_object_keys(v_current))<>8\n      or not (v_current ?& array['schemaVersion','designId','revision','spatialOutputKey','site','objectOptions','legacyCommercialAssociations','provenance'])\n      or coalesce(v_current->>'revision','') !~ '^[1-9][0-9]*$' then\n      raise exception 'studio_schema_unsupported' using errcode='22023';\n    end if;\n    v_revision := (v_current->>'revision')::bigint;\n    if v_current->'designId' is distinct from p_authored->'designId'\n      or v_current->'provenance' is distinct from p_authored->'provenance'\n      or v_current->'legacyCommercialAssociations' is distinct from p_authored->'legacyCommercialAssociations' then\n      raise exception 'studio_identity_changed' using errcode='23514';\n    end if;\n  end if;\n  if v_revision<>p_expected_revision then raise exception 'studio_stale' using errcode='PT409'; end if;\n  v_next := v_revision;\n  v_saved_at := v_estimate.updated_at;\n  if v_current is distinct from p_authored or v_estimate.outputs->'drawing_object_first' is distinct from p_spatial then\n    v_next := v_revision+1;\n    if v_next>9007199254740991 then raise exception 'studio_revision_limit' using errcode='22023'; end if;\n    v_previous_context := current_setting('sanctuary.studio_command',true);\n    perform set_config('sanctuary.studio_command','save',true);\n    update public.estimates e set outputs=coalesce(e.outputs,'{}'::jsonb)||jsonb_build_object(\n      'studio_authored',p_authored||jsonb_build_object('revision',v_next),'drawing_object_first',p_spatial),\n      updated_at=clock_timestamp()\n      where e.id=p_estimate_id returning e.updated_at into v_saved_at;\n    perform set_config('sanctuary.studio_command',coalesce(v_previous_context,''),true);\n  end if;\n  insert into private.studio_authored_save_receipts(estimate_id,request_id,actor_user_id,request_payload,revision,saved_at)\n    values(p_estimate_id,p_request_id,p_actor_user_id,v_request,v_next,v_saved_at);\n  return query select v_next,v_saved_at,false;\nend;\n$$","revoke all on function public.studio_authored_save(uuid,uuid,uuid,uuid,timestamptz,bigint,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_authored_save(uuid,uuid,uuid,uuid,timestamptz,bigint,jsonb,jsonb,jsonb,jsonb) to service_role"],"statementSha256":["8e70e246d302bcd04b1fc518bff15cb45448dc92c37c8b6435118f005a5c40f3","7ad473d59db6f855dbc8476ac0b8b8a4d6c9f7b505f35e893e46aa1da5d3c7a8","584f535527563195a642997e8d210b55a8139c2ae6f9928242209f9a41ab2f0e","cc7583abe9e6035702db20ea0498ac7468123fdaa541e9cf8c938469e4a33ca2","99543d168cd41892aed33c6b3ee0f37379cd7a3993a549729bea84dbf0c872f8","9e0e4736d8915eefdbf229d78cd821e1134fb401159f56551403ef3cf41256ee","19b4e8bfef4ed1e41cdde225f5cf5407f13759351a6d9480843da2236de099d5","47a494a511ef9b07e73ac3f855876c3bbc6f110dc1596b6799fdb8135b4f5270","da018f9e14206495bc355e672502babc5a1c69e11296a990a791fedfe9cfd6e3","7d255d0ac690cffaa3335f9d0f1b1462ab99c6e8f5db9c426dcf17a3c16f42c8","cd9381093983d76cfe743bda4431f53af3632651f22cecc1d1a2d2d83d7e254e"]},{"version":"20261020080002","name":"studio_authored_create","rawSha256":"5c2fb88ca68177963b09b648f1517bb9008136ecbc5535aded3f10923e143b71","canonicalLfSha256":"5c2fb88ca68177963b09b648f1517bb9008136ecbc5535aded3f10923e143b71","statements":["-- Install-only unpriced studio creation. Requires studio_authored_save guards.\n-- Canonical nested geometry/options validation belongs to the trusted server.\ndo $$ begin\n  if to_regprocedure('public.studio_authored_save(uuid,uuid,uuid,uuid,timestamptz,bigint,jsonb,jsonb,jsonb,jsonb)') is null\n    or not exists(select 1 from pg_trigger where tgrelid='public.quote_versions'::regclass and tgname='studio_quote_source_guard' and tgenabled<>'D')\n    or not exists(select 1 from pg_trigger where tgrelid='public.estimates'::regclass and tgname='studio_estimate_write_guard' and tgenabled<>'D') then\n    raise exception 'studio_save_guards_required';\n  end if;\nend $$","create table private.studio_authored_create_receipts (\n  project_id uuid not null references public.projects(id),\n  request_id uuid not null,\n  -- Historical identity must survive removal of current Portal membership.\n  -- The command checks current staff access before every write or replay.\n  actor_user_id uuid not null,\n  source_estimate_id uuid references public.estimates(id),\n  client_request jsonb not null,\n  source_snapshot jsonb,\n  estimate_id uuid not null unique references public.estimates(id),\n  design_id text not null,\n  saved_at timestamptz not null,\n  primary key(project_id, request_id)\n)","revoke all on private.studio_authored_create_receipts from public, anon, authenticated, service_role","create function public.studio_authored_create(\n  p_project_id uuid, p_actor_user_id uuid, p_request_id uuid,\n  p_source_estimate_id uuid, p_client_request jsonb, p_prepared jsonb, p_source_proof jsonb\n) returns table(estimate_id uuid, design_id text, revision bigint, saved_at timestamptz, already_existed boolean)\nlanguage plpgsql security definer set search_path = pg_catalog, pg_temp as $$\ndeclare\n  v_receipt private.studio_authored_create_receipts%rowtype;\n  v_source public.estimates%rowtype;\n  v_authored jsonb;\n  v_spatial jsonb;\n  v_outputs jsonb;\n  v_scope uuid;\n  v_version integer;\n  v_id uuid;\n  v_saved_at timestamptz;\n  v_mode text;\n  -- PostgREST optional JSON arguments can arrive as JSON null rather than SQL NULL.\n  v_source_proof jsonb := nullif(p_source_proof,'null'::jsonb);\nbegin\n  if p_project_id is null or p_request_id is null or not exists(\n    select 1 from public.portal_users u where u.user_id=p_actor_user_id and u.role in ('staff','admin')\n  ) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n\n  -- Same key as configured revisions. UUID identity is authoritative: other\n  -- legacy INSERT writers do not share this lock, so display version uniqueness\n  -- across all estimate writers is NOT guaranteed by this command.\n  perform pg_advisory_xact_lock(hashtextextended('configurator-revision:' || p_project_id::text,0));\n  select * into v_receipt from private.studio_authored_create_receipts r\n    where r.project_id=p_project_id and r.request_id=p_request_id;\n  if found then\n    if v_receipt.actor_user_id is distinct from p_actor_user_id\n      or v_receipt.source_estimate_id is distinct from p_source_estimate_id\n      or v_receipt.client_request is distinct from p_client_request then\n      raise exception 'studio_request_conflict' using errcode='23505';\n    end if;\n    return query select v_receipt.estimate_id,v_receipt.design_id,1::bigint,v_receipt.saved_at,true;\n    return;\n  end if;\n\n  perform 1 from public.projects p where p.id=p_project_id and p.archived_at is null for update;\n  if not found then raise exception 'studio_project_unavailable' using errcode='P0002'; end if;\n  if jsonb_typeof(p_client_request) is distinct from 'object' or octet_length(p_client_request::text)>2097152 then\n    raise exception 'studio_invalid_creation' using errcode='22023';\n  end if;\n  v_mode := p_client_request->>'mode';\n  if p_client_request->>'schemaVersion' is distinct from 'studio_create.v1'\n    or p_client_request->>'requestId' is distinct from p_request_id::text\n    or v_mode is null or v_mode not in ('blank','clone','import') then\n    raise exception 'studio_invalid_creation' using errcode='22023';\n  end if;\n  if jsonb_typeof(p_prepared) is distinct from 'object' or octet_length(p_prepared::text)>2097152 then\n    raise exception 'studio_invalid_creation' using errcode='22023';\n  end if;\n  if (select count(*) from jsonb_object_keys(p_prepared))<>(5 + case when p_prepared ? 'internal_name' then 1 else 0 end)\n    or not(p_prepared ?& array['project_id','commercial_scope_id','status','inputs','outputs'])\n    or p_prepared->>'project_id' is distinct from p_project_id::text\n    or p_prepared->>'status' is distinct from 'draft'\n    or jsonb_typeof(p_prepared->'inputs') is distinct from 'object'\n    or jsonb_typeof(p_prepared->'outputs') is distinct from 'object'\n    or not (p_prepared->'commercial_scope_id'='null'::jsonb or jsonb_typeof(p_prepared->'commercial_scope_id')='string') then\n    raise exception 'studio_invalid_creation' using errcode='22023';\n  end if;\n  if p_prepared ? 'internal_name' and p_prepared->'internal_name'<>'null'::jsonb and (\n    jsonb_typeof(p_prepared->'internal_name') is distinct from 'string'\n    or length(p_prepared->>'internal_name')>120\n    or nullif(btrim(p_prepared->>'internal_name'),'') is null\n  ) then raise exception 'studio_invalid_creation' using errcode='22023'; end if;\n  v_scope := (p_prepared->>'commercial_scope_id')::uuid;\n  v_outputs := p_prepared->'outputs';\n  v_authored := v_outputs->'studio_authored';\n  v_spatial := v_outputs->'drawing_object_first';\n  if jsonb_typeof(v_authored) is distinct from 'object' or jsonb_typeof(v_spatial) is distinct from 'object' then\n    raise exception 'studio_invalid_creation' using errcode='22023';\n  end if;\n  if (select count(*) from jsonb_object_keys(v_authored))<>8\n    or not(v_authored ?& array['schemaVersion','designId','revision','spatialOutputKey','site','objectOptions','legacyCommercialAssociations','provenance'])\n    or v_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n    or v_authored->>'spatialOutputKey' is distinct from 'drawing_object_first'\n    or v_authored->'revision' is distinct from '1'::jsonb\n    or jsonb_typeof(v_authored->'designId') is distinct from 'string'\n    or nullif(btrim(v_authored->>'designId'),'') is null or length(v_authored->>'designId')>200\n    or (select count(*) from jsonb_object_keys(v_spatial))<>4\n    or not(v_spatial ?& array['houseAssembly','decks','openings','pergolas'])\n    or jsonb_typeof(v_spatial->'decks') is distinct from 'array'\n    or jsonb_typeof(v_spatial->'openings') is distinct from 'array'\n    or jsonb_typeof(v_spatial->'pergolas') is distinct from 'array' then\n    raise exception 'studio_invalid_creation' using errcode='22023';\n  end if;\n\n  if v_mode='blank' then\n    if (select count(*) from jsonb_object_keys(p_client_request))<>(4 + case when p_client_request ? 'internalName' then 1 else 0 end)\n      or not(p_client_request ?& array['schemaVersion','requestId','mode','scope'])\n      or p_client_request->>'scope' is null or p_client_request->>'scope' not in ('base','add_on')\n      or p_source_estimate_id is not null or v_source_proof is not null\n      or (p_client_request->>'scope'='base') is distinct from (v_scope is null)\n      or p_prepared->'inputs' is distinct from '{}'::jsonb\n      or coalesce(p_prepared->'internal_name','null'::jsonb) is distinct from coalesce(p_client_request->'internalName','null'::jsonb)\n      or (v_outputs - 'studio_authored' - 'drawing_object_first')<>'{}'::jsonb\n      or v_spatial is distinct from '{\"houseAssembly\":null,\"decks\":[],\"openings\":[],\"pergolas\":[]}'::jsonb\n      or (v_authored - 'designId') is distinct from '{\"schemaVersion\":\"studio_authored.v1\",\"revision\":1,\"spatialOutputKey\":\"drawing_object_first\",\"site\":{\"validation\":\"preserved_unvalidated\",\"values\":{}},\"objectOptions\":[],\"legacyCommercialAssociations\":[],\"provenance\":{\"sourceEstimateId\":null,\"sourceKind\":\"authored\",\"sourcePayload\":null}}'::jsonb then\n      raise exception 'studio_invalid_creation' using errcode='22023';\n    end if;\n    if v_scope is not null and (exists(select 1 from public.estimates e where e.project_id=p_project_id and e.commercial_scope_id=v_scope)\n      or exists(select 1 from public.quotes q where q.project_id=p_project_id and q.commercial_scope_id=v_scope)) then\n      raise exception 'studio_scope_conflict' using errcode='PT409';\n    end if;\n  else\n    if (select count(*) from jsonb_object_keys(p_client_request))<>(6 + case when p_client_request ? 'internalName' then 1 else 0 end)\n      or not(p_client_request ?& array['schemaVersion','requestId','mode','sourceEstimateId','expectedUpdatedAt','expectedRevision'])\n      or p_source_estimate_id is null\n      or p_client_request->>'sourceEstimateId' is distinct from ('est_'||p_source_estimate_id::text)\n      or jsonb_typeof(p_client_request->'expectedUpdatedAt') is distinct from 'string'\n      or coalesce(p_client_request->>'expectedUpdatedAt','') !~ '^\\d{4}-\\d{2}-\\d{2}T'\n      or jsonb_typeof(p_client_request->'expectedRevision') is distinct from 'number'\n      or (v_mode='clone' and coalesce(p_client_request->>'expectedRevision','') !~ '^[1-9][0-9]*$')\n      or (v_mode='import' and p_client_request->'expectedRevision' is distinct from '0'::jsonb)\n      or (p_client_request->>'expectedRevision')::numeric>9007199254740991 then\n      raise exception 'studio_invalid_creation' using errcode='22023';\n    end if;\n    select * into v_source from public.estimates e where e.id=p_source_estimate_id and e.project_id=p_project_id for update;\n    if not found then raise exception 'studio_source_unavailable' using errcode='P0002'; end if;\n    if to_jsonb(v_source) is distinct from v_source_proof\n      or v_source.updated_at is distinct from (p_client_request->>'expectedUpdatedAt')::timestamptz\n      or (v_mode='clone' and v_source.outputs->'studio_authored'->'revision' is distinct from p_client_request->'expectedRevision') then\n      raise exception 'studio_stale' using errcode='PT409';\n    end if;\n    if v_source.status not in ('draft','archived')\n      or jsonb_typeof(v_source.outputs) is distinct from 'object'\n      or jsonb_typeof(v_source.inputs) is distinct from 'object'\n      or p_prepared->'inputs' is distinct from v_source.inputs\n      or coalesce(p_prepared->'internal_name','null'::jsonb) is distinct from\n        (case when p_client_request ? 'internalName' then p_client_request->'internalName' else coalesce(to_jsonb(v_source)->'internal_name','null'::jsonb) end)\n      or v_scope is distinct from v_source.commercial_scope_id then\n      raise exception 'studio_invalid_creation' using errcode='22023';\n    end if;\n    if v_mode='clone' then\n      if v_authored->'designId' is not distinct from v_source.outputs->'studio_authored'->'designId'\n        or (v_authored - 'designId' - 'revision') is distinct from ((v_source.outputs->'studio_authored') - 'designId' - 'revision')\n        or (v_outputs - 'studio_authored') is distinct from (v_source.outputs - 'studio_authored') then\n        raise exception 'studio_invalid_creation' using errcode='22023';\n      end if;\n    else\n      -- Explicit historical import only. The trusted server validates every\n      -- supported selection; SQL binds it to the locked original.\n      -- No quote/source mutation or inference of missing pergola geometry.\n      if v_source.outputs ? 'studio_authored'\n        or v_source.inputs->>'schemaVersion' is distinct from 'v2'\n        or jsonb_typeof(v_source.inputs->'modules') is distinct from 'array'\n        or (v_source.outputs ? 'drawing_object_first' and v_source.outputs->'drawing_object_first' is distinct from v_spatial)\n        or (v_outputs - 'studio_authored' - 'drawing_object_first') is distinct from (v_source.outputs - 'drawing_object_first')\n        or v_authored->'site' is distinct from jsonb_build_object('validation','preserved_unvalidated','values',v_source.inputs - array['schemaVersion','projectName','quoteRef','modules','pergolas'])\n        or v_authored->'provenance' is distinct from jsonb_build_object('sourceEstimateId','est_'||p_source_estimate_id::text,'sourceKind','imported','sourcePayload',to_jsonb(v_source)) then\n        raise exception 'studio_invalid_creation' using errcode='22023';\n      end if;\n      if jsonb_array_length(v_source.inputs->'modules')=0 then\n        if (v_source.inputs ? 'pergolas' and v_source.inputs->'pergolas' is distinct from '[]'::jsonb)\n          or v_spatial is distinct from '{\"houseAssembly\":null,\"decks\":[],\"openings\":[],\"pergolas\":[]}'::jsonb\n          or v_authored->'objectOptions' is distinct from '[]'::jsonb\n          or v_authored->'legacyCommercialAssociations' is distinct from '[]'::jsonb then\n          raise exception 'studio_invalid_creation' using errcode='22023';\n        end if;\n      else\n        -- Existing singleton scene/module agreement is checked by the import\n        -- owner. This binds the new explicit association to that same scene;\n        -- a module index is never accepted as a runtime object identity.\n        if jsonb_array_length(v_source.inputs->'modules')<>1\n          or jsonb_array_length(v_spatial->'pergolas')<>1\n          or v_source.outputs->'drawing_object_first' is distinct from v_spatial\n          or v_spatial->'houseAssembly' is distinct from 'null'::jsonb\n          or v_spatial->'decks' is distinct from '[]'::jsonb\n          or v_spatial->'openings' is distinct from '[]'::jsonb\n          or jsonb_typeof(v_authored->'objectOptions') is distinct from 'array'\n          or jsonb_typeof(v_authored->'legacyCommercialAssociations') is distinct from 'array' then\n          raise exception 'studio_invalid_creation' using errcode='22023';\n        end if;\n        if jsonb_array_length(v_authored->'objectOptions')<>1\n          or v_authored#>'{objectOptions,0,objectId}' is distinct from v_spatial#>'{pergolas,0,id}'\n          or v_authored#>>'{objectOptions,0,options,validation}' is distinct from 'preserved_unvalidated'\n          or jsonb_typeof(v_authored#>'{objectOptions,0,options,values}') is distinct from 'object' then\n          raise exception 'studio_invalid_creation' using errcode='22023';\n        end if;\n        if exists(select 1 from jsonb_each(v_authored#>'{objectOptions,0,options,values}') as option\n          where option.value is distinct from (v_source.inputs#>'{modules,0}')->option.key) then\n          raise exception 'studio_invalid_creation' using errcode='22023';\n        end if;\n        if not(v_source.inputs ? 'pergolas') or v_source.inputs->'pergolas'='[]'::jsonb then\n          if v_authored->'legacyCommercialAssociations' is distinct from '[]'::jsonb then\n            raise exception 'studio_invalid_creation' using errcode='22023';\n          end if;\n        else\n          if jsonb_typeof(v_source.inputs->'pergolas') is distinct from 'array' then\n            raise exception 'studio_invalid_creation' using errcode='22023';\n          end if;\n          if jsonb_array_length(v_source.inputs->'pergolas')<>1\n            or v_source.inputs#>'{modules,0,pergolaId}' is distinct from v_source.inputs#>'{pergolas,0,id}'\n            or v_authored->'legacyCommercialAssociations' is distinct from jsonb_build_array(jsonb_build_object(\n              'authority','preserved_legacy_only','id',v_source.inputs#>'{pergolas,0,id}',\n              'label',v_source.inputs#>'{pergolas,0,label}','objectIds',jsonb_build_array(v_spatial#>'{pergolas,0,id}'),\n              'options',jsonb_build_object('validation','preserved_unvalidated','values',(v_source.inputs#>'{pergolas,0}') - array['id','label'])\n            )) then raise exception 'studio_invalid_creation' using errcode='22023'; end if;\n        end if;\n      end if;\n    end if;\n  end if;\n\n  select coalesce(max(e.version),0)+1 into v_version from public.estimates e where e.project_id=p_project_id;\n  if v_outputs ? 'version' then v_outputs := jsonb_set(v_outputs,'{version}',to_jsonb(v_version)); end if;\n  -- No copied financial summary, costing configuration, or quote mutation.\n  insert into public.estimates(project_id,commercial_scope_id,status,version,created_by,inputs,outputs,internal_name)\n    values(p_project_id,v_scope,'draft',v_version,p_actor_user_id::text,p_prepared->'inputs',v_outputs,p_prepared->>'internal_name')\n    returning id,updated_at into v_id,v_saved_at;\n  insert into private.studio_authored_create_receipts(project_id,request_id,actor_user_id,source_estimate_id,client_request,source_snapshot,estimate_id,design_id,saved_at)\n    values(p_project_id,p_request_id,p_actor_user_id,p_source_estimate_id,p_client_request,v_source_proof,v_id,v_authored->>'designId',v_saved_at);\n  return query select v_id,v_authored->>'designId',1::bigint,v_saved_at,false;\nend;\n$$","revoke all on function public.studio_authored_create(uuid,uuid,uuid,uuid,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_authored_create(uuid,uuid,uuid,uuid,jsonb,jsonb,jsonb) to service_role"],"statementSha256":["6a4aaedcd8ffb9004e58ae304dc1c00d9f8c4bf549c310282f58d0e9864b2cdf","d8044291cc935ee063bc6a1dd376dea4e14551dfc83172965c601cc37bd34991","07e86ee005b46a7fbf07d8374f64caa16783fec81354f81dde411e75bfd12de7","5b41e11360b97b3044cf8b11e9977ad599b0425f0214ed70ae3c65565f0dd62d","40fc45afd1f4a151358dea98f3d949cf59d4f994e39d7d57d31769886b95f5dc","3618e0cea78d2842d4e0f6aa458e92b8a221c7c5665b71831c316b1991edc6e8"]},{"version":"20261020080003","name":"studio_website_quote_snapshot","rawSha256":"a712482db41995328e6c0ac074c24a034af8d5f7badb2c400391582a29c4e9a1","canonicalLfSha256":"6407d519dd4555f29447cc1e940a0d8231dec380de8caa183119f1c1cb3319af","statements":["-- Website Studio V1: immutable design and image bytes, explicit commercial handoff.\n-- Depends on current commercial RPCs and studio_authored_save/create foundations.\ncreate table private.studio_website_quote_snapshots (\n  id uuid primary key,\n  project_id uuid not null references public.projects(id),\n  estimate_id uuid not null references public.estimates(id),\n  commercial_scope_id uuid,\n  actor_user_id uuid not null,\n  content_hash text not null check (content_hash ~ '^[0-9a-f]{64}$'),\n  authored jsonb not null,\n  spatial jsonb not null,\n  publication_id uuid not null,\n  handoff jsonb not null,\n  private_evidence jsonb not null,\n  customer_view jsonb not null,\n  created_at timestamptz not null default clock_timestamp()\n)","create table private.studio_website_quote_bindings (\n  quote_version_id uuid primary key references public.quote_versions(id) on delete cascade,\n  snapshot_id uuid not null references private.studio_website_quote_snapshots(id),\n  bound_at timestamptz not null default clock_timestamp()\n)","revoke all on private.studio_website_quote_snapshots, private.studio_website_quote_bindings from public,anon,authenticated,service_role","create function private.studio_snapshot_immutable() returns trigger language plpgsql\nset search_path=pg_catalog,pg_temp as $$ begin raise exception 'studio_snapshot_immutable' using errcode='55000'; end $$","create trigger studio_snapshot_immutable before update or delete on private.studio_website_quote_snapshots\nfor each row execute function private.studio_snapshot_immutable()","revoke all on function private.studio_snapshot_immutable() from public,anon,authenticated,service_role","create function public.studio_website_quote_prepare(\n p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,\n p_expected_updated_at timestamptz,p_authored jsonb,p_spatial jsonb,p_publication_id uuid,\n p_content_hash text,p_handoff jsonb,p_private_evidence jsonb,p_customer_view jsonb\n) returns table(snapshot_id uuid,prepared_at timestamptz)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare e public.estimates%rowtype; previous text; saved_at timestamptz; replay private.studio_website_quote_snapshots%rowtype; item jsonb; kind text;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then\n  raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into e from public.estimates where id=p_estimate_id and project_id=p_project_id for update;\n if not found or e.status<>'draft' then raise exception 'studio_estimate_unavailable'; end if;\n select * into replay from private.studio_website_quote_snapshots where id=p_snapshot_id;\n if found then\n  if replay.estimate_id is distinct from e.id or replay.actor_user_id is distinct from p_actor_user_id or replay.content_hash is distinct from p_content_hash or replay.customer_view is distinct from p_customer_view or replay.handoff is distinct from p_handoff or replay.authored is distinct from p_authored or replay.spatial is distinct from p_spatial or replay.publication_id is distinct from p_publication_id or replay.private_evidence is distinct from p_private_evidence then raise exception 'studio_prepare_intent_conflict'; end if;\n  return query select replay.id,replay.created_at; return;\n end if;\n if exists(select 1 from public.quote_versions where source_estimate_version_id=e.id) then raise exception 'studio_estimate_referenced'; end if;\n if e.updated_at is distinct from p_expected_updated_at or e.outputs->'studio_authored' is distinct from p_authored\n  or e.outputs->'drawing_object_first' is distinct from p_spatial then raise exception 'studio_stale' using errcode='PT409'; end if;\n perform 1 from public.costing_configuration_publication where singleton and current_version_id=p_publication_id for share;\n if not found then raise exception 'studio_publication_changed' using errcode='PT409'; end if;\n if p_snapshot_id is null or p_publication_id is null or p_content_hash is null or p_content_hash !~ '^[0-9a-f]{64}$'\n  or jsonb_typeof(p_authored) is distinct from 'object' or jsonb_typeof(p_spatial) is distinct from 'object'\n  or jsonb_typeof(p_private_evidence) is distinct from 'object' or jsonb_typeof(p_customer_view) is distinct from 'object'\n  or jsonb_typeof(p_handoff) is distinct from 'object'\n  or p_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n  or p_customer_view->>'schemaVersion' is distinct from 'studio_quote_snapshot.v1'\n  or p_handoff->>'schemaVersion' is distinct from 'studio_quote_snapshot.v1'\n  or p_customer_view->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_handoff->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_customer_view->>'contentHash' is distinct from p_content_hash\n  or p_handoff->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_customer_view->'images') is distinct from 'array'\n  or jsonb_typeof(p_customer_view->'selections') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'lines') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'totalIncGstCents') is distinct from 'number'\n  or jsonb_typeof(p_handoff->'source') is distinct from 'object'\n  or octet_length(p_customer_view::text)>8388608 then raise exception 'studio_snapshot_invalid'; end if;\n if jsonb_array_length(p_customer_view->'images')<>2 or jsonb_array_length(p_handoff->'lines')<1\n  or (p_handoff->>'totalIncGstCents')::bigint<=0 then raise exception 'studio_snapshot_invalid'; end if;\n for item in select value from jsonb_array_elements(p_customer_view->'images') loop\n  if jsonb_typeof(item) is distinct from 'object' or item->>'kind' is null or item->>'kind' not in ('plan','perspective')\n   or item->>'sha256' is null or item->>'sha256' !~ '^[0-9a-f]{64}$'\n   or item->>'dataUrl' is null or item->>'dataUrl' !~ '^data:image/png;base64,[A-Za-z0-9+/]+=*$'\n   or length(item->>'dataUrl')<100 or length(item->>'dataUrl')>3800000\n   or jsonb_typeof(item->'width') is distinct from 'number' or jsonb_typeof(item->'height') is distinct from 'number'\n   then raise exception 'studio_snapshot_images_invalid'; end if;\n  if (item->>'width')::numeric not between 640 and 2400 or (item->>'height')::numeric not between 400 and 1800 then raise exception 'studio_snapshot_images_invalid'; end if;\n end loop;\n if (select count(distinct value->>'kind') from jsonb_array_elements(p_customer_view->'images'))<>2 then raise exception 'studio_snapshot_images_invalid'; end if;\n for item in select value from jsonb_array_elements(p_handoff->'lines') loop\n  if jsonb_typeof(item) is distinct from 'object' or coalesce(trim(item->>'description'),'')=''\n   or item->'qty' is distinct from '1'::jsonb or jsonb_typeof(item->'sortOrder') is distinct from 'number'\n   or jsonb_typeof(item->'unitPriceIncGstCents') is distinct from 'number'\n   or item->'lineTotalIncGstCents' is distinct from item->'unitPriceIncGstCents'\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n  if (item->>'unitPriceIncGstCents')::numeric<0 or (item->>'unitPriceIncGstCents')::numeric<>trunc((item->>'unitPriceIncGstCents')::numeric)\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n end loop;\n if (select sum((value->>'lineTotalIncGstCents')::bigint) from jsonb_array_elements(p_handoff->'lines')) is distinct from (p_handoff->>'totalIncGstCents')::bigint\n  or exists(select 1 from jsonb_array_elements(p_handoff->'lines') with ordinality line(value,n) where (value->>'sortOrder')::numeric<>n-1)\n  then raise exception 'studio_snapshot_lines_invalid'; end if;\n insert into private.studio_website_quote_snapshots(id,project_id,estimate_id,commercial_scope_id,actor_user_id,content_hash,\n  authored,spatial,publication_id,handoff,private_evidence,customer_view)\n values(p_snapshot_id,e.project_id,e.id,e.commercial_scope_id,p_actor_user_id,p_content_hash,p_authored,p_spatial,p_publication_id,p_handoff,p_private_evidence,p_customer_view);\n previous:=current_setting('sanctuary.studio_command',true);\n perform set_config('sanctuary.studio_command','save',true);\n update public.estimates set outputs=outputs||jsonb_build_object('studio_quote_handoff',p_handoff),\n  pricing_source='workbench_solved',pricing_source_metadata=jsonb_build_object('studioSnapshotId',p_snapshot_id,'studioSnapshotHash',p_content_hash),\n  updated_at=clock_timestamp() where id=e.id returning updated_at into saved_at;\n perform set_config('sanctuary.studio_command',coalesce(previous,''),true);\n return query select id,created_at from private.studio_website_quote_snapshots where id=p_snapshot_id;\nend $$","revoke all on function public.studio_website_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_website_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb) to service_role","-- Current commercial owners continue to take the quote lock first, then the estimate.\n-- This trigger is an invariant backstop. Binding is performed by the wrapper only.\ncreate or replace function private.studio_quote_source_guard() returns trigger\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare e public.estimates%rowtype; s private.studio_website_quote_snapshots%rowtype;\nbegin\n if tg_op='UPDATE' and new.source_estimate_version_id is not distinct from old.source_estimate_version_id then return new; end if;\n if new.source_estimate_version_id is null then return new; end if;\n select * into e from public.estimates where id=new.source_estimate_version_id for update;\n if e.outputs ? 'studio_authored' then\n  select * into s from private.studio_website_quote_snapshots where id=nullif(current_setting('sanctuary.studio_quote_snapshot',true),'')::uuid;\n  if not found or s.estimate_id<>e.id or s.project_id<>(select project_id from public.quotes where id=new.quote_id)\n   or s.commercial_scope_id is distinct from (select commercial_scope_id from public.quotes where id=new.quote_id) then\n   raise exception 'studio_costing_required' using errcode='23514'; end if;\n end if;\n return new;\nend $$","create function public.studio_website_quote_commit(p_operation text,p_snapshot_id uuid,p_content_hash text,p_command jsonb)\nreturns public.quote_versions language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare s private.studio_website_quote_snapshots%rowtype; q public.quote_versions%rowtype;\n existing public.quote_versions%rowtype; source public.quote_versions%rowtype; e public.estimates%rowtype;\n previous text; v_quote_id uuid; command_lines jsonb; actual_lines jsonb; prior_snapshot uuid;\nbegin\n if p_operation is null or p_operation not in ('create','refresh','revise') or jsonb_typeof(p_command) is distinct from 'object' then raise exception 'studio_quote_command_invalid'; end if;\n select * into s from private.studio_website_quote_snapshots where id=p_snapshot_id and content_hash=p_content_hash;\n if not found then raise exception 'studio_snapshot_unavailable'; end if;\n if p_operation='refresh' then\n  select * into strict existing from public.quote_versions where id=(p_command->>'p_quote_version_id')::uuid for update;\n  v_quote_id:=existing.quote_id;\n else\n  v_quote_id:=(p_command->>'p_quote_id')::uuid;\n  perform pg_advisory_xact_lock(hashtextextended('commercial-quote:'||v_quote_id::text,0));\n  if exists(select 1 from public.quote_versions qv where qv.quote_id=v_quote_id and qv.status='DRAFT' and qv.is_current_draft and (qv.pricing_source_metadata ? 'studioQuoteDraft')) then raise exception 'Historical Studio quote drafts are review-only. Create the new Studio quote in a separate scope.'; end if;\n  select * into existing from public.quote_versions where quote_id=v_quote_id and client_intent_id=trim(p_command->>'p_client_intent_id') for update;\n  if found then\n   select snapshot_id into prior_snapshot from private.studio_website_quote_bindings where quote_version_id=existing.id;\n   if prior_snapshot is distinct from p_snapshot_id or existing.source_estimate_version_id is distinct from s.estimate_id then raise exception 'studio_quote_intent_conflict' using errcode='23505'; end if;\n   return existing;\n  end if;\n end if;\n if s.project_id is distinct from (select project_id from public.quotes where id=v_quote_id)\n  or s.commercial_scope_id is distinct from (select commercial_scope_id from public.quotes where id=v_quote_id)\n  or (p_command->>'p_source_estimate_version_id')::uuid is distinct from s.estimate_id then raise exception 'studio_snapshot_scope_mismatch'; end if;\n if p_operation='revise' then\n  select * into strict source from public.quote_versions where id=(p_command->>'p_revised_from_quote_version_id')::uuid;\n  if source.quote_id<>v_quote_id or source.status='DRAFT' or not exists(select 1 from private.studio_website_quote_bindings where quote_version_id=source.id and snapshot_id=s.id) then raise exception 'studio_revision_binding_missing'; end if;\n end if;\n command_lines:=p_command->'p_line_items';\n if p_operation='create' and command_lines is distinct from (select jsonb_agg(jsonb_build_object(\n  'description',item->'description','qty',item->'qty','unit_price_inc_gst_cents',item->'unitPriceIncGstCents',\n  'line_total_inc_gst_cents',item->'lineTotalIncGstCents','sort_order',item->'sortOrder') order by (item->>'sortOrder')::integer)\n  from jsonb_array_elements(s.handoff->'lines') item) then raise exception 'studio_quote_lines_changed'; end if;\n previous:=current_setting('sanctuary.studio_quote_snapshot',true);\n perform set_config('sanctuary.studio_quote_snapshot',s.id::text,true);\n if p_operation='refresh' then\n  q:=public.commercial_quote_update_draft((p_command->>'p_quote_version_id')::uuid,(p_command->>'p_expected_commercial_revision')::bigint,\n   p_command->>'p_reference',p_command->>'p_intro_text',p_command->>'p_terms_text',(p_command->>'p_deposit_percent')::numeric,p_command->'p_payment_terms',\n   (p_command->>'p_expires_at')::date,s.estimate_id,(p_command->>'p_total_inc_gst_cents')::integer,(p_command->>'p_total_ex_gst_cents')::integer,\n   (p_command->>'p_gst_cents')::integer,p_command->>'p_pricing_source',p_command->'p_pricing_source_metadata',command_lines);\n else\n  q:=public.commercial_quote_create_draft(v_quote_id,s.estimate_id,(p_command->>'p_revised_from_quote_version_id')::uuid,\n   p_command->>'p_client_intent_id',p_command->>'p_actor',p_command->>'p_customer_name',p_command->>'p_reference',p_command->>'p_intro_text',\n   p_command->>'p_terms_text',(p_command->>'p_deposit_percent')::numeric,p_command->'p_payment_terms',(p_command->>'p_expires_at')::date,\n   (p_command->>'p_total_inc_gst_cents')::integer,(p_command->>'p_total_ex_gst_cents')::integer,(p_command->>'p_gst_cents')::integer,\n   p_command->>'p_pricing_source',p_command->'p_pricing_source_metadata',command_lines);\n end if;\n -- The delegated owner has locked prior draft rows before its INSERT source guard locks the estimate.\n -- Validate within this same transaction, rolling back all quote changes on a stale source.\n if p_operation<>'revise' then\n  select * into strict e from public.estimates where id=s.estimate_id for update;\n  if e.outputs->'studio_authored' is distinct from s.authored or e.outputs->'drawing_object_first' is distinct from s.spatial\n   or e.outputs->'studio_quote_handoff' is distinct from s.handoff then raise exception 'studio_snapshot_stale' using errcode='PT409'; end if;\n  perform 1 from public.costing_configuration_publication where singleton and current_version_id=s.publication_id for share;\n  if not found then raise exception 'studio_publication_changed' using errcode='PT409'; end if;\n end if;\n select jsonb_agg(jsonb_build_object('description',description,'qty',qty,'unit_price_inc_gst_cents',unit_price_inc_gst_cents,\n  'line_total_inc_gst_cents',line_total_inc_gst_cents,'sort_order',sort_order) order by sort_order) into actual_lines\n from public.quote_line_items where quote_version_id=q.id;\n if actual_lines is distinct from command_lines or q.total_inc_gst_cents<>(select sum(line_total_inc_gst_cents) from public.quote_line_items where quote_version_id=q.id)\n  then raise exception 'studio_quote_reconciliation_failed'; end if;\n insert into private.studio_website_quote_bindings(quote_version_id,snapshot_id) values(q.id,s.id)\n on conflict(quote_version_id) do update set snapshot_id=excluded.snapshot_id,bound_at=clock_timestamp();\n perform set_config('sanctuary.studio_quote_snapshot',coalesce(previous,''),true);\n return q;\nend $$","revoke all on function public.studio_website_quote_commit(text,uuid,text,jsonb) from public,anon,authenticated","grant execute on function public.studio_website_quote_commit(text,uuid,text,jsonb) to service_role","create function public.studio_website_quote_view(p_quote_version_id uuid) returns jsonb\nlanguage sql stable security definer set search_path=pg_catalog,pg_temp as $$\n select s.customer_view from private.studio_website_quote_bindings b\n join private.studio_website_quote_snapshots s on s.id=b.snapshot_id where b.quote_version_id=p_quote_version_id\n$$","revoke all on function public.studio_website_quote_view(uuid) from public,anon,authenticated","grant execute on function public.studio_website_quote_view(uuid) to service_role","-- Deferred check runs after line insertion and binding in the same transaction.\ncreate function private.studio_quote_binding_required() returns trigger language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare current_quote public.quote_versions%rowtype; binding private.studio_website_quote_snapshots%rowtype; marked boolean;\nbegin\n select * into current_quote from public.quote_versions where id=new.id;\n if not found then return null; end if;\n select s.* into binding from private.studio_website_quote_bindings b join private.studio_website_quote_snapshots s on s.id=b.snapshot_id where b.quote_version_id=current_quote.id;\n select coalesce(outputs ? 'studio_authored',false) into marked from public.estimates where id=current_quote.source_estimate_version_id;\n if marked and binding.id is null then raise exception 'studio_quote_binding_required'; end if;\n if binding.id is not null and (binding.estimate_id is distinct from current_quote.source_estimate_version_id\n  or binding.project_id is distinct from (select project_id from public.quotes where id=current_quote.quote_id)) then raise exception 'studio_quote_binding_mismatch'; end if;\n return null;\nend $$","revoke all on function private.studio_quote_binding_required() from public,anon,authenticated,service_role","create constraint trigger studio_quote_binding_required after insert or update of source_estimate_version_id on public.quote_versions\n deferrable initially deferred for each row execute function private.studio_quote_binding_required()","notify pgrst,'reload schema'"],"statementSha256":["0a1ea6082a82052cfc7529665503cab7bae98b15e86e4c03f191a8470b797ec2","bf5110d9070986de86b3f04a687e51b482ac0901112b6737e81ac1ed649b19a1","c71614ddd334c37e5a3744145c08c5bcf65997292a4beb1329abf808fc94c7fb","fc789b84b3107b932c2abcb22e5979ec631e499bfa7c116cf2c243ad6bbcffbc","f68a9d87d0d63c12bb9ef15a752a49ac93a1b8c74f869853774ec33c63d51dca","b8e67cd5f24ec13451de8fa13f0719267bc540b69279dc2c406266c9da432c18","e9e8af1a8fbdcadae8b4e9397a739709ca88fd1db5c4de2c9e1cd5706ced4513","3f9071d126ff367c3a1cf53852aae0adc654ab38499b13cb5593154b055c1958","2b6bbd1579b2a5ca348fc62ea76d219876b4b24ad7931289df906321914a342d","1d14dcf80d4419a1caac28a1e0da2703248bdaebe766960ffa8d61c41a0d5a95","3df67aec569a0202ed664aa1d5557bbd872841458f6ff51323abdd6806c8c5da","b193c07c98c7ece346fcc9e19d184f0db5c7232565dd359c28977a76b74a8fac","a32865d6cee3d2e40543acbe04e49c6f70602d91f97db622a502f336b64f3ff0","bcd26bd90df18c1032ad452ae7181cb558c9cfd35ec75ecab2ba66581ea808a2","00c69404111e5ffc4ee49c9db64e193e9c972f051cd14bf0d3784def945d9cb7","ec785ab85de4c847fdfacc0eea90ace612df011c402b5cde0e89d0a231f67191","a2cd6da9c23c73e51837a2732f37398b24dad5841cc440bc834e8f06b08135a3","063fa1e855afdd07667b6ae2d52901be674f63d0097d953fcb692734109a6cf3","f51619498503172da82381077141b088c3b128d90d8753b90c4566af38e85271","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c"]},{"version":"20261020080004","name":"studio_quote_binding_metadata","rawSha256":"3ad2e3798d9cda110316308d67c37dc8e7dfd2499677e4ef6a4ffd2567616e80","canonicalLfSha256":"3c65f34e2a123e17e65a885056463bf2ac9fd2c81b94749878d870484e61f5db","statements":["-- Preserve frozen design identity through generic commercial edits.\n-- Deferred check runs after line insertion and binding in the same transaction.\ncreate or replace function private.studio_quote_binding_required() returns trigger language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare current_quote public.quote_versions%rowtype; binding private.studio_website_quote_snapshots%rowtype; marked boolean;\nbegin\n select * into current_quote from public.quote_versions where id=new.id;\n if not found then return null; end if;\n select s.* into binding from private.studio_website_quote_bindings b join private.studio_website_quote_snapshots s on s.id=b.snapshot_id where b.quote_version_id=current_quote.id;\n select coalesce(outputs ? 'studio_authored',false) into marked from public.estimates where id=current_quote.source_estimate_version_id;\n if marked and binding.id is null then raise exception 'studio_quote_binding_required'; end if;\n if binding.id is not null and (binding.estimate_id is distinct from current_quote.source_estimate_version_id\n  or binding.project_id is distinct from (select project_id from public.quotes where id=current_quote.quote_id)\n  or binding.commercial_scope_id is distinct from (select commercial_scope_id from public.quotes where id=current_quote.quote_id)\n  or current_quote.pricing_source_metadata->>'studioSnapshotId' is distinct from binding.id::text\n  or current_quote.pricing_source_metadata->>'studioSnapshotHash' is distinct from binding.content_hash) then raise exception 'studio_quote_binding_mismatch'; end if;\n return null;\nend $$","revoke all on function private.studio_quote_binding_required() from public,anon,authenticated,service_role","drop trigger studio_quote_binding_required on public.quote_versions","create constraint trigger studio_quote_binding_required after insert or update of source_estimate_version_id,pricing_source,pricing_source_metadata,quote_id on public.quote_versions\n deferrable initially deferred for each row execute function private.studio_quote_binding_required()","notify pgrst,'reload schema'"],"statementSha256":["89c161a996f035ca65bf647a36461a8b8dae6445356114c509e87e6ff25ef70c","063fa1e855afdd07667b6ae2d52901be674f63d0097d953fcb692734109a6cf3","aa6212e142e36c1c590681b575519df91b2d721aee331ce056816bfaf9930adb","0147fbcccdb4d7e218109bed7068cdd97ad4138a782b84111e4e321cea00a506","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c"]},{"version":"20261027234904","name":"studio_travel_quote_destination_guard","rawSha256":"158cdd2836f12d6b4d6fd92ee1b7dbedf35b16196e98ce00ccfaf41f532c3c82","canonicalLfSha256":"158cdd2836f12d6b4d6fd92ee1b7dbedf35b16196e98ce00ccfaf41f532c3c82","statements":["-- Deliberately a new RPC: application calls fail closed until this guard exists.\n-- The established commit owner remains unchanged, including source, line and retry checks.\ncreate function public.studio_website_quote_commit_travel(p_operation text,p_snapshot_id uuid,p_content_hash text,p_command jsonb)\nreturns public.quote_versions language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare\n s private.studio_website_quote_snapshots%rowtype;\n q public.quote_versions%rowtype;\n already_committed boolean:=false;\n destination text;\n current_destination text;\n v_quote_id uuid;\n context jsonb;\n automatic boolean;\nbegin\n if p_operation is null or p_operation not in ('create','refresh','revise') or jsonb_typeof(p_command) is distinct from 'object' then raise exception 'studio_quote_command_invalid'; end if;\n select * into s from private.studio_website_quote_snapshots where id=p_snapshot_id and content_hash=p_content_hash;\n if not found then raise exception 'studio_snapshot_unavailable'; end if;\n if p_operation<>'refresh' then\n  v_quote_id:=(p_command->>'p_quote_id')::uuid;\n  -- Same lock as the delegated owner. A retry cannot race a new same-intent commit.\n  perform pg_advisory_xact_lock(hashtextextended('commercial-quote:'||v_quote_id::text,0));\n  select exists(select 1 from public.quote_versions where quote_id=v_quote_id and client_intent_id=trim(p_command->>'p_client_intent_id')) into already_committed;\n end if;\n -- The predecessor checks an existing intent's exact snapshot/source before returning it.\n q:=public.studio_website_quote_commit(p_operation,p_snapshot_id,p_content_hash,p_command);\n if p_operation<>'revise' and not already_committed then\n  automatic:=s.authored#>>'{site,values,travelAllowance,mode}'='automatic';\n  context:=s.customer_view->'travelContext';\n  if coalesce(automatic,false) or s.customer_view ? 'travelContext' then\n   destination:=context->>'destinationCanonical';\n   if not coalesce(automatic,false) or jsonb_typeof(context) is distinct from 'object'\n    or context->>'schemaVersion' is distinct from 'studio_quote_travel.v1'\n    or jsonb_typeof(context->'destinationCanonical') is distinct from 'string'\n    or destination is null or length(trim(destination))=0 or length(destination)>280\n    or (select count(*) from jsonb_object_keys(context))<>2\n    or destination is distinct from s.authored#>>'{site,values,travelAllowance,receipt,destinationCanonical}'\n    then raise exception 'studio_travel_destination_invalid' using errcode='PT409'; end if;\n   -- FOR SHARE conflicts with ordinary site_address UPDATE and holds through commit.\n   -- This follows the predecessor's existing quote -> estimate -> publication lock order.\n   select site_address into current_destination from public.projects where id=s.project_id for share;\n   if not found or current_destination is distinct from destination then raise exception 'studio_travel_destination_changed' using errcode='PT409'; end if;\n  elsif s.authored#>>'{site,values,travelAllowance,mode}'='pending' then\n   raise exception 'studio_travel_calculation_required' using errcode='PT409';\n  end if;\n end if;\n return q;\nend $$","revoke all on function public.studio_website_quote_commit_travel(text,uuid,text,jsonb) from public,anon,authenticated","grant execute on function public.studio_website_quote_commit_travel(text,uuid,text,jsonb) to service_role"],"statementSha256":["5a7f14255dfde7291cd50ab6dc9c4a71aa6b0a46856bcbdfe2708cf274302d53","d691692c97203accb511f9d175e52b9f63e068eb95093448daad596e8a2e37f2","d5d1c327770bebe4965186ad0fde23e1bcec2719e8825f24c6a72262124fd161"]},{"version":"20261028004820","name":"studio_required_quote_site_address","rawSha256":"f5ef3ea8843db19efe517de3ade105f6bcd515ed1e7f05ffae9048f5113c58fc","canonicalLfSha256":"f5ef3ea8843db19efe517de3ade105f6bcd515ed1e7f05ffae9048f5113c58fc","statements":["-- Distinct RPC makes required-address admission fail closed before this migration.\n-- The original commercial/snapshot commit owner and the prior local wrapper remain unchanged.\ncreate function public.studio_website_quote_commit_address(p_operation text,p_snapshot_id uuid,p_content_hash text,p_command jsonb)\nreturns public.quote_versions language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare\n s private.studio_website_quote_snapshots%rowtype;\n q public.quote_versions%rowtype;\n already_committed boolean:=false;\n destination text;\n current_destination text;\n v_quote_id uuid;\n context jsonb;\n proof jsonb;\nbegin\n if p_operation is null or p_operation not in ('create','refresh','revise') or jsonb_typeof(p_command) is distinct from 'object' then raise exception 'studio_quote_command_invalid'; end if;\n select * into s from private.studio_website_quote_snapshots where id=p_snapshot_id and content_hash=p_content_hash;\n if not found then raise exception 'studio_snapshot_unavailable'; end if;\n if p_operation<>'refresh' then\n  v_quote_id:=(p_command->>'p_quote_id')::uuid;\n  perform pg_advisory_xact_lock(hashtextextended('commercial-quote:'||v_quote_id::text,0));\n  select exists(select 1 from public.quote_versions where quote_id=v_quote_id and client_intent_id=trim(p_command->>'p_client_intent_id')) into already_committed;\n end if;\n -- Existing intent binding/source conflicts and frozen revise are still owned by the predecessor.\n q:=public.studio_website_quote_commit(p_operation,p_snapshot_id,p_content_hash,p_command);\n if p_operation<>'revise' and not already_committed then\n  proof:=s.authored#>'{site,values,siteAddressProof}';\n  context:=s.customer_view->'travelContext';\n  if jsonb_typeof(proof) is distinct from 'object' or jsonb_typeof(context) is distinct from 'object' then raise exception 'studio_site_address_required' using errcode='PT409'; end if;\n  destination:=context->>'destinationCanonical';\n  if proof->>'schemaVersion' is distinct from 'studio_selected_address.v1'\n   or proof->>'projectId' is distinct from 'proj_'||s.project_id::text\n   or jsonb_typeof(proof->'destinationCanonical') is distinct from 'string'\n   or proof->>'destinationCanonical' is distinct from destination\n   or coalesce(proof->>'placeId','') !~ '^[A-Za-z0-9_-]{1,255}$'\n   or coalesce(proof->>'proof','') !~ '^[a-f0-9]{64}$'\n   or jsonb_typeof(proof->'issuedAt') is distinct from 'number'\n   or (select count(*) from jsonb_object_keys(proof))<>6\n   or context->>'schemaVersion' is distinct from 'studio_quote_travel.v1'\n   or jsonb_typeof(context->'destinationCanonical') is distinct from 'string'\n   or destination is null or length(trim(destination))=0 or length(destination)>280\n   or (select count(*) from jsonb_object_keys(context))<>2 then raise exception 'studio_site_address_invalid' using errcode='PT409'; end if;\n  if s.authored#>>'{site,values,travelAllowance,mode}'='pending' then raise exception 'studio_travel_calculation_required' using errcode='PT409'; end if;\n  if s.authored#>>'{site,values,travelAllowance,mode}'='automatic' and destination is distinct from s.authored#>>'{site,values,travelAllowance,receipt,destinationCanonical}' then raise exception 'studio_travel_destination_invalid' using errcode='PT409'; end if;\n  -- Server preparation verifies HMAC; immutable snapshot binds it. No DB signing secret.\n  -- FOR SHARE conflicts with ordinary site_address UPDATE and holds through commit.\n  select site_address into current_destination from public.projects where id=s.project_id for share;\n  if not found or current_destination is distinct from destination then raise exception 'studio_site_address_changed' using errcode='PT409'; end if;\n end if;\n return q;\nend $$","revoke all on function public.studio_website_quote_commit_address(text,uuid,text,jsonb) from public,anon,authenticated","grant execute on function public.studio_website_quote_commit_address(text,uuid,text,jsonb) to service_role"],"statementSha256":["d31d7e7448dbfc98d6cd4e555b5ecf9c7ec838ef8071a689b5d2023132c528ae","edfcf5036988ae22c4721caeecb5b0f0cbb7b8a69b941baa8596df7e96086fe7","9a1cfc32184da127be2c3c7f4244ef9094715c53a2ffaa140b242e9e1ff20d0d"]},{"version":"20261028090403","name":"studio_client_documents","rawSha256":"989abaaf9cace29aaa19a3607aff44064ad09fea17a16afb32f81769b9529264","canonicalLfSha256":"0abe9992c24dd1fc1aa12d64384ec394fab32ae65b973b0c064b8f4a26c2ec72","statements":["-- New image-independent Studio documents only. Applying this migration enables\n-- no producer/worker and changes no historical Studio snapshot or customer PDF.\ninsert into public.background_job_kinds(kind,contract_version,handler_owner,max_attempts,timeout_seconds,concurrency_class,has_external_side_effect,required_effect_kinds,cancellation_allowed,default_rollout_mode,active,allowed_effect_kinds)\nvalues('studio_design_booklet_v1',1,'studio-client-documents',3,600,'documents',false,'{}',true,'disabled',true,'{}')","create table private.studio_client_document_control(\n singleton boolean primary key default true check(singleton),enabled boolean not null default false,\n project_ids uuid[] not null default '{}',check(not enabled or cardinality(project_ids)>0)\n)","insert into private.studio_client_document_control(singleton) values(true)","create table private.studio_client_document_sources(\n snapshot_id uuid primary key references private.studio_website_quote_snapshots(id),\n renderer_version text not null check(renderer_version='studio-booklet.v1'),\n drawing_source jsonb not null check(jsonb_typeof(drawing_source)='object' and octet_length(drawing_source::text)<=16777216)\n)","create trigger studio_client_source_immutable before update or delete on private.studio_client_document_sources\nfor each row execute function private.studio_snapshot_immutable()","create table private.studio_client_documents(\n snapshot_id uuid primary key references private.studio_client_document_sources(snapshot_id),\n project_id uuid not null references public.projects(id),quote_version_id uuid not null references public.quote_versions(id),\n renderer_version text not null,job_id uuid unique references public.background_jobs(id),\n total_pages integer not null check(total_pages between 1 and 65),file_id uuid references public.file_artifacts(id),\n enqueue_failed boolean not null default false,created_at timestamptz not null default clock_timestamp(),completed_at timestamptz\n)","create table private.studio_client_document_pages(\n snapshot_id uuid not null references private.studio_client_documents(snapshot_id),page_index integer not null check(page_index between 0 and 64),\n content_hash text not null check(content_hash~'^[a-f0-9]{64}$'),content_base64 text not null check(length(content_base64)<=16777216),\n created_at timestamptz not null default clock_timestamp(),primary key(snapshot_id,page_index)\n)","alter table private.studio_client_document_control enable row level security","alter table private.studio_client_document_sources enable row level security","alter table private.studio_client_documents enable row level security","alter table private.studio_client_document_pages enable row level security","revoke all on private.studio_client_document_control,private.studio_client_document_sources,private.studio_client_documents,private.studio_client_document_pages from public,anon,authenticated,service_role","create function public.studio_client_document_capability(p_project_id uuid,p_actor_user_id uuid)\nreturns boolean language sql stable security definer set search_path=pg_catalog,pg_temp as $$\n select exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin'))\n  and exists(select 1 from private.studio_client_document_control where singleton and enabled and p_project_id=any(project_ids))\n$$","revoke all on function public.studio_client_document_capability(uuid,uuid) from public,anon,authenticated","grant execute on function public.studio_client_document_capability(uuid,uuid) to service_role","-- The v2 preparation below retains the existing snapshot/estimate/publication,\n-- replay and exact commercial-line guards. Only its versioned image-free input\n-- and frozen drawing source differ; the original v1 entry remains untouched.\ncreate function public.studio_client_quote_prepare(\n p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,\n p_expected_updated_at timestamptz,p_authored jsonb,p_spatial jsonb,p_publication_id uuid,\n p_content_hash text,p_handoff jsonb,p_private_evidence jsonb,p_customer_view jsonb,p_drawing_source jsonb\n) returns table(snapshot_id uuid,prepared_at timestamptz)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare e public.estimates%rowtype; previous text; saved_at timestamptz; replay private.studio_website_quote_snapshots%rowtype; item jsonb; kind text;\nbegin\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and p_project_id=any(project_ids)) then raise exception 'studio_client_documents_disabled'; end if;\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then\n  raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into e from public.estimates where id=p_estimate_id and project_id=p_project_id for update;\n if not found or e.status<>'draft' then raise exception 'studio_estimate_unavailable'; end if;\n select * into replay from private.studio_website_quote_snapshots where id=p_snapshot_id;\n if found then\n  if replay.estimate_id is distinct from e.id or replay.actor_user_id is distinct from p_actor_user_id or replay.content_hash is distinct from p_content_hash or replay.customer_view is distinct from p_customer_view or replay.handoff is distinct from p_handoff or replay.authored is distinct from p_authored or replay.spatial is distinct from p_spatial or replay.publication_id is distinct from p_publication_id or replay.private_evidence is distinct from p_private_evidence then raise exception 'studio_prepare_intent_conflict'; end if;\n  if not exists(select 1 from private.studio_client_document_sources d where d.snapshot_id=p_snapshot_id\n   and (d.drawing_source-'issuedAt'-'issuedDate') is not distinct from (p_drawing_source-'issuedAt'-'issuedDate'))\n   then raise exception 'studio_prepare_intent_conflict'; end if;\n  return query select replay.id,replay.created_at; return;\n end if;\n if exists(select 1 from public.quote_versions where source_estimate_version_id=e.id) then raise exception 'studio_estimate_referenced'; end if;\n if e.updated_at is distinct from p_expected_updated_at or e.outputs->'studio_authored' is distinct from p_authored\n  or e.outputs->'drawing_object_first' is distinct from p_spatial then raise exception 'studio_stale' using errcode='PT409'; end if;\n perform 1 from public.costing_configuration_publication where singleton and current_version_id=p_publication_id for share;\n if not found then raise exception 'studio_publication_changed' using errcode='PT409'; end if;\n if p_snapshot_id is null or p_publication_id is null or p_content_hash is null or p_content_hash !~ '^[0-9a-f]{64}$'\n  or jsonb_typeof(p_authored) is distinct from 'object' or jsonb_typeof(p_spatial) is distinct from 'object'\n  or jsonb_typeof(p_private_evidence) is distinct from 'object' or jsonb_typeof(p_customer_view) is distinct from 'object'\n  or jsonb_typeof(p_handoff) is distinct from 'object'\n  or p_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n  or p_customer_view->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_handoff->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_customer_view->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_handoff->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_customer_view->>'contentHash' is distinct from p_content_hash\n  or p_handoff->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_customer_view->'images') is distinct from 'array'\n  or jsonb_typeof(p_customer_view->'selections') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'lines') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'totalIncGstCents') is distinct from 'number'\n  or jsonb_typeof(p_handoff->'source') is distinct from 'object'\n  or octet_length(p_customer_view::text)>8388608 then raise exception 'studio_snapshot_invalid'; end if;\n if jsonb_array_length(p_customer_view->'images')<>0 or jsonb_array_length(p_handoff->'lines')<1\n  or (p_handoff->>'totalIncGstCents')::bigint<=0\n  or jsonb_typeof(p_drawing_source) is distinct from 'object'\n  or p_drawing_source->>'schemaVersion' is distinct from 'studio_client_document.v1'\n  or p_drawing_source->>'rendererVersion' is distinct from 'studio-booklet.v1'\n  or p_drawing_source->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_drawing_source->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_drawing_source->'products') is distinct from 'array'\n  or jsonb_array_length(p_drawing_source->'products') not between 0 and 32\n  or jsonb_typeof(p_private_evidence->'configuration') is distinct from 'object'\n  or octet_length(p_drawing_source::text)>16777216\n  then raise exception 'studio_client_document_invalid'; end if;\n for item in select value from jsonb_array_elements(p_handoff->'lines') loop\n  if jsonb_typeof(item) is distinct from 'object' or coalesce(trim(item->>'description'),'')=''\n   or item->'qty' is distinct from '1'::jsonb or jsonb_typeof(item->'sortOrder') is distinct from 'number'\n   or jsonb_typeof(item->'unitPriceIncGstCents') is distinct from 'number'\n   or item->'lineTotalIncGstCents' is distinct from item->'unitPriceIncGstCents'\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n  if (item->>'unitPriceIncGstCents')::numeric<0 or (item->>'unitPriceIncGstCents')::numeric<>trunc((item->>'unitPriceIncGstCents')::numeric)\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n end loop;\n if (select sum((value->>'lineTotalIncGstCents')::bigint) from jsonb_array_elements(p_handoff->'lines')) is distinct from (p_handoff->>'totalIncGstCents')::bigint\n  or exists(select 1 from jsonb_array_elements(p_handoff->'lines') with ordinality line(value,n) where (value->>'sortOrder')::numeric<>n-1)\n  then raise exception 'studio_snapshot_lines_invalid'; end if;\n insert into private.studio_website_quote_snapshots(id,project_id,estimate_id,commercial_scope_id,actor_user_id,content_hash,\n  authored,spatial,publication_id,handoff,private_evidence,customer_view)\n values(p_snapshot_id,e.project_id,e.id,e.commercial_scope_id,p_actor_user_id,p_content_hash,p_authored,p_spatial,p_publication_id,p_handoff,p_private_evidence,p_customer_view);\n insert into private.studio_client_document_sources(snapshot_id,renderer_version,drawing_source)\n values(p_snapshot_id,'studio-booklet.v1',p_drawing_source);\n previous:=current_setting('sanctuary.studio_command',true);\n perform set_config('sanctuary.studio_command','save',true);\n update public.estimates set outputs=outputs||jsonb_build_object('studio_quote_handoff',p_handoff),\n  pricing_source='workbench_solved',pricing_source_metadata=jsonb_build_object('studioSnapshotId',p_snapshot_id,'studioSnapshotHash',p_content_hash,'studioDocumentMode','separate_v1'),\n  updated_at=clock_timestamp() where id=e.id returning updated_at into saved_at;\n perform set_config('sanctuary.studio_command',coalesce(previous,''),true);\n return query select id,created_at from private.studio_website_quote_snapshots where id=p_snapshot_id;\nend $$","revoke all on function public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb) to service_role","-- A committed snapshot always has durable intent. Queue unavailability cannot\n-- roll back a valid quote; the same intent can be admitted by explicit retry.\ncreate function private.studio_client_document_enqueue(p_snapshot_id uuid)\nreturns void language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; s private.studio_website_quote_snapshots%rowtype; j public.background_jobs%rowtype;\nbegin\n select * into d from private.studio_client_documents where snapshot_id=p_snapshot_id for update;\n if d.snapshot_id is null or d.job_id is not null or d.file_id is not null then return; end if;\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and d.project_id=any(project_ids)) then raise exception 'studio_client_document_unavailable'; end if;\n select * into s from private.studio_website_quote_snapshots where id=d.snapshot_id;\n begin\n  j:=private.background_job_enqueue_core('studio_design_booklet_v1',1,'studio_snapshot',s.id::text,s.project_id,s.actor_user_id,'staff',100::smallint,\n   'studio-booklet:'||s.id::text||':'||d.renderer_version,jsonb_build_object('contractVersion',1,'snapshotId',s.id,'rendererVersion',d.renderer_version),null,'worker_enabled','worker','studio-client-documents-local');\n  update private.studio_client_documents set job_id=j.id,enqueue_failed=false where snapshot_id=d.snapshot_id;\n exception when others then\n  update private.studio_client_documents set enqueue_failed=true where snapshot_id=d.snapshot_id;\n end;\nend $$","revoke all on function private.studio_client_document_enqueue(uuid) from public,anon,authenticated,service_role","create function public.studio_client_quote_commit(p_operation text,p_snapshot_id uuid,p_content_hash text,p_command jsonb)\nreturns public.quote_versions language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare s private.studio_website_quote_snapshots%rowtype; d private.studio_client_document_sources%rowtype; q public.quote_versions%rowtype; j public.background_jobs%rowtype; prior_stage text;\nbegin\n select * into s from private.studio_website_quote_snapshots where id=p_snapshot_id and content_hash=p_content_hash;\n select * into d from private.studio_client_document_sources where snapshot_id=p_snapshot_id;\n if s.id is null or d.snapshot_id is null or s.customer_view->>'schemaVersion'<>'studio_quote_snapshot.v2'\n  or not exists(select 1 from private.studio_client_document_control where singleton and enabled and s.project_id=any(project_ids))\n then raise exception 'studio_client_document_unavailable'; end if;\n -- Serialize only new client-document commands on the same project before\n -- the canonical quote/address locks. Avoid two SHARE-to-UPDATE conversions.\n perform pg_advisory_xact_lock(hashtextextended('studio-client-quote-project:'||s.project_id::text,0));\n q:=public.studio_website_quote_commit_address(p_operation,p_snapshot_id,p_content_hash,p_command);\n if not exists(select 1 from private.studio_client_documents where snapshot_id=s.id) then\n  insert into private.studio_client_documents(snapshot_id,project_id,quote_version_id,renderer_version,total_pages)\n  values(s.id,s.project_id,q.id,d.renderer_version,1+2*jsonb_array_length(d.drawing_source->'products'));\n end if;\n perform private.studio_client_document_enqueue(s.id);\n if p_operation='create' and not exists(select 1 from public.audit_events where idempotency_key='studio:quote-created:'||q.id::text) then\n  select pipeline_stage into prior_stage from public.projects where id=s.project_id;\n  update public.projects set pipeline_stage='QUOTING' where id=s.project_id;\n  insert into public.audit_events(project_id,type,idempotency_key,payload) values\n   (s.project_id,'pipeline.stage_changed','studio:quote-stage:'||q.id::text,jsonb_build_object('fromStage',prior_stage,'toStage','QUOTING','quoteId',q.id)),\n   (s.project_id,'quote.created','studio:quote-created:'||q.id::text,coalesce(p_command->'p_studio_created_audit','{}'::jsonb)||jsonb_build_object('quoteVersionId',q.id));\n end if;\n return q;\nend $$","revoke all on function public.studio_client_quote_commit(text,uuid,text,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_quote_commit(text,uuid,text,jsonb) to service_role","create function private.studio_client_document_owned(p_job_id uuid,p_worker_id text,p_lease_token uuid)\nreturns private.studio_client_documents language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare j public.background_jobs%rowtype; d private.studio_client_documents%rowtype;\nbegin\n j:=private.background_job_lock_owned(p_job_id,p_worker_id,p_lease_token);\n -- Cancellation is checked under the same job lock used by the request owner.\n if j.cancellation_requested_at is not null then raise exception 'studio_document_cancelled' using errcode='55000'; end if;\n select * into d from private.studio_client_documents where job_id=j.id for update;\n if j.kind<>'studio_design_booklet_v1' or d.snapshot_id is null or j.subject_type<>'studio_snapshot'\n  or j.subject_id<>d.snapshot_id::text or j.project_id<>d.project_id\n  or not exists(select 1 from private.studio_client_document_control where singleton and enabled and d.project_id=any(project_ids))\n then raise exception 'studio_document_job_mismatch' using errcode='42501'; end if;\n return d;\nend $$","revoke all on function private.studio_client_document_owned(uuid,text,uuid) from public,anon,authenticated,service_role","create function public.studio_client_document_worker_read(p_job_id uuid,p_worker_id text,p_lease_token uuid)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype;\nbegin\n d:=private.studio_client_document_owned(p_job_id,p_worker_id,p_lease_token);\n return jsonb_build_object('snapshotId',d.snapshot_id,'rendererVersion',d.renderer_version,'totalPages',d.total_pages,'readyFileId',d.file_id,\n  'source',(select drawing_source from private.studio_client_document_sources where snapshot_id=d.snapshot_id),\n  'pages',coalesce((select jsonb_agg(jsonb_build_object('index',page_index,'sha256',content_hash,'contentBase64',content_base64) order by page_index) from private.studio_client_document_pages where snapshot_id=d.snapshot_id),'[]'::jsonb));\nend $$","revoke all on function public.studio_client_document_worker_read(uuid,text,uuid) from public,anon,authenticated","grant execute on function public.studio_client_document_worker_read(uuid,text,uuid) to service_role","create function public.studio_client_document_page_stage(p_job_id uuid,p_worker_id text,p_lease_token uuid,p_page_index integer,p_content_base64 text,p_sha256 text)\nreturns integer language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; previous text; count_pages integer;\nbegin\n d:=private.studio_client_document_owned(p_job_id,p_worker_id,p_lease_token);\n if d.file_id is not null or p_page_index is null or p_page_index not between 0 and d.total_pages-1\n  or p_content_base64 is null or length(p_content_base64)>16777216 or substring(decode(p_content_base64,'base64') from 1 for 5)<>convert_to('%PDF-','UTF8')\n  or p_sha256 is null or encode(sha256(decode(p_content_base64,'base64')),'hex')<>p_sha256\n then raise exception 'studio_document_page_invalid'; end if;\n select content_hash into previous from private.studio_client_document_pages where snapshot_id=d.snapshot_id and page_index=p_page_index;\n if previous is not null and previous<>p_sha256 then raise exception 'studio_document_checkpoint_conflict'; end if;\n insert into private.studio_client_document_pages(snapshot_id,page_index,content_hash,content_base64) values(d.snapshot_id,p_page_index,p_sha256,p_content_base64) on conflict do nothing;\n select count(*) into count_pages from private.studio_client_document_pages where snapshot_id=d.snapshot_id;\n return count_pages;\nend $$","revoke all on function public.studio_client_document_page_stage(uuid,text,uuid,integer,text,text) from public,anon,authenticated","grant execute on function public.studio_client_document_page_stage(uuid,text,uuid,integer,text,text) to service_role","create function public.studio_client_document_finish(p_job_id uuid,p_worker_id text,p_lease_token uuid,p_content_base64 text,p_sha256 text)\nreturns uuid language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; file_uuid uuid; filename text; previous_hash text;\nbegin\n d:=private.studio_client_document_owned(p_job_id,p_worker_id,p_lease_token);\n if p_content_base64 is null or length(p_content_base64)>33554432 or substring(decode(p_content_base64,'base64') from 1 for 5)<>convert_to('%PDF-','UTF8')\n  or p_sha256 is null or encode(sha256(decode(p_content_base64,'base64')),'hex')<>p_sha256\n  or (select count(*) from private.studio_client_document_pages where snapshot_id=d.snapshot_id)<>d.total_pages\n then raise exception 'studio_document_final_invalid'; end if;\n if d.file_id is not null then\n  select encode(sha256(decode(content_base64,'base64')),'hex') into previous_hash from public.file_artifacts where id=d.file_id;\n  if previous_hash<>p_sha256 then raise exception 'studio_document_final_conflict'; end if;\n  return d.file_id;\n end if;\n select 'Sanctuary-Design-'||q.quote_ref||'-v'||v.version_number||'.pdf' into filename from public.quote_versions v join public.quotes q on q.id=v.quote_id where v.id=d.quote_version_id;\n insert into public.file_artifacts(project_id,filename,content_type,size_bytes,content_base64,created_by)\n values(d.project_id,filename,'application/pdf',octet_length(decode(p_content_base64,'base64')),p_content_base64,'background:studio-documents') returning id into file_uuid;\n update private.studio_client_documents set file_id=file_uuid,completed_at=clock_timestamp() where snapshot_id=d.snapshot_id;\n return file_uuid;\nend $$","revoke all on function public.studio_client_document_finish(uuid,text,uuid,text,text) from public,anon,authenticated","grant execute on function public.studio_client_document_finish(uuid,text,uuid,text,text) to service_role","create function public.studio_client_document_status(p_quote_version_id uuid,p_actor_user_id uuid,p_download boolean default false)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; j public.background_jobs%rowtype; completed integer; result jsonb;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id;\n if not found then return null; end if;\n select * into j from public.background_jobs where id=d.job_id;\n select count(*) into completed from private.studio_client_document_pages where snapshot_id=d.snapshot_id;\n result:=jsonb_build_object('snapshotId',d.snapshot_id,'rendererVersion',d.renderer_version,'completedPages',completed,'totalPages',d.total_pages,\n  'state',case when d.file_id is not null then 'ready' when d.enqueue_failed or j.status in ('needs_attention','permanent_failed','cancelled') then 'failed' when j.status='queued' then 'queued' else 'running' end,\n  'percent',case when d.file_id is not null then 100 else floor(completed*100.0/(d.total_pages+1)) end,\n  'canRetry',d.file_id is null and (d.enqueue_failed or (j.status in ('needs_attention','permanent_failed') and j.attempt_count<4)));\n if p_download and d.file_id is not null then result:=result||jsonb_build_object('file',(select jsonb_build_object('filename',filename,'contentBase64',content_base64) from public.file_artifacts where id=d.file_id and project_id=d.project_id)); end if;\n return result;\nend $$","revoke all on function public.studio_client_document_status(uuid,uuid,boolean) from public,anon,authenticated","grant execute on function public.studio_client_document_status(uuid,uuid,boolean) to service_role","create function public.studio_client_document_retry(p_quote_version_id uuid,p_snapshot_id uuid,p_actor_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; j public.background_jobs%rowtype;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id and b.snapshot_id=p_snapshot_id;\n if not found or d.file_id is not null or not exists(select 1 from private.studio_client_document_control where singleton and enabled and d.project_id=any(project_ids)) then raise exception 'studio_document_retry_unavailable'; end if;\n if d.job_id is null then\n  perform private.studio_client_document_enqueue(d.snapshot_id);\n  return public.studio_client_document_status(p_quote_version_id,p_actor_user_id,false);\n end if;\n -- Match the lease helper lock order: job, then generation.\n select * into j from public.background_jobs where id=d.job_id for update;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id and b.snapshot_id=p_snapshot_id for update of g;\n if not found or d.file_id is not null then raise exception 'studio_document_retry_unavailable'; end if;\n if j.status not in ('needs_attention','permanent_failed') or j.attempt_count>=4 then raise exception 'studio_document_retry_unavailable'; end if;\n perform public.background_job_manual_retry(j.id,p_actor_user_id);\n return public.studio_client_document_status(p_quote_version_id,p_actor_user_id,false);\nend $$","revoke all on function public.studio_client_document_retry(uuid,uuid,uuid) from public,anon,authenticated","grant execute on function public.studio_client_document_retry(uuid,uuid,uuid) to service_role"],"statementSha256":["4d4616f4597d29f5b10e24d271ef4c75b06ecc7180055d0e2b25f1538d5d8c27","1d5490ec61715aec5b45d351763ecd12f76820e8920212e9661048b6cb9959de","e7d3fb095eb4228a3ecd2bcec61ab7abdb96d1e8ae4f4a006bab99d586929543","5f4559ef69dca041b55cea3822077b6c62398a1dca7b0e35c253dcc75fc694ef","249a0c6080f3c6187dd4c7d6f8ee6d8265a9f468c7322f0ad0043c4f8c6d5e42","dc44e5938f3d7688e57c1713c1b36d78a5270e6ceb734cbb279c37f309646e6f","d2b97ab09bedec3a8a2445cc2c78be684257336da33fcb6559bd69bec3cc2d98","07451ae3a66e817463b07dd1a7bb1cb39d3e33c5a361016489a7d2498f6fccf0","d060087c02bafbe730deccd2bab17788cf577933da2712102baa9cbe63a896fe","c31aae86a10a0ee1a5bd2ad537a635004351a25eb41663332040eb11a11d817b","e4988a844279e0c910afd61dbc5bb9959c606436243d0ac3547bf1538bcb40cd","210f230ae314ecaf5423883864950c646e9b62b35aef07512356499b95c955eb","23901d44c6d2b838318ad1e313e7e6ca7061aa8c0034bdf4fadd1e296c58ceb1","3082e296140afd8bf6ce6cc17307fb45aef9bd0ad2d3a285c7bdb7f8ba1cadc5","04f1f8c99a7ce05d28de2c1d68be8306dd72e86de362d2002f70efb3b6ecbc45","3bb18629a8173e162d27469a686223547e1ec89f8cdf7fc01ebfd16b8e3cb600","34f3f764c19c5ee4e6dc9d91ddf1b94946c323abb522b7f89b7415fca4b12b27","1b9dd647ba1063636312cbafc50022f89ede754d9692c653146db27e12db4a62","17ed97217d47a4ae168290bded6c6c04a7a9548f887ad408124841629c766890","cc51486f09743c014cea2291c191507a2b775cc5fa55b9fb98d3472549fbfd0e","ebcfb358ed269b9a53b6c14b4dd52f98f8fe941d6ddef4089b84e79b25cb378b","2079c5398081a07d5373ebef84d6ef3ba4059eb17e29ea5cbf87a6723668c1ff","a28d3fe1c6d17aec0c5fedf463d15e65877c2cd1596cb69f317ff55f137e1d94","d872e556e4312824d154831ba5510b37d30f52d50128ae78f4cab644f9bd598b","0d001e8e2f7aa18b9180ae06dc9aed4d9dbb587671eb5438238caef2b19cb816","b4585472a7dbd1812d647534646a25e653580564eae8eefed473b509b821e198","74c28f20b6585b243e17d56f74e1cf9be61dc04a87a90a277e6f582581d8f5ca","be07e5d921388306b11a783c8423d81c9e67e7eccd5b900b5a59206b61d194ee","550075bfe54eef2754a11246e340b56c0a5343f9fd454774993263254c81e5e8","ef9ea75b3b4fb59f729b9ea4ee9cd246661edfa2550f8a895dbda0504864c2f6","05f5e6c4bcf618ea80a382222f6cc77aab4c4dedf4e928dd653dde3b0da09fa9","bf7bf30da801e3c5f692668055f69b569567cce2ffd7785ff682fd1ee3303bcd","4c36bdea0d50311d1d25e6e01279bbcb6af3feb01c15016118d220eccee5cac3","b458d3cba474c92ef97eaff2b0a84bf76cf309085ed1e858dee0912294b1e5ac","103c5fb32cdc4867e04993bdae3c0196200c440fca19b8b08e4f1187ed4275d9","bc890fdc49d05731ec90059a127e213e6eef5191a0794a7daaf51f341eb645e0","856da40db11680f4ebab4d9be7b7289a51f8dfcfb3665356271c3d7326208c83","a22997a8511f592f07db93863303ce80a102f5e66ce39dace170c3360ff2473d","e6cb6c3707a0a2c01469a40d871e5f8e63178f9d8a598b39068e538e896d29e8","78b4efc7b39e78142b530f34495cf78c50ede7ea0714294c5d4cf2796fbffd7c"]},{"version":"20261028090414","name":"background_jobs_scoped_claim","rawSha256":"2d4f44a1d1b30eee0c3ca0fc5ed09f0918e1f66efb91d2751c9cde654c430aa0","canonicalLfSha256":"bf8a589fe5063e90ac671128400bc4be7e343d8fb49522295093728b064b68ce","statements":["-- Optional canonical claim scope. Existing three-argument callers are unchanged.\n-- Filter before queue visibility/read counters or job leases are changed.\ncreate function private.background_job_read_claim_queue(p_visibility_timeout_seconds integer,p_batch_size integer)\nreturns table(msg_id bigint,message jsonb)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare kinds jsonb; projects jsonb;\nbegin\n kinds:=nullif(current_setting('sanctuary.background_job_claim_kinds',true),'')::jsonb;\n projects:=nullif(current_setting('sanctuary.background_job_claim_projects',true),'')::jsonb;\n if (kinds is not null or projects is not null) and (jsonb_typeof(kinds) is distinct from 'array' or jsonb_array_length(kinds) not between 1 and 16\n  or jsonb_typeof(projects) is distinct from 'array' or jsonb_array_length(projects) not between 1 and 32\n ) then raise exception 'invalid_background_job_claim_scope' using errcode='22023'; end if;\n return query\n with candidates as (\n  select q.msg_id from pgmq.q_portal_background_jobs q\n  left join public.background_jobs j on j.id::text=q.message->>'jobId'\n  where q.vt<=clock_timestamp() and (\n   (kinds is null and projects is null and j.kind is distinct from 'studio_design_booklet_v1')\n   or (kinds ? j.kind and projects ? j.project_id::text and j.queue_message_id=q.msg_id))\n  order by q.msg_id limit p_batch_size for update of q skip locked\n ), touched as (\n  update pgmq.q_portal_background_jobs q set vt=clock_timestamp()+make_interval(secs=>p_visibility_timeout_seconds),read_ct=q.read_ct+1\n  from candidates c where q.msg_id=c.msg_id returning q.msg_id,q.message\n ) select t.msg_id,t.message from touched t order by t.msg_id;\nend $$","revoke all on function private.background_job_read_claim_queue(integer,integer) from public,anon,authenticated,service_role","create function public.background_jobs_claim_scoped(p_worker_id text,p_batch_size integer,p_visibility_timeout_seconds integer,p_kinds text[],p_project_ids uuid[])\nreturns table(job_id uuid,kind text,contract_version integer,status public.background_job_status,current_phase text,attempt_number integer,max_attempts integer,queue_message_id bigint,lease_token uuid,lease_expires_at timestamptz,cancellation_requested_at timestamptz,rollout_mode public.background_job_rollout_mode,execution_owner public.background_job_execution_owner)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare previous_kinds text:=current_setting('sanctuary.background_job_claim_kinds',true); previous_projects text:=current_setting('sanctuary.background_job_claim_projects',true);\nbegin\n if p_kinds is null or cardinality(p_kinds) not between 1 and 16 or p_project_ids is null or cardinality(p_project_ids) not between 1 and 32\n  or array_position(p_kinds,null) is not null or array_position(p_project_ids,null) is not null\n  or exists(select 1 from unnest(p_kinds) k where not exists(select 1 from public.background_job_kinds registered where registered.kind=k))\n then raise exception 'invalid_background_job_claim_scope' using errcode='22023'; end if;\n perform set_config('sanctuary.background_job_claim_kinds',to_jsonb(p_kinds)::text,true);\n perform set_config('sanctuary.background_job_claim_projects',to_jsonb(p_project_ids)::text,true);\n return query select * from public.background_jobs_claim(p_worker_id,p_batch_size,p_visibility_timeout_seconds);\n perform set_config('sanctuary.background_job_claim_kinds',coalesce(previous_kinds,''),true);\n perform set_config('sanctuary.background_job_claim_projects',coalesce(previous_projects,''),true);\nexception when others then\n perform set_config('sanctuary.background_job_claim_kinds',coalesce(previous_kinds,''),true);\n perform set_config('sanctuary.background_job_claim_projects',coalesce(previous_projects,''),true);\n raise;\nend $$","revoke all on function public.background_jobs_claim_scoped(text,integer,integer,text[],uuid[]) from public,anon,authenticated","grant execute on function public.background_jobs_claim_scoped(text,integer,integer,text[],uuid[]) to service_role","-- The canonical state machine below is unchanged apart from its queue reader.\ncreate or replace function public.background_jobs_claim(\n  p_worker_id text,\n  p_batch_size integer default 5,\n  p_visibility_timeout_seconds integer default 120\n)\nreturns table (\n  job_id uuid,\n  kind text,\n  contract_version integer,\n  status public.background_job_status,\n  current_phase text,\n  attempt_number integer,\n  max_attempts integer,\n  queue_message_id bigint,\n  lease_token uuid,\n  lease_expires_at timestamptz,\n  cancellation_requested_at timestamptz,\n  rollout_mode public.background_job_rollout_mode,\n  execution_owner public.background_job_execution_owner\n)\nlanguage plpgsql\nsecurity definer\nset search_path = pg_catalog, pg_temp\nas $$\ndeclare\n  v_message record;\n  v_job public.background_jobs%rowtype;\n  v_job_id uuid;\n  v_contract_version integer;\n  v_previous_status public.background_job_status;\n  v_delay_seconds integer;\n  v_dispatch_effect_count integer := 0;\n  v_dispatch_outcome_count integer := 0;\nbegin\n  if p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9._:-]{1,128}$' then\n    raise exception 'invalid worker ID' using errcode = '22023';\n  end if;\n  if p_batch_size is null or p_batch_size not between 1 and 100 then\n    raise exception 'batch size must be between 1 and 100' using errcode = '22023';\n  end if;\n  if p_visibility_timeout_seconds is null or p_visibility_timeout_seconds not between 15 and 3600 then\n    raise exception 'visibility timeout must be between 15 and 3600 seconds' using errcode = '22023';\n  end if;\n\n  for v_message in\n    select *\n    from private.background_job_read_claim_queue(p_visibility_timeout_seconds, p_batch_size)\n  loop\n    v_job_id := null;\n    v_contract_version := null;\n    v_dispatch_effect_count := 0;\n    v_dispatch_outcome_count := 0;\n\n    begin\n      if jsonb_typeof(v_message.message) <> 'object'\n         or (select count(*) from jsonb_object_keys(v_message.message)) <> 2\n         or not (v_message.message ? 'jobId')\n         or not (v_message.message ? 'contractVersion')\n         or jsonb_typeof(v_message.message -> 'jobId') <> 'string'\n         or jsonb_typeof(v_message.message -> 'contractVersion') <> 'number' then\n        raise exception 'invalid minimal queue contract';\n      end if;\n      v_job_id := (v_message.message ->> 'jobId')::uuid;\n      v_contract_version := (v_message.message ->> 'contractVersion')::integer;\n      if v_contract_version <= 0 then\n        raise exception 'invalid queue contract version';\n      end if;\n    exception when others then\n      perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n      perform private.background_job_insert_event(\n        null,\n        v_message.msg_id,\n        'orphaned_message',\n        null,\n        null,\n        null,\n        null,\n        p_worker_id,\n        null,\n        'INVALID_QUEUE_MESSAGE',\n        jsonb_build_object('reason', 'invalid_minimal_contract')\n      );\n      continue;\n    end;\n\n    select candidate.*\n    into v_job\n    from public.background_jobs candidate\n    where candidate.id = v_job_id\n    for update skip locked;\n\n    if not found then\n      if exists (select 1 from public.background_jobs existing where existing.id = v_job_id) then\n        perform pgmq.set_vt('portal_background_jobs', v_message.msg_id, 5);\n      else\n        perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n        perform private.background_job_insert_event(\n          null,\n          v_message.msg_id,\n          'orphaned_message',\n          null,\n          null,\n          null,\n          null,\n          p_worker_id,\n          null,\n          'MISSING_LEDGER_ROW',\n          jsonb_build_object('reason', 'job_not_found')\n        );\n      end if;\n      continue;\n    end if;\n\n    v_previous_status := v_job.status;\n\n    if v_job.queue_message_id is distinct from v_message.msg_id then\n      perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_message.msg_id,\n        'duplicate_message',\n        v_job.status,\n        v_job.status,\n        v_job.current_phase,\n        v_job.attempt_count,\n        p_worker_id,\n        null,\n        null,\n        jsonb_build_object('reason', 'non_canonical_message')\n      );\n      continue;\n    end if;\n\n    if v_job.contract_version <> v_contract_version then\n      if v_job.status = 'dispatching' then\n        update public.background_job_effects as effect\n        set state = 'uncertain',\n            safe_metadata = jsonb_build_object(\n              'effectKind', effect.effect_kind,\n              'checkpoint', 'uncertain',\n              'providerName', effect.provider_name\n            ),\n            updated_at = now()\n        where effect.job_id = v_job.id\n          and effect.state = 'dispatch_started';\n      end if;\n      update public.background_jobs\n      set status = 'needs_attention',\n          current_phase = 'contract_mismatch',\n          error_code = 'QUEUE_CONTRACT_MISMATCH',\n          error_message = private.background_job_safe_error_copy('QUEUE_CONTRACT_MISMATCH'),\n          lease_owner = null,\n          lease_token = null,\n          lease_started_at = null,\n          lease_expires_at = null,\n          last_heartbeat_at = null\n      where id = v_job.id;\n      perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_message.msg_id,\n        'needs_attention',\n        v_job.status,\n        'needs_attention',\n        'contract_mismatch',\n        v_job.attempt_count,\n        p_worker_id,\n        null,\n        'QUEUE_CONTRACT_MISMATCH'\n      );\n      continue;\n    end if;\n\n    if v_job.status in ('succeeded', 'cancelled', 'needs_attention', 'permanent_failed') then\n      perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_message.msg_id,\n        'reconciled',\n        v_job.status,\n        v_job.status,\n        v_job.current_phase,\n        v_job.attempt_count,\n        p_worker_id,\n        null,\n        null,\n        jsonb_build_object('reason', 'terminal_message_archived')\n      );\n      continue;\n    end if;\n\n    if v_job.next_attempt_at > now() then\n      v_delay_seconds := greatest(1, ceil(extract(epoch from (v_job.next_attempt_at - now())))::integer);\n      perform pgmq.set_vt('portal_background_jobs', v_message.msg_id, v_delay_seconds);\n      continue;\n    end if;\n\n    if v_job.lease_expires_at is not null and v_job.lease_expires_at > now() then\n      v_delay_seconds := greatest(1, ceil(extract(epoch from (v_job.lease_expires_at - now())))::integer);\n      perform pgmq.set_vt('portal_background_jobs', v_message.msg_id, v_delay_seconds);\n      continue;\n    end if;\n\n    if v_job.cancellation_requested_at is not null\n       and v_job.status in ('queued', 'retrying', 'claimed', 'preparing', 'running') then\n      v_previous_status := v_job.status;\n      update public.background_jobs\n      set status = 'cancelled',\n          current_phase = 'cancelled',\n          lease_owner = null,\n          lease_token = null,\n          lease_started_at = null,\n          lease_expires_at = null,\n          last_heartbeat_at = null\n      where id = v_job.id;\n      perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_message.msg_id,\n        'cancelled',\n        v_previous_status,\n        'cancelled',\n        'cancelled',\n        v_job.attempt_count,\n        p_worker_id\n      );\n      continue;\n    end if;\n\n    if v_job.lease_expires_at is not null then\n      v_previous_status := v_job.status;\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_message.msg_id,\n        'lease_expired',\n        v_previous_status,\n        v_previous_status,\n        v_job.current_phase,\n        v_job.attempt_count,\n        p_worker_id\n      );\n\n      if v_previous_status = 'dispatching' then\n        select\n          count(*) filter (where effect.state in ('dispatch_started', 'uncertain')),\n          count(*)\n        into v_dispatch_effect_count, v_dispatch_outcome_count\n        from public.background_job_effects effect\n        where effect.job_id = v_job.id;\n\n        if v_dispatch_effect_count <> 1 or v_dispatch_outcome_count <> 1 then\n          update public.background_jobs\n          set status = 'needs_attention',\n              current_phase = 'provider_reconciliation',\n              error_code = 'PROVIDER_EFFECT_INVARIANT',\n              error_message = private.background_job_safe_error_copy('PROVIDER_EFFECT_INVARIANT'),\n              lease_owner = null,\n              lease_token = null,\n              lease_started_at = null,\n              lease_expires_at = null,\n              last_heartbeat_at = null\n          where id = v_job.id;\n          perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n          perform private.background_job_insert_event(\n            v_job.id,\n            v_message.msg_id,\n            'needs_attention',\n            v_previous_status,\n            'needs_attention',\n            'provider_reconciliation',\n            v_job.attempt_count,\n            p_worker_id,\n            null,\n            'PROVIDER_EFFECT_INVARIANT',\n            jsonb_build_object('reason', 'provider_effect_invariant')\n          );\n          continue;\n        end if;\n\n        update public.background_job_effects as effect\n        set state = 'uncertain',\n            safe_metadata = jsonb_build_object(\n              'effectKind', effect.effect_kind,\n              'checkpoint', 'uncertain',\n              'providerName', effect.provider_name\n            ),\n            updated_at = now()\n        where effect.job_id = v_job.id\n          and effect.state = 'dispatch_started';\n\n        -- A cancellation requested while the prior worker was in the provider\n        -- call must win before this claimant can replay the frozen request.\n        -- The checkpoint is already uncertain, so the ledger does not imply\n        -- that an interrupted dispatch was proven absent.\n        if v_job.cancellation_requested_at is not null then\n          update public.background_jobs\n          set status = 'cancelled',\n              current_phase = 'cancelled',\n              error_code = null,\n              error_message = null,\n              lease_owner = null,\n              lease_token = null,\n              lease_started_at = null,\n              lease_expires_at = null,\n              last_heartbeat_at = null\n          where id = v_job.id;\n          perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n          perform private.background_job_insert_event(\n            v_job.id,\n            v_message.msg_id,\n            'cancelled',\n            v_previous_status,\n            'cancelled',\n            'cancelled',\n            v_job.attempt_count,\n            p_worker_id,\n            v_job.cancellation_requested_by,\n            null,\n            jsonb_build_object('reason', 'expired_lease_cancellation_acknowledged')\n          );\n          continue;\n        end if;\n\n        update public.background_jobs\n        set status = 'retrying',\n            current_phase = 'provider_retry',\n            error_code = 'PROVIDER_OUTCOME_UNCERTAIN',\n            error_message = private.background_job_safe_error_copy('PROVIDER_OUTCOME_UNCERTAIN'),\n            lease_owner = null,\n            lease_token = null,\n            lease_started_at = null,\n            lease_expires_at = null,\n            last_heartbeat_at = null\n        where id = v_job.id\n        returning * into v_job;\n        perform private.background_job_insert_event(\n          v_job.id,\n          v_message.msg_id,\n          'retry_scheduled',\n          v_previous_status,\n          'retrying',\n          'provider_retry',\n          v_job.attempt_count,\n          p_worker_id,\n          null,\n          'PROVIDER_OUTCOME_UNCERTAIN',\n          jsonb_build_object('delaySeconds', 0)\n        );\n      elsif v_previous_status not in ('provider_accepted', 'finalising') then\n        update public.background_jobs\n        set status = 'retrying',\n            current_phase = 'lease_recovery',\n            lease_owner = null,\n            lease_token = null,\n            lease_started_at = null,\n            lease_expires_at = null,\n            last_heartbeat_at = null\n        where id = v_job.id\n        returning * into v_job;\n      end if;\n    end if;\n\n    -- Provider-effect safety is decided before retry exhaustion so a live\n    -- same-key uncertain request can run, but an expired or exhausted request\n    -- can never be hidden as a generic permanent failure.\n    if v_job.execution_owner <> 'shadow' and exists (\n      select 1\n      from public.background_job_effects effect\n      where effect.job_id = v_job.id\n        and effect.state in ('prepared', 'failed', 'uncertain')\n        and (\n          effect.provider_idempotency_expires_at is null\n          or effect.provider_idempotency_expires_at <= now()\n        )\n    ) then\n      perform private.background_job_archive_canonical(v_job.id, v_job.queue_message_id);\n      update public.background_jobs\n      set status = 'needs_attention',\n          current_phase = 'provider_reconciliation',\n          error_code = 'PROVIDER_IDEMPOTENCY_WINDOW_EXPIRED',\n          error_message = private.background_job_safe_error_copy('PROVIDER_IDEMPOTENCY_WINDOW_EXPIRED'),\n          lease_owner = null,\n          lease_token = null,\n          lease_started_at = null,\n          lease_expires_at = null,\n          last_heartbeat_at = null\n      where id = v_job.id;\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_job.queue_message_id,\n        'needs_attention',\n        v_previous_status,\n        'needs_attention',\n        'provider_reconciliation',\n        v_job.attempt_count,\n        p_worker_id,\n        null,\n        'PROVIDER_IDEMPOTENCY_WINDOW_EXPIRED',\n        jsonb_build_object('reason', 'provider_idempotency_window_expired')\n      );\n      continue;\n    end if;\n\n    if v_job.attempt_count >= v_job.max_attempts and exists (\n      select 1\n      from public.background_job_effects effect\n      where effect.job_id = v_job.id\n        and effect.state = 'uncertain'\n    ) then\n      perform private.background_job_archive_canonical(v_job.id, v_job.queue_message_id);\n      update public.background_jobs\n      set status = 'needs_attention',\n          current_phase = 'provider_reconciliation',\n          error_code = 'PROVIDER_OUTCOME_UNCERTAIN',\n          error_message = private.background_job_safe_error_copy('PROVIDER_OUTCOME_UNCERTAIN'),\n          lease_owner = null,\n          lease_token = null,\n          lease_started_at = null,\n          lease_expires_at = null,\n          last_heartbeat_at = null\n      where id = v_job.id;\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_job.queue_message_id,\n        'needs_attention',\n        v_previous_status,\n        'needs_attention',\n        'provider_reconciliation',\n        v_job.attempt_count,\n        p_worker_id,\n        null,\n        'PROVIDER_OUTCOME_UNCERTAIN',\n        jsonb_build_object('reason', 'provider_outcome_uncertain')\n      );\n      continue;\n    end if;\n\n    if v_job.status = 'retrying' and v_job.attempt_count >= v_job.max_attempts then\n      update public.background_jobs\n      set status = 'permanent_failed',\n          current_phase = 'retry_exhausted',\n          error_code = 'RETRY_EXHAUSTED',\n          error_message = private.background_job_safe_error_copy('RETRY_EXHAUSTED'),\n          lease_owner = null,\n          lease_token = null,\n          lease_started_at = null,\n          lease_expires_at = null,\n          last_heartbeat_at = null\n      where id = v_job.id;\n      perform pgmq.archive('portal_background_jobs', v_message.msg_id);\n      perform private.background_job_insert_event(\n        v_job.id,\n        v_message.msg_id,\n        'permanent_failed',\n        'retrying',\n        'permanent_failed',\n        'retry_exhausted',\n        v_job.attempt_count,\n        p_worker_id,\n        null,\n        'RETRY_EXHAUSTED'\n      );\n      continue;\n    end if;\n\n    v_previous_status := v_job.status;\n    update public.background_jobs as claimed_job\n    set status = case\n          when claimed_job.status in ('provider_accepted', 'finalising') then claimed_job.status\n          else 'claimed'::public.background_job_status\n        end,\n        current_phase = case\n          when claimed_job.status in ('provider_accepted', 'finalising') then claimed_job.current_phase\n          else 'claimed'\n        end,\n        attempt_count = claimed_job.attempt_count + 1,\n        lease_owner = p_worker_id,\n        lease_token = gen_random_uuid(),\n        lease_started_at = now(),\n        lease_expires_at = now() + make_interval(secs => p_visibility_timeout_seconds),\n        last_heartbeat_at = now(),\n        error_code = null,\n        error_message = null\n    where id = v_job.id\n    returning * into v_job;\n\n    perform private.background_job_insert_event(\n      v_job.id,\n      v_message.msg_id,\n      'claimed',\n      v_previous_status,\n      v_job.status,\n      v_job.current_phase,\n      v_job.attempt_count,\n      p_worker_id\n    );\n\n    job_id := v_job.id;\n    kind := v_job.kind;\n    contract_version := v_job.contract_version;\n    status := v_job.status;\n    current_phase := v_job.current_phase;\n    attempt_number := v_job.attempt_count;\n    max_attempts := v_job.max_attempts;\n    queue_message_id := v_job.queue_message_id;\n    lease_token := v_job.lease_token;\n    lease_expires_at := v_job.lease_expires_at;\n    cancellation_requested_at := v_job.cancellation_requested_at;\n    rollout_mode := v_job.rollout_mode;\n    execution_owner := v_job.execution_owner;\n    return next;\n  end loop;\nend;\n$$","-- v1 metrics keep their known-kind projection for rolling older workers. The new\n-- document kind has its own scoped status; omission is not a measured zero.\n\ncreate or replace function public.background_jobs_runtime_metrics()\nreturns table (\n  queue_depth bigint,\n  oldest_message_age_seconds integer,\n  oldest_job_age_seconds integer,\n  due_jobs bigint,\n  next_due_at timestamptz,\n  status_counts jsonb,\n  kind_counts jsonb,\n  worker_lifecycle_counts jsonb,\n  stale_workers bigint,\n  measured_at timestamptz\n)\nlanguage sql\nstable\nsecurity definer\nset search_path = pg_catalog, pg_temp\nas $$\n  with queue_metrics as (\n    select * from pgmq.metrics('portal_background_jobs')\n  ),\n  unfinished_jobs as (\n    select job.*\n    from public.background_jobs job\n    where job.status not in ('succeeded', 'cancelled', 'permanent_failed')\n  ),\n  job_metrics as (\n    select\n      coalesce(\n        greatest(0, floor(extract(epoch from (now() - min(job.created_at))))),\n        0\n      )::integer as oldest_job_age_seconds,\n      count(*) filter (\n        where job.status in ('queued', 'retrying')\n          and job.next_attempt_at <= now()\n      )::bigint as due_jobs,\n      min(job.next_attempt_at) filter (\n        where job.status in ('queued', 'retrying')\n      ) as next_due_at\n    from unfinished_jobs job\n  ),\n  status_totals as (\n    select status.value::text as key, count(job.id)::bigint as value\n    from unnest(enum_range(null::public.background_job_status)) status(value)\n    left join public.background_jobs job on job.status = status.value\n    group by status.value\n  ),\n  kind_totals as (\n    select kind.kind as key, count(job.id)::bigint as value\n    from public.background_job_kinds kind\n    left join public.background_jobs job on job.kind = kind.kind\n    where kind.kind <> 'studio_design_booklet_v1'\n    group by kind.kind\n  ),\n  worker_lifecycle_totals as (\n    select lifecycle.value as key, count(worker.worker_id)::bigint as value\n    from unnest(array[\n      'starting',\n      'ready',\n      'draining',\n      'stopped',\n      'unhealthy'\n    ]::text[]) lifecycle(value)\n    left join public.background_workers worker on worker.lifecycle_state = lifecycle.value\n    group by lifecycle.value\n  ),\n  worker_totals as (\n    select count(*) filter (\n      where worker.lifecycle_state <> 'stopped'\n        and worker.last_heartbeat_at < now() - interval '2 minutes'\n    )::bigint as stale_workers\n    from public.background_workers worker\n  )\n  select\n    queue_metrics.queue_length,\n    queue_metrics.oldest_msg_age_sec,\n    job_metrics.oldest_job_age_seconds,\n    job_metrics.due_jobs,\n    job_metrics.next_due_at,\n    (select jsonb_object_agg(total.key, total.value order by total.key) from status_totals total),\n    (select jsonb_object_agg(total.key, total.value order by total.key) from kind_totals total),\n    (select jsonb_object_agg(total.key, total.value order by total.key) from worker_lifecycle_totals total),\n    worker_totals.stale_workers,\n    queue_metrics.scrape_time\n  from queue_metrics, job_metrics, worker_totals;\n$$"],"statementSha256":["fadcd7aff60a1db42c7ebd8c0ebfeb8b2df4f2c775b7287a60c7516d3f230a73","5f3eb439b1db54f0947cdda0d8e3261adb06ee7cadd51b85a781b0d6e95a3580","3491215910f959571c25a7767b9a6b8ef70fe5675c1ea7240ea3c448e1d9cc4e","1a87f77df0bed3e1bfe2f8b9543b3c1b83254173ce04c0aa48b224bd6af0e0c2","74eac27664000e0dc3ef2c1ae07ad6958b9aa3c57ff4f00d3edd76752125d6f1","def1b7e870aa15333fa14279b97c4803c57f07533c71253994f7d3024117e802","720fa5ae6893962ba272410b923d74c4b97a755b6b9c22668b1e02a4694a8234"]},{"version":"20261028114624","name":"studio_client_quote_atomic_create","rawSha256":"7c6cdcf4a82e736d601f54d94f22d7557c2852b22de5b82ca5302fb3424ca899","canonicalLfSha256":"7c6cdcf4a82e736d601f54d94f22d7557c2852b22de5b82ca5302fb3424ca899","statements":["-- One admitted Studio Create action. Existing Save, snapshot, financial and\n-- address owners remain authoritative; this wrapper only removes remote hops.\ncreate function private.studio_client_quote_created_result(p_quote_version_id uuid)\nreturns jsonb language sql stable security definer set search_path=pg_catalog,pg_temp as $$\n select jsonb_build_object('versionRow',to_jsonb(q)||jsonb_build_object('quotes',to_jsonb(f)),\n  'lineItems',coalesce((select jsonb_agg(to_jsonb(l) order by l.sort_order) from public.quote_line_items l where l.quote_version_id=q.id),'[]'::jsonb),\n  'sendLogs',coalesce((select jsonb_agg(to_jsonb(l) order by l.created_at desc) from public.quote_send_logs l where l.quote_version_id=q.id),'[]'::jsonb),\n  'studioDesign',s.customer_view,'estimateVersionLabel',d.drawing_source->>'designVersionLabel',\n  'saveReceipt',s.private_evidence->'atomicSaveReceipt','savedView',s.handoff->'source',\n  'sourceUpdatedAt',(select updated_at from public.estimates where id=s.estimate_id),\n  'contact',jsonb_build_object('name',coalesce(c.name,''),'email',coalesce(c.email,''),'phone',c.phone),\n  'project',jsonb_build_object('name',p.name,'siteAddress',s.customer_view#>>'{travelContext,destinationCanonical}','region',p.region,'quoteRef',p.quote_ref))\n from public.quote_versions q join public.quotes f on f.id=q.quote_id\n join public.projects p on p.id=f.project_id left join public.contacts c on c.id=p.contact_id\n join private.studio_website_quote_bindings b on b.quote_version_id=q.id\n join private.studio_website_quote_snapshots s on s.id=b.snapshot_id\n join private.studio_client_document_sources d on d.snapshot_id=s.id\n where q.id=p_quote_version_id\n$$","revoke all on function private.studio_client_quote_created_result(uuid) from public,anon,authenticated,service_role","-- Recognise an exact completed request before attempting to merge an old base.\n-- A replay still requires current staff role and the project's local admission.\ncreate function public.studio_client_quote_create_replay(p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_request_id uuid,p_client_request jsonb)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare s private.studio_website_quote_snapshots%rowtype; q public.quote_versions%rowtype;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and p_project_id=any(project_ids)) then raise exception 'studio_client_documents_disabled'; end if;\n select * into s from private.studio_website_quote_snapshots where id=p_request_id;\n if not found then return null; end if;\n if s.project_id is distinct from p_project_id or s.estimate_id is distinct from p_estimate_id or s.actor_user_id is distinct from p_actor_user_id\n  or s.private_evidence->'atomicCreateRequest' is distinct from p_client_request then raise exception 'studio_quote_intent_conflict' using errcode='23505'; end if;\n select v.* into q from public.quote_versions v join private.studio_website_quote_bindings b on b.quote_version_id=v.id\n  where b.snapshot_id=s.id and v.client_intent_id='studio:'||p_request_id::text;\n if not found then return null; end if;\n return private.studio_client_quote_created_result(q.id);\nend $$","revoke all on function public.studio_client_quote_create_replay(uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_quote_create_replay(uuid,uuid,uuid,uuid,jsonb) to service_role","create function public.studio_client_quote_create(p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_request_id uuid,\n p_client_request jsonb,p_save jsonb,p_preparation jsonb,p_command jsonb)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare replay jsonb; e public.estimates%rowtype; f public.quotes%rowtype; q public.quote_versions%rowtype;\n r record; evidence jsonb; command jsonb; customer text; ref text;\nbegin\n replay:=public.studio_client_quote_create_replay(p_project_id,p_estimate_id,p_actor_user_id,p_request_id,p_client_request);\n if replay is not null then return replay; end if;\n if p_request_id is null or jsonb_typeof(p_client_request) is distinct from 'object' or octet_length(p_client_request::text)>2097152\n  or jsonb_typeof(p_save) is distinct from 'object' or jsonb_typeof(p_preparation) is distinct from 'object' or jsonb_typeof(p_command) is distinct from 'object'\n  or p_save->>'requestId' is distinct from p_request_id::text\n  or p_preparation->>'p_snapshot_id' is distinct from p_request_id::text\n  or p_preparation->>'p_project_id' is distinct from p_project_id::text\n  or p_preparation->>'p_estimate_id' is distinct from p_estimate_id::text\n  or p_preparation->>'p_actor_user_id' is distinct from p_actor_user_id::text\n  or p_command->>'p_source_estimate_version_id' is distinct from p_estimate_id::text\n  or p_command->>'p_client_intent_id' is distinct from 'studio:'||p_request_id::text then raise exception 'studio_quote_command_invalid'; end if;\n -- Same ordering as the existing document/commercial owners: project advisory,\n -- quote advisory/current draft rows, then the source estimate Save lock.\n perform pg_advisory_xact_lock(hashtextextended('studio-client-quote-project:'||p_project_id::text,0));\n replay:=public.studio_client_quote_create_replay(p_project_id,p_estimate_id,p_actor_user_id,p_request_id,p_client_request);\n if replay is not null then return replay; end if;\n select * into e from public.estimates where id=p_estimate_id and project_id=p_project_id;\n if not found then raise exception 'studio_estimate_unavailable'; end if;\n select * into f from public.quotes where project_id=p_project_id and commercial_scope_id is not distinct from e.commercial_scope_id;\n if not found then\n  ref:=public.next_quote_ref();\n  insert into public.quotes(project_id,quote_ref,commercial_scope_id,created_by)\n   values(p_project_id,ref,e.commercial_scope_id,p_command->>'p_actor') on conflict do nothing returning * into f;\n  if not found then select * into strict f from public.quotes where project_id=p_project_id and commercial_scope_id is not distinct from e.commercial_scope_id; end if;\n  if e.commercial_scope_id is null then update public.projects set quote_ref=f.quote_ref where id=p_project_id and quote_ref is null; end if;\n end if;\n perform pg_advisory_xact_lock(hashtextextended('commercial-quote:'||f.id::text,0));\n perform 1 from public.quote_versions where quote_id=f.id and status='DRAFT' and is_current_draft order by id for update;\n select * into strict r from public.studio_authored_save(p_project_id,p_estimate_id,p_actor_user_id,p_request_id,\n  (p_save->>'expectedUpdatedAt')::timestamptz,(p_save->>'expectedRevision')::bigint,p_save->'authored',p_save->'spatial',p_save->'validatedStoredAuthored',p_client_request);\n select * into strict e from public.estimates where id=p_estimate_id and project_id=p_project_id for update;\n if e.outputs->'studio_authored' is distinct from p_preparation->'p_authored' or e.outputs->'drawing_object_first' is distinct from p_preparation->'p_spatial' then raise exception 'studio_stale' using errcode='PT409'; end if;\n evidence:=(p_preparation->'p_private_evidence')||jsonb_build_object('atomicCreateRequest',p_client_request,\n  'atomicSaveReceipt',jsonb_build_object('revision',r.revision,'savedAt',r.saved_at,'alreadyExisted',r.already_existed));\n perform public.studio_client_quote_prepare(p_project_id,p_estimate_id,p_actor_user_id,p_request_id,e.updated_at,\n  e.outputs->'studio_authored',e.outputs->'drawing_object_first',(p_preparation->>'p_publication_id')::uuid,\n  p_preparation->>'p_content_hash',p_preparation->'p_handoff',evidence,p_preparation->'p_customer_view',p_preparation->'p_drawing_source');\n select c.name into customer from public.projects p left join public.contacts c on c.id=p.contact_id where p.id=p_project_id;\n command:=p_command||jsonb_build_object('p_quote_id',f.id,'p_customer_name',customer);\n q:=public.studio_client_quote_commit('create',p_request_id,p_preparation->>'p_content_hash',command);\n return private.studio_client_quote_created_result(q.id);\nend $$","revoke all on function public.studio_client_quote_create(uuid,uuid,uuid,uuid,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_quote_create(uuid,uuid,uuid,uuid,jsonb,jsonb,jsonb,jsonb) to service_role","-- PDF bytes are produced only after commit. File insertion and cache publication\n-- are one revision-fenced operation, with exact retry returning the same file.\ncreate function public.studio_client_quote_store_pdf(p_quote_version_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,\n p_content_hash text,p_commercial_revision bigint,p_render_hash text,p_preview_payload jsonb,p_filename text,p_content_base64 text)\nreturns uuid language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare q public.quote_versions%rowtype; s private.studio_website_quote_snapshots%rowtype; file_id uuid; bytes bytea;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into strict q from public.quote_versions where id=p_quote_version_id for update;\n select snapshot.* into s from private.studio_website_quote_bindings b join private.studio_website_quote_snapshots snapshot on snapshot.id=b.snapshot_id where b.quote_version_id=q.id;\n if s.id is distinct from p_snapshot_id or s.content_hash is distinct from p_content_hash or q.commercial_revision is distinct from p_commercial_revision\n  or not exists(select 1 from private.studio_client_document_control where singleton and enabled and s.project_id=any(project_ids))\n  then raise exception 'studio_quote_artifact_stale' using errcode='PT409'; end if;\n if p_render_hash is null or p_render_hash !~ '^[a-f0-9]{64}$' or jsonb_typeof(p_preview_payload) is distinct from 'object'\n  or p_filename is null or length(p_filename)>200 or p_content_base64 is null or length(p_content_base64)>11184812 then raise exception 'studio_quote_artifact_invalid'; end if;\n if q.render_hash=p_render_hash and q.pdf_file_id is not null then return q.pdf_file_id; end if;\n bytes:=decode(p_content_base64,'base64');\n if octet_length(bytes) not between 5 and 8388608 or substring(bytes from 1 for 5)<>convert_to('%PDF-','UTF8') then raise exception 'studio_quote_artifact_invalid'; end if;\n insert into public.file_artifacts(project_id,filename,content_type,size_bytes,content_base64,created_by)\n  values(s.project_id,p_filename,'application/pdf',octet_length(bytes),p_content_base64,'studio:client-quote') returning id into file_id;\n update public.quote_versions set render_hash=p_render_hash,preview_base_payload=p_preview_payload,preview_rendered_at=clock_timestamp(),pdf_file_id=file_id where id=q.id;\n return file_id;\nend $$","revoke all on function public.studio_client_quote_store_pdf(uuid,uuid,uuid,text,bigint,text,jsonb,text,text) from public,anon,authenticated","grant execute on function public.studio_client_quote_store_pdf(uuid,uuid,uuid,text,bigint,text,jsonb,text,text) to service_role","notify pgrst,'reload schema'"],"statementSha256":["25893635eae59364cda6f28bbbceb468a070c24151a464049f020e9f7fe2e6aa","c21f4452869bf9188c44b2d4bb96b38b803ee3fe0f7036a9b6da2723aece7209","bcb388252f25579a23e689ecf9eb3fa88f579d7a9646ddcbcabce69e137901a8","6cc11311d5b2eceeca5f3c520e8f875f18dedc97a844d41045ebec1bb66f8faa","3679dc933e598463bf6819e84e1c2bb47646d429af51c00bc3c1bf33eb3ce016","476c9ee560a3a98b221247b8273167539d5f3c3a8dab1736caa6a9db9c5cd56a","528712701eaa233ccf066fb14a757d8d808a0d37dc068b17833c5d015cf4a0ee","66a6db991228781aff5442bebee09cea3321cce794cf0e43504ed3808fc22419","1e0082934977a96dff2ef893f802d0bc9718bd6ad8b97f69ba7f70baa65b79d4","bc7fcc413538be7f60fdd86a2247447c496c1cea10b1ad65c7974249c3443b78","8513ee602506cba1dac881e092b1fbab1ffd2207de1a6e4767a34467463622c3","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c"]},{"version":"20261028132459","name":"studio_client_document_archives","rawSha256":"def889338c3d9060d41bf1f6312883067e32550da4ef80cd48f299265af6b3a6","canonicalLfSha256":"def889338c3d9060d41bf1f6312883067e32550da4ef80cd48f299265af6b3a6","statements":["-- Lossless private transport only. Logical source/render versions and all\n-- canonical role, Save/CAS, publication, financial and address guards remain.\ncreate function private.studio_json_archive_valid(v jsonb,expected_kind text)\nreturns boolean language plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare encoded text; compressed bytea; raw_count numeric; zipped_count numeric;\nbegin\n if jsonb_typeof(v) is distinct from 'object' or (select count(*) from jsonb_object_keys(v))<>8\n  or not(v ?& array['schemaVersion','kind','encoding','decodedBytes','compressedBytes','sha256','compressedSha256','contentBase64'])\n  or v->>'schemaVersion' is distinct from 'studio_json_gzip.v1' or v->>'kind' is distinct from expected_kind or v->>'encoding' is distinct from 'gzip-base64'\n  or jsonb_typeof(v->'decodedBytes') is distinct from 'number' or jsonb_typeof(v->'compressedBytes') is distinct from 'number'\n  or coalesce(v->>'sha256','') !~ '^[a-f0-9]{64}$' or coalesce(v->>'compressedSha256','') !~ '^[a-f0-9]{64}$'\n  or jsonb_typeof(v->'contentBase64') is distinct from 'string' or octet_length(v::text)>16777216 then return false; end if;\n raw_count:=(v->>'decodedBytes')::numeric; zipped_count:=(v->>'compressedBytes')::numeric;\n if raw_count<1 or raw_count>16777216 or raw_count<>trunc(raw_count) or zipped_count<20 or zipped_count>16777216 or zipped_count<>trunc(zipped_count) then return false; end if;\n encoded:=v->>'contentBase64';\n if length(encoded)>16773120 or encoded !~ '^([A-Za-z0-9+/]{4})*([A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$' then return false; end if;\n compressed:=decode(encoded,'base64');\n if octet_length(compressed)<>zipped_count or replace(encode(compressed,'base64'),chr(10),'') is distinct from encoded or get_byte(compressed,0)<>31 or get_byte(compressed,1)<>139\n  or encode(sha256(compressed),'hex') is distinct from v->>'compressedSha256' then return false; end if;\n return true;\nexception when others then return false;\nend $$","revoke all on function private.studio_json_archive_valid(jsonb,text) from public,anon,authenticated,service_role","create function private.studio_drawing_archive_valid(v jsonb)\nreturns boolean language plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare product jsonb; logical_count numeric;\nbegin\n if jsonb_typeof(v) is distinct from 'object' or (select count(*) from jsonb_object_keys(v))<>12\n  or not(v ?& array['schemaVersion','sourceSchemaVersion','rendererVersion','snapshotId','contentHash','designVersionLabel','products','issuedAt','issuedDate','logicalBytes','logicalSha256','archive'])\n  or v->>'schemaVersion' is distinct from 'studio_client_document_archive.v1' or v->>'sourceSchemaVersion' is distinct from 'studio_client_document.v1'\n  or v->>'rendererVersion' is distinct from 'studio-booklet.v1' or coalesce(v->>'logicalSha256','') !~ '^[a-f0-9]{64}$'\n  or jsonb_typeof(v->'logicalBytes') is distinct from 'number' or jsonb_typeof(v->'products') is distinct from 'array'\n  or jsonb_typeof(v->'snapshotId') is distinct from 'string' or jsonb_typeof(v->'contentHash') is distinct from 'string'\n  or coalesce(v->>'designVersionLabel','') !~ '^V[1-9][0-9]*(\\.[0-9]+)?$' or length(v->>'designVersionLabel')>32\n  or jsonb_typeof(v->'issuedAt') is distinct from 'string' or length(v->>'issuedAt')>64\n  or jsonb_typeof(v->'issuedDate') is distinct from 'string' or length(v->>'issuedDate')>64\n  or jsonb_array_length(v->'products')>32 or octet_length(v::text)>16777216\n  or not private.studio_json_archive_valid(v->'archive','studio-drawing-core.v1') then return false; end if;\n logical_count:=(v->>'logicalBytes')::numeric;\n if logical_count<1 or logical_count>16777216 or logical_count<>trunc(logical_count) then return false; end if;\n for product in select value from jsonb_array_elements(v->'products') loop\n  if jsonb_typeof(product) is distinct from 'object' or (select count(*) from jsonb_object_keys(product))<>3\n   or not(product ?& array['id','code','label']) or jsonb_typeof(product->'id') is distinct from 'string'\n   or jsonb_typeof(product->'code') is distinct from 'string' or jsonb_typeof(product->'label') is distinct from 'string'\n   or length(product->>'id') not between 1 and 200 or length(product->>'code') not between 1 and 200 or length(product->>'label') not between 1 and 200 then return false; end if;\n end loop;\n return true;\nexception when others then return false;\nend $$","revoke all on function private.studio_drawing_archive_valid(jsonb) from public,anon,authenticated,service_role","create function private.studio_configuration_archive_valid(v jsonb,publication_id uuid,publication_hash text)\nreturns boolean language plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare n numeric;\nbegin\n if jsonb_typeof(v) is distinct from 'object' or (select count(*) from jsonb_object_keys(v))<>5\n  or not(v ?& array['schemaVersion','versionId','versionNumber','contentHash','archive'])\n  or v->>'schemaVersion' is distinct from 'studio_costing_configuration_archive.v1'\n  or v->>'versionId' is distinct from publication_id::text or v->>'contentHash' is distinct from publication_hash\n  or coalesce(v->>'contentHash','') !~ '^[a-f0-9]{64}$' or jsonb_typeof(v->'versionNumber') is distinct from 'number'\n  or octet_length(v::text)>16777216 or not private.studio_json_archive_valid(v->'archive','studio-costing-configuration.v1') then return false; end if;\n n:=(v->>'versionNumber')::numeric;return n>=1 and n<=9007199254740991 and n=trunc(n);\nexception when others then return false;\nend $$","revoke all on function private.studio_configuration_archive_valid(jsonb,uuid,text) from public,anon,authenticated,service_role","create function private.studio_configuration_stored_valid(v jsonb,publication_id uuid,publication_hash text)\nreturns boolean language plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare n numeric;\nbegin\n if jsonb_typeof(v) is distinct from 'object' then return false; end if;\n if v ? 'archive' or v->>'schemaVersion' like 'studio_costing_configuration_archive.%' then\n  return private.studio_configuration_archive_valid(v,publication_id,publication_hash);\n end if;\n -- Historical plain records remain plain. An unknown archive cannot qualify\n -- merely because the outer JSON value happens to be an object.\n if v->>'id' is distinct from publication_id::text or v->>'contentHash' is distinct from publication_hash\n  or v->>'status' is distinct from 'published' or jsonb_typeof(v->'config') is distinct from 'object'\n  or jsonb_typeof(v->'versionNumber') is distinct from 'number' then return false; end if;\n n:=(v->>'versionNumber')::numeric;return n>=1 and n<=9007199254740991 and n=trunc(n);\nexception when others then return false;\nend $$","revoke all on function private.studio_configuration_stored_valid(jsonb,uuid,text) from public,anon,authenticated,service_role","-- The compressed core excludes these two intentionally reissuable date fields.\n-- Whole-logical hash/size are derived from them and must not redefine retry.\ncreate function private.studio_document_retry_value(v jsonb) returns jsonb\nlanguage sql immutable set search_path=pg_catalog,pg_temp as $$\n select case when v->>'schemaVersion'='studio_client_document_archive.v1' then\n  (v-'issuedAt'-'issuedDate'-'logicalSha256'-'logicalBytes'-'archive')||jsonb_build_object('archive',jsonb_build_object(\n    'schemaVersion',v#>'{archive,schemaVersion}','kind',v#>'{archive,kind}','decodedBytes',v#>'{archive,decodedBytes}','sha256',v#>'{archive,sha256}'))\n  else v-'issuedAt'-'issuedDate' end\n$$","revoke all on function private.studio_document_retry_value(jsonb) from public,anon,authenticated,service_role","create function private.studio_evidence_retry_value(v jsonb) returns jsonb\nlanguage sql immutable set search_path=pg_catalog,pg_temp as $$\n select case when v#>>'{configuration,schemaVersion}'='studio_costing_configuration_archive.v1' then\n  jsonb_set(v,'{configuration}',((v->'configuration')-'archive')||jsonb_build_object('archive',jsonb_build_object(\n   'schemaVersion',v#>'{configuration,archive,schemaVersion}','kind',v#>'{configuration,archive,kind}',\n   'decodedBytes',v#>'{configuration,archive,decodedBytes}','sha256',v#>'{configuration,archive,sha256}')))\n  else v end\n$$","revoke all on function private.studio_evidence_retry_value(jsonb) from public,anon,authenticated,service_role","create or replace function public.studio_client_quote_prepare(\n p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,\n p_expected_updated_at timestamptz,p_authored jsonb,p_spatial jsonb,p_publication_id uuid,\n p_content_hash text,p_handoff jsonb,p_private_evidence jsonb,p_customer_view jsonb,p_drawing_source jsonb\n) returns table(snapshot_id uuid,prepared_at timestamptz)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare e public.estimates%rowtype; previous text; saved_at timestamptz; replay private.studio_website_quote_snapshots%rowtype; item jsonb; kind text;\nbegin\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and p_project_id=any(project_ids)) then raise exception 'studio_client_documents_disabled'; end if;\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then\n  raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into e from public.estimates where id=p_estimate_id and project_id=p_project_id for update;\n if not found or e.status<>'draft' then raise exception 'studio_estimate_unavailable'; end if;\n if (p_drawing_source ? 'archive' or p_drawing_source->>'schemaVersion' like 'studio_client_document_archive.%')\n  and not private.studio_drawing_archive_valid(p_drawing_source) then raise exception 'studio_client_document_invalid'; end if;\n if not private.studio_configuration_stored_valid(p_private_evidence->'configuration',p_publication_id,p_private_evidence#>>'{publication,contentHash}')\n  then raise exception 'studio_client_document_invalid'; end if;\n select * into replay from private.studio_website_quote_snapshots where id=p_snapshot_id;\n if found then\n  if replay.estimate_id is distinct from e.id or replay.actor_user_id is distinct from p_actor_user_id or replay.content_hash is distinct from p_content_hash or replay.customer_view is distinct from p_customer_view or replay.handoff is distinct from p_handoff or replay.authored is distinct from p_authored or replay.spatial is distinct from p_spatial or replay.publication_id is distinct from p_publication_id or private.studio_evidence_retry_value(replay.private_evidence) is distinct from private.studio_evidence_retry_value(p_private_evidence) then raise exception 'studio_prepare_intent_conflict'; end if;\n  if not exists(select 1 from private.studio_client_document_sources d where d.snapshot_id=p_snapshot_id\n   and private.studio_document_retry_value(d.drawing_source) is not distinct from private.studio_document_retry_value(p_drawing_source))\n   then raise exception 'studio_prepare_intent_conflict'; end if;\n  return query select replay.id,replay.created_at; return;\n end if;\n if exists(select 1 from public.quote_versions where source_estimate_version_id=e.id) then raise exception 'studio_estimate_referenced'; end if;\n if e.updated_at is distinct from p_expected_updated_at or e.outputs->'studio_authored' is distinct from p_authored\n  or e.outputs->'drawing_object_first' is distinct from p_spatial then raise exception 'studio_stale' using errcode='PT409'; end if;\n perform 1 from public.costing_configuration_publication where singleton and current_version_id=p_publication_id for share;\n if not found then raise exception 'studio_publication_changed' using errcode='PT409'; end if;\n if p_snapshot_id is null or p_publication_id is null or p_content_hash is null or p_content_hash !~ '^[0-9a-f]{64}$'\n  or jsonb_typeof(p_authored) is distinct from 'object' or jsonb_typeof(p_spatial) is distinct from 'object'\n  or jsonb_typeof(p_private_evidence) is distinct from 'object' or jsonb_typeof(p_customer_view) is distinct from 'object'\n  or jsonb_typeof(p_handoff) is distinct from 'object'\n  or p_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n  or p_customer_view->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_handoff->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_customer_view->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_handoff->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_customer_view->>'contentHash' is distinct from p_content_hash\n  or p_handoff->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_customer_view->'images') is distinct from 'array'\n  or jsonb_typeof(p_customer_view->'selections') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'lines') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'totalIncGstCents') is distinct from 'number'\n  or jsonb_typeof(p_handoff->'source') is distinct from 'object'\n  or octet_length(p_customer_view::text)>8388608 then raise exception 'studio_snapshot_invalid'; end if;\n if jsonb_array_length(p_customer_view->'images')<>0 or jsonb_array_length(p_handoff->'lines')<1\n  or (p_handoff->>'totalIncGstCents')::bigint<=0\n  or jsonb_typeof(p_drawing_source) is distinct from 'object'\n  or coalesce(p_drawing_source->>'schemaVersion','') not in ('studio_client_document.v1','studio_client_document_archive.v1')\n  or (p_drawing_source->>'schemaVersion'='studio_client_document_archive.v1' and not private.studio_drawing_archive_valid(p_drawing_source))\n  or (p_drawing_source->>'schemaVersion'='studio_client_document.v1' and p_drawing_source ? 'archive')\n  or p_drawing_source->>'rendererVersion' is distinct from 'studio-booklet.v1'\n  or p_drawing_source->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_drawing_source->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_drawing_source->'products') is distinct from 'array'\n  or jsonb_array_length(p_drawing_source->'products') not between 0 and 32\n  or jsonb_typeof(p_private_evidence->'configuration') is distinct from 'object'\n  or ((p_private_evidence->'configuration') ? 'archive' and not private.studio_configuration_archive_valid(p_private_evidence->'configuration',p_publication_id,p_private_evidence#>>'{publication,contentHash}'))\n  or octet_length(p_drawing_source::text)>16777216\n  then raise exception 'studio_client_document_invalid'; end if;\n for item in select value from jsonb_array_elements(p_handoff->'lines') loop\n  if jsonb_typeof(item) is distinct from 'object' or coalesce(trim(item->>'description'),'')=''\n   or item->'qty' is distinct from '1'::jsonb or jsonb_typeof(item->'sortOrder') is distinct from 'number'\n   or jsonb_typeof(item->'unitPriceIncGstCents') is distinct from 'number'\n   or item->'lineTotalIncGstCents' is distinct from item->'unitPriceIncGstCents'\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n  if (item->>'unitPriceIncGstCents')::numeric<0 or (item->>'unitPriceIncGstCents')::numeric<>trunc((item->>'unitPriceIncGstCents')::numeric)\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n end loop;\n if (select sum((value->>'lineTotalIncGstCents')::bigint) from jsonb_array_elements(p_handoff->'lines')) is distinct from (p_handoff->>'totalIncGstCents')::bigint\n  or exists(select 1 from jsonb_array_elements(p_handoff->'lines') with ordinality line(value,n) where (value->>'sortOrder')::numeric<>n-1)\n  then raise exception 'studio_snapshot_lines_invalid'; end if;\n insert into private.studio_website_quote_snapshots(id,project_id,estimate_id,commercial_scope_id,actor_user_id,content_hash,\n  authored,spatial,publication_id,handoff,private_evidence,customer_view)\n values(p_snapshot_id,e.project_id,e.id,e.commercial_scope_id,p_actor_user_id,p_content_hash,p_authored,p_spatial,p_publication_id,p_handoff,p_private_evidence,p_customer_view);\n insert into private.studio_client_document_sources(snapshot_id,renderer_version,drawing_source)\n values(p_snapshot_id,'studio-booklet.v1',p_drawing_source);\n previous:=current_setting('sanctuary.studio_command',true);\n perform set_config('sanctuary.studio_command','save',true);\n update public.estimates set outputs=outputs||jsonb_build_object('studio_quote_handoff',p_handoff),\n  pricing_source='workbench_solved',pricing_source_metadata=jsonb_build_object('studioSnapshotId',p_snapshot_id,'studioSnapshotHash',p_content_hash,'studioDocumentMode','separate_v1'),\n  updated_at=clock_timestamp() where id=e.id returning updated_at into saved_at;\n perform set_config('sanctuary.studio_command',coalesce(previous,''),true);\n return query select id,created_at from private.studio_website_quote_snapshots where id=p_snapshot_id;\nend $$","revoke all on function public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb) to service_role","notify pgrst,'reload schema'"],"statementSha256":["59f5aca03b54332474a6a1d964d9cbcb72be66d9e730cf8462c94e80782d19d5","012e13a01950824787773bf80e9d28eb2fed1fa4fa8f84acd79289c900328d75","0833943064dc3da54f723d746a80ce7932b191f2e50a3ed7082afe473f2f431b","fba3dc710c71ef4311cdfa8664b9490a254531151df96a2e0ef3c4b9b9106be0","1b6bf8e1007a39acc0ed3fa2394a55eac5c7d236a07f62dff107cbf2bca5262a","af4d1899fe55a68ef1bf061d72db963a753f2f391aecfb271d9489b5aadfbd1b","7f1802696d9e926f5bd9ed3d9fa017a8dbb0766531b1b84bfdc2bd42288e8bfb","84b2491952c534dfa04635888209d77044367ccb3756ab5d2266e6c9bdbd3888","6421acaf1943be7098e59fc81c85b1166f8a6f5ac511e0b775f2e5222322d360","c0823a823c9d549cba501287672f4b3ea4e37aedeaf75a4222a03c417443c963","30338c36c3dce4ec3e699ca58d84e81b77865b860a3a26e30b6acf6f5269af46","4a909acb267a254f6bd7feaa569d918513869c8e8541c523cc851090eb60e86d","fc765ee1c2d7520a60bf4f8514c53c9a618fb3f1da8198e14d9ba4765c4d7635","34f3f764c19c5ee4e6dc9d91ddf1b94946c323abb522b7f89b7415fca4b12b27","1b9dd647ba1063636312cbafc50022f89ede754d9692c653146db27e12db4a62","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c"]},{"version":"20261028143455","name":"studio_costing_audit_archive","rawSha256":"af1c6a15330b6ed4791f35e7ec3ddaa5d5fc25fe4e47d6f2d3cfe44ff1b1dd0b","canonicalLfSha256":"af1c6a15330b6ed4791f35e7ec3ddaa5d5fc25fe4e47d6f2d3cfe44ff1b1dd0b","statements":["-- Lossless private costing trace only. Fresh price/source/address/financial\n-- authority remains in the existing canonical preparation/commit owners.\ncreate function private.studio_costing_audit_stored_valid(evidence jsonb,publication_id uuid) returns boolean\nlanguage plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare v jsonb;\nbegin\n if jsonb_typeof(evidence) is distinct from 'object' then return false; end if;\n -- Historical plain evidence retains its original representation and retry.\n if not (evidence ? 'audit') then return true; end if;\n if evidence ? 'siteInputs' or evidence ? 'siteOutput' then return false; end if;\n v:=evidence->'audit';\n if jsonb_typeof(v) is distinct from 'object' or (select count(*) from jsonb_object_keys(v))<>4\n  or not (v ?& array['schemaVersion','publicationId','publicationContentHash','archive'])\n  or v->>'schemaVersion' is distinct from 'studio_costing_audit_archive.v1'\n  or v->>'publicationId' is distinct from publication_id::text\n  or jsonb_typeof(v->'publicationId') is distinct from 'string'\n  or jsonb_typeof(v->'publicationContentHash') is distinct from 'string'\n  or coalesce(v->>'publicationContentHash','') !~ '^[a-f0-9]{64}$'\n  or v->>'publicationContentHash' is distinct from evidence#>>'{publication,contentHash}'\n  or evidence#>>'{publication,schemaVersion}' is distinct from 'costing-provenance.v1'\n  or evidence#>>'{publication,source}' is distinct from 'published'\n  or evidence#>>'{publication,versionId}' is distinct from publication_id::text\n  or octet_length(v::text)>16777216 then return false; end if;\n -- SQL verifies compressed representation and binding. Full bounded canonical\n -- decode and exact two-key logical audit validation remain in the Node owner.\n return private.studio_json_archive_valid(v->'archive','studio-costing-audit.v1');\nexception when others then return false;\nend $$","revoke all on function private.studio_costing_audit_stored_valid(jsonb,uuid) from public,anon,authenticated,service_role","-- Semantic retry ignores compression settings/bytes, not the complete decoded\n-- audit identity or any other private evidence fields (including atomic intent).\ncreate or replace function private.studio_evidence_retry_value(v jsonb) returns jsonb\nlanguage sql immutable set search_path=pg_catalog,pg_temp as $$\n with configuration as (\n  select case when v#>>'{configuration,schemaVersion}'='studio_costing_configuration_archive.v1' then\n   jsonb_set(v,'{configuration}',((v->'configuration')-'archive')||jsonb_build_object('archive',jsonb_build_object(\n    'schemaVersion',v#>'{configuration,archive,schemaVersion}','kind',v#>'{configuration,archive,kind}',\n    'decodedBytes',v#>'{configuration,archive,decodedBytes}','sha256',v#>'{configuration,archive,sha256}')))\n   else v end as evidence\n )\n select case when evidence#>>'{audit,schemaVersion}'='studio_costing_audit_archive.v1' then\n  jsonb_set(evidence,'{audit}',((evidence->'audit')-'archive')||jsonb_build_object('archive',jsonb_build_object(\n   'schemaVersion',evidence#>'{audit,archive,schemaVersion}','kind',evidence#>'{audit,archive,kind}',\n   'decodedBytes',evidence#>'{audit,archive,decodedBytes}','sha256',evidence#>'{audit,archive,sha256}')))\n  else evidence end from configuration\n$$","revoke all on function private.studio_evidence_retry_value(jsonb) from public,anon,authenticated,service_role","create or replace function public.studio_client_quote_prepare(\n p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,\n p_expected_updated_at timestamptz,p_authored jsonb,p_spatial jsonb,p_publication_id uuid,\n p_content_hash text,p_handoff jsonb,p_private_evidence jsonb,p_customer_view jsonb,p_drawing_source jsonb\n) returns table(snapshot_id uuid,prepared_at timestamptz)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare e public.estimates%rowtype; previous text; saved_at timestamptz; replay private.studio_website_quote_snapshots%rowtype; item jsonb; kind text;\nbegin\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and p_project_id=any(project_ids)) then raise exception 'studio_client_documents_disabled'; end if;\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then\n  raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into e from public.estimates where id=p_estimate_id and project_id=p_project_id for update;\n if not found or e.status<>'draft' then raise exception 'studio_estimate_unavailable'; end if;\n if (p_drawing_source ? 'archive' or p_drawing_source->>'schemaVersion' like 'studio_client_document_archive.%')\n  and not private.studio_drawing_archive_valid(p_drawing_source) then raise exception 'studio_client_document_invalid'; end if;\n if not private.studio_configuration_stored_valid(p_private_evidence->'configuration',p_publication_id,p_private_evidence#>>'{publication,contentHash}')\n  then raise exception 'studio_client_document_invalid'; end if;\n if not private.studio_costing_audit_stored_valid(p_private_evidence,p_publication_id)\n  then raise exception 'studio_costing_audit_invalid'; end if;\n select * into replay from private.studio_website_quote_snapshots where id=p_snapshot_id;\n if found then\n  if replay.estimate_id is distinct from e.id or replay.actor_user_id is distinct from p_actor_user_id or replay.content_hash is distinct from p_content_hash or replay.customer_view is distinct from p_customer_view or replay.handoff is distinct from p_handoff or replay.authored is distinct from p_authored or replay.spatial is distinct from p_spatial or replay.publication_id is distinct from p_publication_id or private.studio_evidence_retry_value(replay.private_evidence) is distinct from private.studio_evidence_retry_value(p_private_evidence) then raise exception 'studio_prepare_intent_conflict'; end if;\n  if not exists(select 1 from private.studio_client_document_sources d where d.snapshot_id=p_snapshot_id\n   and private.studio_document_retry_value(d.drawing_source) is not distinct from private.studio_document_retry_value(p_drawing_source))\n   then raise exception 'studio_prepare_intent_conflict'; end if;\n  return query select replay.id,replay.created_at; return;\n end if;\n if exists(select 1 from public.quote_versions where source_estimate_version_id=e.id) then raise exception 'studio_estimate_referenced'; end if;\n if e.updated_at is distinct from p_expected_updated_at or e.outputs->'studio_authored' is distinct from p_authored\n  or e.outputs->'drawing_object_first' is distinct from p_spatial then raise exception 'studio_stale' using errcode='PT409'; end if;\n perform 1 from public.costing_configuration_publication where singleton and current_version_id=p_publication_id for share;\n if not found then raise exception 'studio_publication_changed' using errcode='PT409'; end if;\n if p_snapshot_id is null or p_publication_id is null or p_content_hash is null or p_content_hash !~ '^[0-9a-f]{64}$'\n  or jsonb_typeof(p_authored) is distinct from 'object' or jsonb_typeof(p_spatial) is distinct from 'object'\n  or jsonb_typeof(p_private_evidence) is distinct from 'object' or jsonb_typeof(p_customer_view) is distinct from 'object'\n  or jsonb_typeof(p_handoff) is distinct from 'object'\n  or p_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n  or p_customer_view->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_handoff->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_customer_view->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_handoff->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_customer_view->>'contentHash' is distinct from p_content_hash\n  or p_handoff->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_customer_view->'images') is distinct from 'array'\n  or jsonb_typeof(p_customer_view->'selections') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'lines') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'totalIncGstCents') is distinct from 'number'\n  or jsonb_typeof(p_handoff->'source') is distinct from 'object'\n  or octet_length(p_customer_view::text)>8388608 then raise exception 'studio_snapshot_invalid'; end if;\n if jsonb_array_length(p_customer_view->'images')<>0 or jsonb_array_length(p_handoff->'lines')<1\n  or (p_handoff->>'totalIncGstCents')::bigint<=0\n  or jsonb_typeof(p_drawing_source) is distinct from 'object'\n  or coalesce(p_drawing_source->>'schemaVersion','') not in ('studio_client_document.v1','studio_client_document_archive.v1')\n  or (p_drawing_source->>'schemaVersion'='studio_client_document_archive.v1' and not private.studio_drawing_archive_valid(p_drawing_source))\n  or (p_drawing_source->>'schemaVersion'='studio_client_document.v1' and p_drawing_source ? 'archive')\n  or p_drawing_source->>'rendererVersion' is distinct from 'studio-booklet.v1'\n  or p_drawing_source->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_drawing_source->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_drawing_source->'products') is distinct from 'array'\n  or jsonb_array_length(p_drawing_source->'products') not between 0 and 32\n  or jsonb_typeof(p_private_evidence->'configuration') is distinct from 'object'\n  or ((p_private_evidence->'configuration') ? 'archive' and not private.studio_configuration_archive_valid(p_private_evidence->'configuration',p_publication_id,p_private_evidence#>>'{publication,contentHash}'))\n  or octet_length(p_drawing_source::text)>16777216\n  then raise exception 'studio_client_document_invalid'; end if;\n for item in select value from jsonb_array_elements(p_handoff->'lines') loop\n  if jsonb_typeof(item) is distinct from 'object' or coalesce(trim(item->>'description'),'')=''\n   or item->'qty' is distinct from '1'::jsonb or jsonb_typeof(item->'sortOrder') is distinct from 'number'\n   or jsonb_typeof(item->'unitPriceIncGstCents') is distinct from 'number'\n   or item->'lineTotalIncGstCents' is distinct from item->'unitPriceIncGstCents'\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n  if (item->>'unitPriceIncGstCents')::numeric<0 or (item->>'unitPriceIncGstCents')::numeric<>trunc((item->>'unitPriceIncGstCents')::numeric)\n   then raise exception 'studio_snapshot_lines_invalid'; end if;\n end loop;\n if (select sum((value->>'lineTotalIncGstCents')::bigint) from jsonb_array_elements(p_handoff->'lines')) is distinct from (p_handoff->>'totalIncGstCents')::bigint\n  or exists(select 1 from jsonb_array_elements(p_handoff->'lines') with ordinality line(value,n) where (value->>'sortOrder')::numeric<>n-1)\n  then raise exception 'studio_snapshot_lines_invalid'; end if;\n insert into private.studio_website_quote_snapshots(id,project_id,estimate_id,commercial_scope_id,actor_user_id,content_hash,\n  authored,spatial,publication_id,handoff,private_evidence,customer_view)\n values(p_snapshot_id,e.project_id,e.id,e.commercial_scope_id,p_actor_user_id,p_content_hash,p_authored,p_spatial,p_publication_id,p_handoff,p_private_evidence,p_customer_view);\n insert into private.studio_client_document_sources(snapshot_id,renderer_version,drawing_source)\n values(p_snapshot_id,'studio-booklet.v1',p_drawing_source);\n previous:=current_setting('sanctuary.studio_command',true);\n perform set_config('sanctuary.studio_command','save',true);\n update public.estimates set outputs=outputs||jsonb_build_object('studio_quote_handoff',p_handoff),\n  pricing_source='workbench_solved',pricing_source_metadata=jsonb_build_object('studioSnapshotId',p_snapshot_id,'studioSnapshotHash',p_content_hash,'studioDocumentMode','separate_v1'),\n  updated_at=clock_timestamp() where id=e.id returning updated_at into saved_at;\n perform set_config('sanctuary.studio_command',coalesce(previous,''),true);\n return query select id,created_at from private.studio_website_quote_snapshots where id=p_snapshot_id;\nend $$","revoke all on function public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamptz,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb) to service_role","notify pgrst,'reload schema'"],"statementSha256":["950a8e421b4c595e952649a63d73b0187ad4f82c5469e295d44f71626e5ee67c","8871beb7f8e1284de4ba45d1cc996ac8772352354c1c1fd988df876083f2cc6a","991cb178694d603cf5ef3b227e4aa653e0ee7a19a8575b423305e279a66451f8","4a909acb267a254f6bd7feaa569d918513869c8e8541c523cc851090eb60e86d","eeb80964367846ad0b8c923562e7d75c0c8038fa884b558ebdf586c04f69cf54","34f3f764c19c5ee4e6dc9d91ddf1b94946c323abb522b7f89b7415fca4b12b27","1b9dd647ba1063636312cbafc50022f89ede754d9692c653146db27e12db4a62","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c"]},{"version":"20261029042636","name":"studio_booklet_approved_inventory","rawSha256":"fbecad72b8288faa3aea7b27498c50b61cadbeae91f901f05a30068237a39a6e","canonicalLfSha256":"158d728b9413726e9d68cf996dbd9753ed203636ff693feb14c9e91cf9dfa756","statements":["-- Owner-approved Studio drawing inventory. Historical sources and checkpoints\n-- retain their original page count; only a frozen v3 manifest expands it.\ncreate function private.studio_document_manifest_valid(v jsonb) returns boolean\nlanguage plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare manifest jsonb; product jsonb; page jsonb; cursor_index integer:=1; expected_kind text; expected_code text;\nbegin\n if jsonb_typeof(v) is distinct from 'object' then return false; end if;\n if not(v ? 'layoutVersion') then return not(v ? 'pageManifest'); end if;\n if jsonb_typeof(v->'layoutVersion') is distinct from 'string' then return false; end if;\n if v->>'layoutVersion'='studio-booklet-layout.v2' then return not(v ? 'pageManifest'); end if;\n if v->>'layoutVersion'<>'studio-booklet-layout.v3' then return false; end if;\n manifest:=v->'pageManifest';\n if jsonb_typeof(manifest) is distinct from 'array' or jsonb_array_length(manifest) not between 1 and 193\n  or jsonb_typeof(v->'products') is distinct from 'array' or jsonb_array_length(v->'products')>32\n  or (select count(distinct value->>'id') from jsonb_array_elements(v->'products'))<>jsonb_array_length(v->'products')\n  or manifest->0 is distinct from '{\"index\":0,\"key\":\"cover\",\"kind\":\"cover\",\"label\":\"Design overview and drawing register\",\"code\":\"A00\"}'::jsonb then return false; end if;\n for product in select value from jsonb_array_elements(v->'products') loop\n  foreach expected_kind in array array['plan','iso','elevation','lighting','blind-plan','blind-elevation'] loop\n   page:=manifest->cursor_index;\n   if expected_kind='lighting' and page->>'kind' is distinct from 'lighting' then continue; end if;\n   if expected_kind='blind-plan' and page->>'kind' is distinct from 'blind-plan' then continue; end if;\n   if expected_kind='blind-elevation' and manifest->(cursor_index-1)->>'kind' is distinct from 'blind-plan' then continue; end if;\n   expected_code:='A'||cursor_index::text;\n   if cursor_index<10 then expected_code:='A0'||cursor_index::text; end if;\n   if jsonb_typeof(page) is distinct from 'object' or (select count(*) from jsonb_object_keys(page))<>6\n    or not(page ?& array['index','key','kind','objectId','label','code'])\n    or page->'index' is distinct from to_jsonb(cursor_index)\n    or page->>'kind' is distinct from expected_kind\n    or page->>'objectId' is distinct from product->>'id'\n    or page->>'key' is distinct from (product->>'id')||':'||expected_kind\n    or page->>'code' is distinct from expected_code\n    or jsonb_typeof(page->'label') is distinct from 'string' or length(page->>'label') not between 1 and 260 then return false; end if;\n   cursor_index:=cursor_index+1;\n  end loop;\n end loop;\n return cursor_index=jsonb_array_length(manifest);\nexception when others then return false;\nend $$","revoke all on function private.studio_document_manifest_valid(jsonb) from public,anon,authenticated,service_role","create function private.studio_document_total_pages(v jsonb) returns integer\nlanguage plpgsql immutable set search_path=pg_catalog,pg_temp as $$\nbegin\n if not private.studio_document_manifest_valid(v) then raise exception 'studio_document_inventory_invalid'; end if;\n if v->>'layoutVersion'='studio-booklet-layout.v3' then return jsonb_array_length(v->'pageManifest'); end if;\n return 1+2*jsonb_array_length(v->'products');\nend $$","revoke all on function private.studio_document_total_pages(jsonb) from public,anon,authenticated,service_role","alter table private.studio_client_documents drop constraint studio_client_documents_total_pages_check","alter table private.studio_client_documents add constraint studio_client_documents_total_pages_check check(total_pages between 1 and 193)","create function private.studio_drawing_archive_valid_pre_v3(v jsonb)\nreturns boolean language plpgsql immutable set search_path=pg_catalog,pg_temp as $$\ndeclare product jsonb; logical_count numeric;\nbegin\n if jsonb_typeof(v) is distinct from 'object' or (select count(*) from jsonb_object_keys(v))<>12\n  or not(v ?& array['schemaVersion','sourceSchemaVersion','rendererVersion','snapshotId','contentHash','designVersionLabel','products','issuedAt','issuedDate','logicalBytes','logicalSha256','archive'])\n  or v->>'schemaVersion' is distinct from 'studio_client_document_archive.v1' or v->>'sourceSchemaVersion' is distinct from 'studio_client_document.v1'\n  or v->>'rendererVersion' is distinct from 'studio-booklet.v1' or coalesce(v->>'logicalSha256','') !~ '^[a-f0-9]{64}$'\n  or jsonb_typeof(v->'logicalBytes') is distinct from 'number' or jsonb_typeof(v->'products') is distinct from 'array'\n  or jsonb_typeof(v->'snapshotId') is distinct from 'string' or jsonb_typeof(v->'contentHash') is distinct from 'string'\n  or coalesce(v->>'designVersionLabel','') !~ '^V[1-9][0-9]*(\\.[0-9]+)?$' or length(v->>'designVersionLabel')>32\n  or jsonb_typeof(v->'issuedAt') is distinct from 'string' or length(v->>'issuedAt')>64\n  or jsonb_typeof(v->'issuedDate') is distinct from 'string' or length(v->>'issuedDate')>64\n  or jsonb_array_length(v->'products')>32 or octet_length(v::text)>16777216\n  or not private.studio_json_archive_valid(v->'archive','studio-drawing-core.v1') then return false; end if;\n logical_count:=(v->>'logicalBytes')::numeric;\n if logical_count<1 or logical_count>16777216 or logical_count<>trunc(logical_count) then return false; end if;\n for product in select value from jsonb_array_elements(v->'products') loop\n  if jsonb_typeof(product) is distinct from 'object' or (select count(*) from jsonb_object_keys(product))<>3\n   or not(product ?& array['id','code','label']) or jsonb_typeof(product->'id') is distinct from 'string'\n   or jsonb_typeof(product->'code') is distinct from 'string' or jsonb_typeof(product->'label') is distinct from 'string'\n   or length(product->>'id') not between 1 and 200 or length(product->>'code') not between 1 and 200 or length(product->>'label') not between 1 and 200 then return false; end if;\n end loop;\n return true;\nexception when others then return false;\nend $$","revoke all on function private.studio_drawing_archive_valid_pre_v3(jsonb) from public,anon,authenticated,service_role","create or replace function private.studio_drawing_archive_valid(v jsonb) returns boolean\nlanguage plpgsql immutable set search_path=pg_catalog,pg_temp as $$\nbegin\n if v->>'layoutVersion'='studio-booklet-layout.v3' then\n  return (select count(*) from jsonb_object_keys(v))=14\n   and private.studio_document_manifest_valid(v)\n   and private.studio_drawing_archive_valid_pre_v3(v-'layoutVersion'-'pageManifest');\n end if;\n return private.studio_document_manifest_valid(v) and private.studio_drawing_archive_valid_pre_v3(v);\nexception when others then return false;\nend $$","revoke all on function private.studio_drawing_archive_valid(jsonb) from public,anon,authenticated,service_role","create or replace function public.studio_client_quote_prepare(\n p_project_id uuid,p_estimate_id uuid,p_actor_user_id uuid,p_snapshot_id uuid,\n p_expected_updated_at timestamptz,p_authored jsonb,p_spatial jsonb,p_publication_id uuid,\n p_content_hash text,p_handoff jsonb,p_private_evidence jsonb,p_customer_view jsonb,p_drawing_source jsonb\n) returns table(snapshot_id uuid,prepared_at timestamptz)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare e public.estimates%rowtype; previous text; saved_at timestamptz; replay private.studio_website_quote_snapshots%rowtype; item jsonb; kind text;\nbegin\n if not private.studio_document_manifest_valid(p_drawing_source) then raise exception 'studio_document_inventory_invalid'; end if;\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and p_project_id=any(project_ids)) then raise exception 'studio_client_documents_disabled'; end if;\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then\n  raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into e from public.estimates where id=p_estimate_id and project_id=p_project_id for update;\n if not found or e.status<>'draft' then raise exception 'studio_estimate_unavailable'; end if;\n if (p_drawing_source ? 'archive' or p_drawing_source->>'schemaVersion' like 'studio_client_document_archive.%')\n  and not private.studio_drawing_archive_valid(p_drawing_source) then raise exception 'studio_client_document_invalid'; end if;\n if not private.studio_configuration_stored_valid(p_private_evidence->'configuration',p_publication_id,p_private_evidence#>>'{publication,contentHash}')\n  then raise exception 'studio_client_document_invalid'; end if;\n if not private.studio_costing_audit_stored_valid(p_private_evidence,p_publication_id)\n  then raise exception 'studio_costing_audit_invalid'; end if;\n select * into replay from private.studio_website_quote_snapshots where id=p_snapshot_id;\n if found then\n  if replay.estimate_id is distinct from e.id or replay.actor_user_id is distinct from p_actor_user_id or replay.content_hash is distinct from p_content_hash or replay.customer_view is distinct from p_customer_view or replay.handoff is distinct from p_handoff or replay.authored is distinct from p_authored or replay.spatial is distinct from p_spatial or replay.publication_id is distinct from p_publication_id or private.studio_evidence_retry_value(replay.private_evidence) is distinct from private.studio_evidence_retry_value(p_private_evidence) then raise exception 'studio_prepare_intent_conflict'; end if;\n  if not exists(select 1 from private.studio_client_document_sources d where d.snapshot_id=p_snapshot_id\n   and private.studio_document_retry_value(d.drawing_source) is not distinct from private.studio_document_retry_value(p_drawing_source))\n   then raise exception 'studio_prepare_intent_conflict'; end if;\n  return query select replay.id,replay.created_at; return;\n end if;\n if exists(select 1 from public.quote_versions where source_estimate_version_id=e.id) then raise exception 'studio_estimate_referenced'; end if;\n if e.updated_at is distinct from p_expected_updated_at or e.outputs->'studio_authored' is distinct from p_authored\n  or e.outputs->'drawing_object_first' is distinct from p_spatial then raise exception 'studio_stale' using errcode='PT409'; end if;\n perform 1 from public.costing_configuration_publication where singleton and current_version_id=p_publication_id for share;\n if not found then raise exception 'studio_publication_changed' using errcode='PT409'; end if;\n if p_snapshot_id is null or p_publication_id is null or p_content_hash is null or p_content_hash !~ '^[0-9a-f]{64}$'\n  or jsonb_typeof(p_authored) is distinct from 'object' or jsonb_typeof(p_spatial) is distinct from 'object'\n  or jsonb_typeof(p_private_evidence) is distinct from 'object' or jsonb_typeof(p_customer_view) is distinct from 'object'\n  or jsonb_typeof(p_handoff) is distinct from 'object'\n  or p_authored->>'schemaVersion' is distinct from 'studio_authored.v1'\n  or p_customer_view->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_handoff->>'schemaVersion' is distinct from 'studio_quote_snapshot.v2'\n  or p_customer_view->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_handoff->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_customer_view->>'contentHash' is distinct from p_content_hash\n  or p_handoff->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_customer_view->'images') is distinct from 'array'\n  or jsonb_typeof(p_customer_view->'selections') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'lines') is distinct from 'array'\n  or jsonb_typeof(p_handoff->'totalIncGstCents') is distinct from 'number'\n  or jsonb_typeof(p_handoff->'source') is distinct from 'object'\n  or octet_length(p_customer_view::text)>8388608 then raise exception 'studio_snapshot_invalid'; end if;\n if jsonb_array_length(p_customer_view->'images')<>0 or jsonb_array_length(p_handoff->'lines')<1\n  or (p_handoff->>'totalIncGstCents')::bigint<=0\n  or jsonb_typeof(p_drawing_source) is distinct from 'object'\n  or coalesce(p_drawing_source->>'schemaVersion','') not in ('studio_client_document.v1','studio_client_document_archive.v1')\n  or (p_drawing_source->>'schemaVersion'='studio_client_document_archive.v1' and not private.studio_drawing_archive_valid(p_drawing_source))\n  or (p_drawing_source->>'schemaVersion'='studio_client_document.v1' and p_drawing_source ? 'archive')\n  or p_drawing_source->>'rendererVersion' is distinct from 'studio-booklet.v1'\n  or p_drawing_source->>'snapshotId' is distinct from p_snapshot_id::text\n  or p_drawing_source->>'contentHash' is distinct from p_content_hash\n  or jsonb_typeof(p_drawing_source->'products') is distinct from 'array'\n  or jsonb_array_length(p_drawing_source->'products') not between 0 and 32\n  or jsonb_typeof(p_private_evidence->'configuration') is distinct from 'object'\n  or ((p_private_evidence->'configuration') ? 'archive' and not private.studio_configuration_archive_valid(p_private_evidence->'configuration',p_publication_id,p_private_evidence#>>'{publication,contentHash}'))\n  or octet_length(p_drawing_source::text)>16777216\n  then raise exception 'studio_client_document_invalid'; end if;\n for item in select value from jsonb_array_elements(p_handoff->'lines') loop\n  if jsonb_typeof(item) is distinct from 'object' or coalesce(trim(item->>'description'),'')=''\n   or item->'qty' is distinct from '1'::jsonb or jsonb_typeof(item->'sortOrder') is distinct from 'number'\n   or jsonb_typeof(item->'unitPriceIncGstCents') is distinct from 'number'\n   or item->'lineTotalIncGstCents' is distinct from item->