(d.drawing_source->'layoutVersion')='string' and d.drawing_source->>'layoutVersion' in ('studio-booklet-layout.v2','studio-booklet-layout.v3','studio-booklet-layout.v4') then d.drawing_source->>'layoutVersion' else '' end)))\n  order by q.msg_id limit p_batch_size for update of q skip locked\n ), touched as (\n  update pgmq.q_portal_background_jobs q set vt=clock_timestamp()+make_interval(secs=>p_visibility_timeout_seconds),read_ct=q.read_ct+1\n  from candidates c where q.msg_id=c.msg_id returning q.msg_id,q.message\n ) select t.msg_id,t.message from touched t order by t.msg_id;\nend $$","revoke all on function private.background_job_read_claim_queue(integer,integer) from public,anon,authenticated,service_role","create or replace function public.background_jobs_claim_documents(p_worker_id text,p_batch_size integer,p_visibility_timeout_seconds integer,p_kinds text[],p_project_ids uuid[],p_manifest_versions text[])\nreturns table(job_id uuid,kind text,contract_version integer,status public.background_job_status,current_phase text,attempt_number integer,max_attempts integer,queue_message_id bigint,lease_token uuid,lease_expires_at timestamptz,cancellation_requested_at timestamptz,rollout_mode public.background_job_rollout_mode,execution_owner public.background_job_execution_owner)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare previous_versions text:=current_setting('sanctuary.studio_document_manifest_versions',true);\nbegin\n if p_kinds is distinct from array['studio_design_booklet_v1']::text[]\n  or p_manifest_versions is null or cardinality(p_manifest_versions) not between 1 and 4\n  or array_position(p_manifest_versions,null) is not null\n  or exists(select 1 from unnest(p_manifest_versions) version where version not in ('legacy','studio-booklet-layout.v2','studio-booklet-layout.v3','studio-booklet-layout.v4'))\n then raise exception 'invalid_document_manifest_capability' using errcode='22023'; end if;\n perform set_config('sanctuary.studio_document_manifest_versions',to_jsonb(p_manifest_versions)::text,true);\n return query select * from public.background_jobs_claim_scoped(p_worker_id,p_batch_size,p_visibility_timeout_seconds,p_kinds,p_project_ids);\n perform set_config('sanctuary.studio_document_manifest_versions',coalesce(previous_versions,''),true);\nexception when others then\n perform set_config('sanctuary.studio_document_manifest_versions',coalesce(previous_versions,''),true);\n raise;\nend $$","revoke all on function public.background_jobs_claim_documents(text,integer,integer,text[],uuid[],text[]) from public,anon,authenticated","grant execute on function public.background_jobs_claim_documents(text,integer,integer,text[],uuid[],text[]) to service_role","-- A financial-only quote retains its frozen source but creates no empty PDF/job.\ncreate or replace function public.studio_client_quote_commit(p_operation text,p_snapshot_id uuid,p_content_hash text,p_command jsonb)\nreturns public.quote_versions language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare s private.studio_website_quote_snapshots%rowtype; d private.studio_client_document_sources%rowtype; q public.quote_versions%rowtype; j public.background_jobs%rowtype; prior_stage text;\nbegin\n select * into s from private.studio_website_quote_snapshots where id=p_snapshot_id and content_hash=p_content_hash;\n select * into d from private.studio_client_document_sources where snapshot_id=p_snapshot_id;\n if s.id is null or d.snapshot_id is null or s.customer_view->>'schemaVersion'<>'studio_quote_snapshot.v2'\n  or not exists(select 1 from private.studio_client_document_control where singleton and enabled and s.project_id=any(project_ids))\n then raise exception 'studio_client_document_unavailable'; end if;\n -- Serialize only new client-document commands on the same project before\n -- the canonical quote/address locks. Avoid two SHARE-to-UPDATE conversions.\n perform pg_advisory_xact_lock(hashtextextended('studio-client-quote-project:'||s.project_id::text,0));\n q:=public.studio_website_quote_commit_address(p_operation,p_snapshot_id,p_content_hash,p_command);\n if private.studio_document_total_pages(d.drawing_source)>0 then\n if not exists(select 1 from private.studio_client_documents where snapshot_id=s.id) then\n  insert into private.studio_client_documents(snapshot_id,project_id,quote_version_id,renderer_version,total_pages)\n  values(s.id,s.project_id,q.id,d.renderer_version,private.studio_document_total_pages(d.drawing_source));\n end if;\n perform private.studio_client_document_enqueue(s.id);\n end if;\n if p_operation='create' and not exists(select 1 from public.audit_events where idempotency_key='studio:quote-created:'||q.id::text) then\n  select pipeline_stage into prior_stage from public.projects where id=s.project_id;\n  update public.projects set pipeline_stage='QUOTING' where id=s.project_id;\n  insert into public.audit_events(project_id,type,idempotency_key,payload) values\n   (s.project_id,'pipeline.stage_changed','studio:quote-stage:'||q.id::text,jsonb_build_object('fromStage',prior_stage,'toStage','QUOTING','quoteId',q.id)),\n   (s.project_id,'quote.created','studio:quote-created:'||q.id::text,coalesce(p_command->'p_studio_created_audit','{}'::jsonb)||jsonb_build_object('quoteVersionId',q.id));\n end if;\n return q;\nend $$","create or replace function public.studio_client_document_status(p_quote_version_id uuid,p_actor_user_id uuid,p_download boolean default false)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; j public.background_jobs%rowtype; completed integer; result jsonb; empty_source private.studio_client_document_sources%rowtype;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id;\n if not found then\n  select g.* into empty_source from private.studio_website_quote_bindings b\n   join private.studio_client_document_sources g on g.snapshot_id=b.snapshot_id\n   where b.quote_version_id=p_quote_version_id and g.drawing_source->>'layoutVersion'='studio-booklet-layout.v4';\n  if found and private.studio_document_total_pages(empty_source.drawing_source)=0 then\n   return jsonb_build_object('snapshotId',empty_source.snapshot_id,'rendererVersion',empty_source.renderer_version,\n    'completedPages',0,'totalPages',0,'state','unavailable','percent',0,'canRetry',false);\n  end if;\n  return null;\n end if;\n select * into j from public.background_jobs where id=d.job_id;\n select count(*) into completed from private.studio_client_document_pages where snapshot_id=d.snapshot_id;\n result:=jsonb_build_object('snapshotId',d.snapshot_id,'rendererVersion',d.renderer_version,'completedPages',completed,'totalPages',d.total_pages,\n  'state',case when d.file_id is not null then 'ready' when d.enqueue_failed or j.status in ('needs_attention','permanent_failed','cancelled') then 'failed' when j.status='queued' then 'queued' else 'running' end,\n  'percent',case when d.file_id is not null then 100 else floor(completed*100.0/(d.total_pages+1)) end,\n  'canRetry',d.file_id is null and (d.enqueue_failed or (j.status in ('needs_attention','permanent_failed') and j.attempt_count<4)));\n if p_download and d.file_id is not null then result:=result||jsonb_build_object('file',(select jsonb_build_object('filename',filename,'contentBase64',content_base64) from public.file_artifacts where id=d.file_id and project_id=d.project_id)); end if;\n return result;\nend $$","revoke all on function public.studio_client_document_status(uuid,uuid,boolean) from public,anon,authenticated","grant execute on function public.studio_client_document_status(uuid,uuid,boolean) to service_role"],"statementSha256":["ce2d8fe8202a2f31468c41e88dccbcc2417855570e414525699ec4fe10f4fac8","8e35692761c048ad042461930db705d585fc3eb1d83aabf9baf638eae53695b5","9b41e2d43d34c0d84c6728583f66254c7dc1c3306ba367b711fc2262bcc5bdba","17b9c1f319ec8849668354cb3e1c52ac3b10f98aee73f4ca37dfd346c544c3be","3d24d2862151dc58b0d5bd1eda990545548c2e966171bafeb35dd501f395ae86","fba3dc710c71ef4311cdfa8664b9490a254531151df96a2e0ef3c4b9b9106be0","8b0cb400d29197850c79ada7162ca93f13e70768a26f2795ea4fb0ad1b09357c","5f3eb439b1db54f0947cdda0d8e3261adb06ee7cadd51b85a781b0d6e95a3580","9763ce90025dd035bba21d857c44589d59c37967fbb7c49b25542695cd7ff912","fdbbcda50a385a22a5c4653cb2e3188df1f3e0522c0816b7a019fda5ec735c3e","d979a3a6f75825ef4050057c5f3c77e87779281427ad31762dc7ef7a8e8dd713","7575a89a4a13910e37864c0ddf0f6fa3fb73100ea2776ca41a8cdc0db481ae46","4d5b7f1b81970c3fbca36429f3cb0b0794c94f6000d4d88e3da4ef3ddcd4c9b2","bc890fdc49d05731ec90059a127e213e6eef5191a0794a7daaf51f341eb645e0","856da40db11680f4ebab4d9be7b7289a51f8dfcfb3665356271c3d7326208c83"]},{"version":"20261029231641","name":"studio_client_package_variants","rawSha256":"2a0089bef8efc43614289d4fffe7d7e9fc3b1f521a496f375096a7a073ad61db","canonicalLfSha256":"c09e784c2c12a4f79109211c065cf457207d304019b13b85508480ce2fb92060","statements":["-- Generalise the existing immutable Studio document pipeline. No source or PDF is overwritten.\n-- Service-only RPCs below are reached only after caller-RLS quote/project admission.\nalter table private.studio_client_documents add column document_id uuid","update private.studio_client_documents set document_id=snapshot_id","alter table private.studio_client_documents alter column document_id set not null","alter table private.studio_client_document_pages drop constraint studio_client_document_pages_snapshot_id_fkey","alter table private.studio_client_documents drop constraint studio_client_documents_pkey","alter table private.studio_client_documents add primary key(document_id)","alter table private.studio_client_documents add column variant_manifest jsonb, add column render_assets jsonb not null default '[]', add column variant_hash text","create unique index studio_client_documents_base on private.studio_client_documents(snapshot_id) where variant_manifest is null","create unique index studio_client_documents_variant on private.studio_client_documents(snapshot_id,variant_hash) where variant_manifest is not null","alter table private.studio_client_document_pages rename column snapshot_id to document_id","alter table private.studio_client_document_pages add foreign key(document_id) references private.studio_client_documents(document_id)","alter table private.studio_client_documents drop constraint studio_client_documents_total_pages_check","alter table private.studio_client_documents add check(total_pages between 1 and 200)","alter table private.studio_client_document_pages drop constraint studio_client_document_pages_page_index_check","alter table private.studio_client_document_pages add check(page_index between 0 and 199)","create or replace function private.studio_client_document_enqueue(p_snapshot_id uuid)\nreturns void language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; s private.studio_website_quote_snapshots%rowtype; j public.background_jobs%rowtype;\nbegin\n select * into d from private.studio_client_documents where document_id=p_snapshot_id for update;\n if d.snapshot_id is null or d.job_id is not null or d.file_id is not null then return; end if;\n if not exists(select 1 from private.studio_client_document_control where singleton and enabled and d.project_id=any(project_ids)) then raise exception 'studio_client_document_unavailable'; end if;\n select * into s from private.studio_website_quote_snapshots where id=d.snapshot_id;\n begin\n  j:=private.background_job_enqueue_core('studio_design_booklet_v1',1,case when d.variant_manifest is null then 'studio_snapshot' else 'studio_document' end,d.document_id::text,s.project_id,s.actor_user_id,'staff',100::smallint,\n   'studio-booklet:'||d.document_id::text||':'||d.renderer_version,jsonb_build_object('contractVersion',1,'snapshotId',s.id,'rendererVersion',d.renderer_version)||case when d.variant_manifest is null then '{}'::jsonb else jsonb_build_object('documentId',d.document_id,'variantVersion','studio-booklet-renders.v1') end,null,'worker_enabled','worker','studio-client-documents-local');\n  update private.studio_client_documents set job_id=j.id,enqueue_failed=false where document_id=d.document_id;\n exception when others then\n  update private.studio_client_documents set enqueue_failed=true where document_id=d.document_id;\n end;\nend $$","create or replace function public.studio_client_quote_commit(p_operation text,p_snapshot_id uuid,p_content_hash text,p_command jsonb)\nreturns public.quote_versions language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare s private.studio_website_quote_snapshots%rowtype; d private.studio_client_document_sources%rowtype; q public.quote_versions%rowtype; j public.background_jobs%rowtype; prior_stage text;\nbegin\n select * into s from private.studio_website_quote_snapshots where id=p_snapshot_id and content_hash=p_content_hash;\n select * into d from private.studio_client_document_sources where snapshot_id=p_snapshot_id;\n if s.id is null or d.snapshot_id is null or s.customer_view->>'schemaVersion'<>'studio_quote_snapshot.v2'\n  or not exists(select 1 from private.studio_client_document_control where singleton and enabled and s.project_id=any(project_ids))\n then raise exception 'studio_client_document_unavailable'; end if;\n -- Serialize only new client-document commands on the same project before\n -- the canonical quote/address locks. Avoid two SHARE-to-UPDATE conversions.\n perform pg_advisory_xact_lock(hashtextextended('studio-client-quote-project:'||s.project_id::text,0));\n q:=public.studio_website_quote_commit_address(p_operation,p_snapshot_id,p_content_hash,p_command);\n if private.studio_document_total_pages(d.drawing_source)>0 then\n if not exists(select 1 from private.studio_client_documents where snapshot_id=s.id and variant_manifest is null) then\n  insert into private.studio_client_documents(document_id,snapshot_id,project_id,quote_version_id,renderer_version,total_pages)\n  values(s.id,s.id,s.project_id,q.id,d.renderer_version,private.studio_document_total_pages(d.drawing_source));\n end if;\n perform private.studio_client_document_enqueue(s.id);\n end if;\n if p_operation='create' and not exists(select 1 from public.audit_events where idempotency_key='studio:quote-created:'||q.id::text) then\n  select pipeline_stage into prior_stage from public.projects where id=s.project_id;\n  update public.projects set pipeline_stage='QUOTING' where id=s.project_id;\n  insert into public.audit_events(project_id,type,idempotency_key,payload) values\n   (s.project_id,'pipeline.stage_changed','studio:quote-stage:'||q.id::text,jsonb_build_object('fromStage',prior_stage,'toStage','QUOTING','quoteId',q.id)),\n   (s.project_id,'quote.created','studio:quote-created:'||q.id::text,coalesce(p_command->'p_studio_created_audit','{}'::jsonb)||jsonb_build_object('quoteVersionId',q.id));\n end if;\n return q;\nend $$","create or replace function private.studio_client_document_owned(p_job_id uuid,p_worker_id text,p_lease_token uuid)\nreturns private.studio_client_documents language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare j public.background_jobs%rowtype; d private.studio_client_documents%rowtype;\nbegin\n j:=private.background_job_lock_owned(p_job_id,p_worker_id,p_lease_token);\n -- Cancellation is checked under the same job lock used by the request owner.\n if j.cancellation_requested_at is not null then raise exception 'studio_document_cancelled' using errcode='55000'; end if;\n select * into d from private.studio_client_documents where job_id=j.id for update;\n if j.kind<>'studio_design_booklet_v1' or d.snapshot_id is null or j.subject_type<>(case when d.variant_manifest is null then 'studio_snapshot' else 'studio_document' end)\n  or j.subject_id<>d.document_id::text or j.project_id<>d.project_id\n  or not exists(select 1 from private.studio_client_document_control where singleton and enabled and d.project_id=any(project_ids))\n then raise exception 'studio_document_job_mismatch' using errcode='42501'; end if;\n return d;\nend $$","create or replace function public.studio_client_document_worker_read(p_job_id uuid,p_worker_id text,p_lease_token uuid)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype;\nbegin\n d:=private.studio_client_document_owned(p_job_id,p_worker_id,p_lease_token);\n return jsonb_build_object('snapshotId',d.snapshot_id,'rendererVersion',d.renderer_version,'totalPages',d.total_pages,'readyFileId',d.file_id,\n  'documentId',d.document_id,'variantVersion',case when d.variant_manifest is null then null else 'studio-booklet-renders.v1' end,'renders',d.render_assets,\n  'source',(select drawing_source from private.studio_client_document_sources where snapshot_id=d.snapshot_id),\n  'pages',coalesce((select jsonb_agg(jsonb_build_object('index',page_index,'sha256',content_hash,'contentBase64',content_base64) order by page_index) from private.studio_client_document_pages where document_id=d.document_id),'[]'::jsonb));\nend $$","create or replace function public.studio_client_document_page_stage(p_job_id uuid,p_worker_id text,p_lease_token uuid,p_page_index integer,p_content_base64 text,p_sha256 text)\nreturns integer language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; previous text; count_pages integer;\nbegin\n d:=private.studio_client_document_owned(p_job_id,p_worker_id,p_lease_token);\n if d.file_id is not null or p_page_index is null or p_page_index not between 0 and d.total_pages-1\n  or p_content_base64 is null or length(p_content_base64)>16777216 or substring(decode(p_content_base64,'base64') from 1 for 5)<>convert_to('%PDF-','UTF8')\n  or p_sha256 is null or encode(sha256(decode(p_content_base64,'base64')),'hex')<>p_sha256\n then raise exception 'studio_document_page_invalid'; end if;\n select content_hash into previous from private.studio_client_document_pages where document_id=d.document_id and page_index=p_page_index;\n if previous is not null and previous<>p_sha256 then raise exception 'studio_document_checkpoint_conflict'; end if;\n insert into private.studio_client_document_pages(document_id,page_index,content_hash,content_base64) values(d.document_id,p_page_index,p_sha256,p_content_base64) on conflict do nothing;\n select count(*) into count_pages from private.studio_client_document_pages where document_id=d.document_id;\n return count_pages;\nend $$","create or replace function public.studio_client_document_finish(p_job_id uuid,p_worker_id text,p_lease_token uuid,p_content_base64 text,p_sha256 text)\nreturns uuid language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; file_uuid uuid; filename text; previous_hash text;\nbegin\n d:=private.studio_client_document_owned(p_job_id,p_worker_id,p_lease_token);\n if p_content_base64 is null or length(p_content_base64)>33554432 or substring(decode(p_content_base64,'base64') from 1 for 5)<>convert_to('%PDF-','UTF8')\n  or p_sha256 is null or encode(sha256(decode(p_content_base64,'base64')),'hex')<>p_sha256\n  or (select count(*) from private.studio_client_document_pages where document_id=d.document_id)<>d.total_pages\n then raise exception 'studio_document_final_invalid'; end if;\n if d.file_id is not null then\n  select encode(sha256(decode(content_base64,'base64')),'hex') into previous_hash from public.file_artifacts where id=d.file_id;\n  if previous_hash<>p_sha256 then raise exception 'studio_document_final_conflict'; end if;\n  return d.file_id;\n end if;\n select 'Sanctuary-Design-'||q.quote_ref||'-v'||v.version_number||case when d.variant_hash is null then '' else '-'||left(d.variant_hash,10) end||'.pdf' into filename from public.quote_versions v join public.quotes q on q.id=v.quote_id where v.id=d.quote_version_id;\n insert into public.file_artifacts(project_id,filename,content_type,size_bytes,content_base64,created_by)\n values(d.project_id,filename,'application/pdf',octet_length(decode(p_content_base64,'base64')),p_content_base64,'background:studio-documents') returning id into file_uuid;\n update private.studio_client_documents set file_id=file_uuid,completed_at=clock_timestamp() where document_id=d.document_id;\n return file_uuid;\nend $$","create or replace function private.background_job_read_claim_queue(p_visibility_timeout_seconds integer,p_batch_size integer)\nreturns table(msg_id bigint,message jsonb)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare kinds jsonb; projects jsonb; versions jsonb;\nbegin\n versions:=coalesce(nullif(current_setting('sanctuary.studio_document_manifest_versions',true),'')::jsonb,'[\"legacy\",\"studio-booklet-layout.v2\"]'::jsonb);\n if jsonb_typeof(versions) is distinct from 'array' or jsonb_array_length(versions) not between 1 and 5 then raise exception 'invalid_document_manifest_capability'; end if;\n kinds:=nullif(current_setting('sanctuary.background_job_claim_kinds',true),'')::jsonb;\n projects:=nullif(current_setting('sanctuary.background_job_claim_projects',true),'')::jsonb;\n if (kinds is not null or projects is not null) and (jsonb_typeof(kinds) is distinct from 'array' or jsonb_array_length(kinds) not between 1 and 16\n  or jsonb_typeof(projects) is distinct from 'array' or jsonb_array_length(projects) not between 1 and 52\n ) then raise exception 'invalid_background_job_claim_scope' using errcode='22023'; end if;\n return query\n with candidates as (\n  select q.msg_id from pgmq.q_portal_background_jobs q\n  left join public.background_jobs j on j.id::text=q.message->>'jobId'\n  left join private.studio_client_documents doc on doc.document_id::text=j.subject_id and j.subject_type in ('studio_snapshot','studio_document')\n  left join private.studio_client_document_sources d on d.snapshot_id=doc.snapshot_id\n  where q.vt<=clock_timestamp() and (\n   (kinds is null and projects is null and j.kind is distinct from 'studio_design_booklet_v1')\n   or (kinds ? j.kind and projects ? j.project_id::text and j.queue_message_id=q.msg_id))\n  and (j.kind is distinct from 'studio_design_booklet_v1' or (d.snapshot_id is not null and versions ? (case when doc.variant_manifest is not null then 'studio-booklet-renders.v1' when not(d.drawing_source ? 'layoutVersion') then 'legacy' when jsonb_typeof(d.drawing_source->'layoutVersion')='string' and d.drawing_source->>'layoutVersion' in ('studio-booklet-layout.v2','studio-booklet-layout.v3','studio-booklet-layout.v4') then d.drawing_source->>'layoutVersion' else '' end)))\n  order by q.msg_id limit p_batch_size for update of q skip locked\n ), touched as (\n  update pgmq.q_portal_background_jobs q set vt=clock_timestamp()+make_interval(secs=>p_visibility_timeout_seconds),read_ct=q.read_ct+1\n  from candidates c where q.msg_id=c.msg_id returning q.msg_id,q.message\n ) select t.msg_id,t.message from touched t order by t.msg_id;\nend $$","create or replace function public.background_jobs_claim_documents(p_worker_id text,p_batch_size integer,p_visibility_timeout_seconds integer,p_kinds text[],p_project_ids uuid[],p_manifest_versions text[])\nreturns table(job_id uuid,kind text,contract_version integer,status public.background_job_status,current_phase text,attempt_number integer,max_attempts integer,queue_message_id bigint,lease_token uuid,lease_expires_at timestamptz,cancellation_requested_at timestamptz,rollout_mode public.background_job_rollout_mode,execution_owner public.background_job_execution_owner)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare previous_versions text:=current_setting('sanctuary.studio_document_manifest_versions',true);\nbegin\n if p_kinds is distinct from array['studio_design_booklet_v1']::text[]\n  or p_manifest_versions is null or cardinality(p_manifest_versions) not between 1 and 5\n  or array_position(p_manifest_versions,null) is not null\n  or exists(select 1 from unnest(p_manifest_versions) version where version not in ('legacy','studio-booklet-layout.v2','studio-booklet-layout.v3','studio-booklet-layout.v4','studio-booklet-renders.v1'))\n then raise exception 'invalid_document_manifest_capability' using errcode='22023'; end if;\n perform set_config('sanctuary.studio_document_manifest_versions',to_jsonb(p_manifest_versions)::text,true);\n return query select * from public.background_jobs_claim_scoped(p_worker_id,p_batch_size,p_visibility_timeout_seconds,p_kinds,p_project_ids);\n perform set_config('sanctuary.studio_document_manifest_versions',coalesce(previous_versions,''),true);\nexception when others then\n perform set_config('sanctuary.studio_document_manifest_versions',coalesce(previous_versions,''),true);\n raise;\nend $$","-- Preserve the invoice restoration lock added by its later migration.\ndo $patch$\ndeclare definition text; anchor text:='  if v_intent.status = ''finalised'' then';\nbegin\n definition:=pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure);\n if strpos(definition,anchor)=0 then raise exception 'Email dispatch owner changed'; end if;\n execute replace(definition,anchor,'  if v_intent.status = ''cancelled'' then raise exception ''Delivery was cancelled'' using errcode=''55000''; end if;'||chr(10)||anchor);\nend $patch$","create or replace function public.studio_client_document_status(p_quote_version_id uuid,p_actor_user_id uuid,p_download boolean default false)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; j public.background_jobs%rowtype; completed integer; result jsonb; empty_source private.studio_client_document_sources%rowtype;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id and g.variant_manifest is null;\n if not found then\n  select g.* into empty_source from private.studio_website_quote_bindings b\n   join private.studio_client_document_sources g on g.snapshot_id=b.snapshot_id\n   where b.quote_version_id=p_quote_version_id and g.drawing_source->>'layoutVersion'='studio-booklet-layout.v4';\n  if found and private.studio_document_total_pages(empty_source.drawing_source)=0 then\n   return jsonb_build_object('snapshotId',empty_source.snapshot_id,'rendererVersion',empty_source.renderer_version,\n    'completedPages',0,'totalPages',0,'state','unavailable','percent',0,'canRetry',false);\n  end if;\n  return null;\n end if;\n select * into j from public.background_jobs where id=d.job_id;\n select count(*) into completed from private.studio_client_document_pages where document_id=d.document_id;\n result:=jsonb_build_object('snapshotId',d.snapshot_id,'documentId',d.document_id,'rendererVersion',d.renderer_version,'completedPages',completed,'totalPages',d.total_pages,\n  'state',case when d.file_id is not null then 'ready' when d.enqueue_failed or j.status in ('needs_attention','permanent_failed','cancelled') then 'failed' when j.status='queued' then 'queued' else 'running' end,\n  'percent',case when d.file_id is not null then 100 else floor(completed*100.0/(d.total_pages+1)) end,\n  'canRetry',d.file_id is null and (d.enqueue_failed or (j.status in ('needs_attention','permanent_failed') and j.attempt_count<4)));\n if p_download and d.file_id is not null then result:=result||jsonb_build_object('file',(select jsonb_build_object('filename',filename,'contentBase64',content_base64) from public.file_artifacts where id=d.file_id and project_id=d.project_id)); end if;\n return result;\nend $$","create function private.studio_document_identity_guard() returns trigger\nlanguage plpgsql set search_path=pg_catalog,pg_temp as $$\nbegin\n if (new.document_id,new.snapshot_id,new.project_id,new.quote_version_id,new.renderer_version,new.total_pages,new.variant_manifest,new.render_assets,new.variant_hash)\n is distinct from (old.document_id,old.snapshot_id,old.project_id,old.quote_version_id,old.renderer_version,old.total_pages,old.variant_manifest,old.render_assets,old.variant_hash)\n then raise exception 'studio_document_identity_immutable'; end if;\n return new;\nend $$","create trigger studio_document_identity_immutable before update on private.studio_client_documents for each row execute function private.studio_document_identity_guard()","revoke all on function private.studio_document_identity_guard() from public,anon,authenticated,service_role","create function public.studio_client_document_variant_status(p_quote_version_id uuid,p_actor_user_id uuid,p_document_id uuid,p_download boolean default false)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; j public.background_jobs%rowtype; completed integer; result jsonb;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id\n where b.quote_version_id=p_quote_version_id and g.quote_version_id=p_quote_version_id and g.document_id=p_document_id;\n if not found then return null; end if;\n select * into j from public.background_jobs where id=d.job_id;\n select count(*) into completed from private.studio_client_document_pages where document_id=d.document_id;\n result:=jsonb_build_object('snapshotId',d.snapshot_id,'documentId',d.document_id,'rendererVersion',d.renderer_version,'completedPages',completed,'totalPages',d.total_pages,\n 'state',case when d.file_id is not null then 'ready' when d.enqueue_failed or j.status in ('needs_attention','permanent_failed','cancelled') then 'failed' when j.status='queued' then 'queued' else 'running' end,\n 'percent',case when d.file_id is not null then 100 else floor(completed*100.0/(d.total_pages+1)) end,\n 'canRetry',d.file_id is null and (d.enqueue_failed or (j.status in ('needs_attention','permanent_failed') and j.attempt_count<4)));\n if p_download and d.file_id is not null then result:=result||jsonb_build_object('file',(select jsonb_build_object('id',id,'filename',filename,'contentType',content_type,'sizeBytes',size_bytes,'sha256',encode(sha256(decode(content_base64,'base64')),'hex'),'contentBase64',content_base64) from public.file_artifacts where id=d.file_id and project_id=d.project_id)); end if;\n return result;\nend $$","revoke all on function public.studio_client_document_variant_status(uuid,uuid,uuid,boolean) from public,anon,authenticated","grant execute on function public.studio_client_document_variant_status(uuid,uuid,uuid,boolean) to service_role","create function public.studio_client_document_variant_retry(p_quote_version_id uuid,p_document_id uuid,p_actor_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare d private.studio_client_documents%rowtype; j public.background_jobs%rowtype;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select g.* into d from private.studio_website_quote_bindings b join private.studio_client_documents g on g.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id and g.quote_version_id=p_quote_version_id and g.document_id=p_document_id;\n if not found or d.file_id is not null or not exists(select 1 from private.studio_client_document_control where singleton and enabled and d.project_id=any(project_ids)) then raise exception 'studio_document_retry_unavailable'; end if;\n if d.job_id is null then perform private.studio_client_document_enqueue(d.document_id); return public.studio_client_document_variant_status(p_quote_version_id,p_actor_user_id,p_document_id,false); end if;\n select * into j from public.background_jobs where id=d.job_id for update;\n select * into d from private.studio_client_documents where document_id=p_document_id for update;\n if d.file_id is not null or j.status not in ('needs_attention','permanent_failed') or j.attempt_count>=4 then raise exception 'studio_document_retry_unavailable'; end if;\n perform public.background_job_manual_retry(j.id,p_actor_user_id);\n return public.studio_client_document_variant_status(p_quote_version_id,p_actor_user_id,p_document_id,false);\nend $$","revoke all on function public.studio_client_document_variant_retry(uuid,uuid,uuid) from public,anon,authenticated","grant execute on function public.studio_client_document_variant_retry(uuid,uuid,uuid) to service_role","-- Backward three-argument operations always address the original base document.\ncreate or replace function public.studio_client_document_retry(p_quote_version_id uuid,p_snapshot_id uuid,p_actor_user_id uuid)\nreturns jsonb language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\nbegin\n if not exists(select 1 from private.studio_website_quote_bindings b join private.studio_client_documents d on d.snapshot_id=b.snapshot_id where b.quote_version_id=p_quote_version_id and b.snapshot_id=p_snapshot_id and d.document_id=p_snapshot_id and d.variant_manifest is null) then raise exception 'studio_document_retry_unavailable'; end if;\n return public.studio_client_document_variant_retry(p_quote_version_id,p_snapshot_id,p_actor_user_id);\nend $$","create function public.studio_client_document_variant_prepare(p_quote_version_id uuid,p_actor_user_id uuid,p_file_ids uuid[])\nreturns uuid language plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare b private.studio_website_quote_bindings%rowtype; source private.studio_client_document_sources%rowtype; base private.studio_client_documents%rowtype; f public.file_artifacts%rowtype; asset jsonb; assets jsonb:='[]'; manifest jsonb; digest text; doc_id uuid; total_bytes integer:=0; fid uuid; bound_project uuid;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select * into strict b from private.studio_website_quote_bindings where quote_version_id=p_quote_version_id;\n select * into source from private.studio_client_document_sources where snapshot_id=b.snapshot_id;\n select * into base from private.studio_client_documents where snapshot_id=b.snapshot_id and variant_manifest is null;\n select s.project_id into bound_project from private.studio_website_quote_snapshots s join public.quote_versions v on v.id=p_quote_version_id join public.quotes q on q.id=v.quote_id and q.project_id=s.project_id where s.id=b.snapshot_id;\n if bound_project is null or not exists(select 1 from private.studio_client_document_control where singleton and enabled and bound_project=any(project_ids)) then raise exception 'studio_client_document_unavailable'; end if;\n if p_file_ids is null or cardinality(p_file_ids)>8 or array_position(p_file_ids,null) is not null or (select count(distinct id) from unnest(p_file_ids) id)<>cardinality(p_file_ids) then raise exception 'studio_render_selection_invalid'; end if;\n if cardinality(p_file_ids)=0 then return base.document_id; end if;\n if base.document_id is null or source.drawing_source->>'layoutVersion' is distinct from 'studio-booklet-layout.v4' then raise exception 'studio_variant_unavailable'; end if;\n foreach fid in array p_file_ids loop\n  select * into f from public.file_artifacts where id=fid and project_id=base.project_id;\n  if not found or f.content_type not in ('image/png','image/jpeg') or f.size_bytes not between 1 and 2097152 or octet_length(decode(f.content_base64,'base64'))<>f.size_bytes then raise exception 'studio_render_unavailable'; end if;\n  total_bytes:=total_bytes+f.size_bytes;if total_bytes>4194304 then raise exception 'studio_render_selection_too_large'; end if;\n  asset:=jsonb_build_object('fileId',f.id,'label',left(f.filename,120),'contentType',f.content_type,'sha256',encode(sha256(decode(f.content_base64,'base64')),'hex'));\n  assets:=assets||jsonb_build_array(asset||jsonb_build_object('contentBase64',f.content_base64));\n end loop;\n manifest:=jsonb_build_object('schemaVersion','studio-booklet-renders.v1','snapshotId',b.snapshot_id,'sourceContentHash',source.drawing_source->>'contentHash','assets',(select jsonb_agg(value-'contentBase64' order by n) from jsonb_array_elements(assets) with ordinality a(value,n)));\n digest:=encode(sha256(convert_to(manifest::text,'UTF8')),'hex');\n perform pg_advisory_xact_lock(hashtextextended('studio-booklet-variant:'||b.snapshot_id::text||':'||digest,0));\n select document_id into doc_id from private.studio_client_documents where snapshot_id=b.snapshot_id and variant_hash=digest;\n if doc_id is not null then return doc_id; end if;\n doc_id:=gen_random_uuid();\n insert into private.studio_client_documents(document_id,snapshot_id,project_id,quote_version_id,renderer_version,total_pages,variant_manifest,render_assets,variant_hash)\n values(doc_id,b.snapshot_id,base.project_id,p_quote_version_id,base.renderer_version,base.total_pages+cardinality(p_file_ids),manifest,assets,digest);\n perform private.studio_client_document_enqueue(doc_id);return doc_id;\nend $$","revoke all on function public.studio_client_document_variant_prepare(uuid,uuid,uuid[]) from public,anon,authenticated","grant execute on function public.studio_client_document_variant_prepare(uuid,uuid,uuid[]) to service_role"],"statementSha256":["0bda499b3542affdd96094e38a992c0f61ab50aab54eac352d6ce3c544d02d4c","f1b3a7a446b1d17419203304b0cd453820273e0a090590e51979b528605a5fc1","10b187f5f4c5b6b03abde958d817723ae3d8c2d76a6df7c25029eceac6db5ece","484a75159fbbc1ce0841e3ae9ef06d91bd8ed3ce038dfa106bd2b0a7f8c270ae","8a3a4b54db0ce67063eb01793ac2681a15dd6e6f9f6436edcceca0105adbfac9","952a294acdd17fe65a583e7c45524327b09e7ba8a48ab2731bf0e81efdd4face","86bdfbee279e1cfe0303ad406701d18d797f940475d3578a9e53910808f34193","62852dcd706638ef5427b7478856badf473af7a4ab0861f8fe40a1cdb9833105","13a844cc1aaf5418546fc3d39840e1914b1cb16e868a37e28c841ffd29c3bfd6","0c34d268c92ce3ccf79f7580f5c5776ffcb7ab334fcea93300a4312208237492","ff294f16e131086a8eae9e7c7e89a08df785c3bc9f52d65d2f2cca982b979b13","ea5290aed848e82700f43ddf889bed7f4c5d439a67278dfd9167e01267e5d3b1","d01987c3c3266551a51fc5324fe986745181c3de26f5abce42ddec134e4a41de","ec6d9760b3eb7af6933dc8b849ee969fae8df60d7d5d8a1a7e4ac5cde68e2b09","027205f1d1483013609d853122d1705d404c9c2087b1a23858bd981820f4d049","cf07a0f6fc9a4ca646a423be8d67d35d6a97d56cf5f1ca594c8aede6ca004117","4493c017bc1ae15c24ce4fe01c2a8ec452be5e832eb5da0ecfdfdcea6f900887","2905482e7158883c87404235460a8f62c19257c08df55278f7f7fc2c1a1ce4ec","b2bff7aa45f525238ee60b3f3b30aab34adaa6be1e127ba2ff6e66eff05bd9f3","ec7102af8eb011269d6172eb0cee9a01a8d5674e4a94bcd77fb25277448cf8a5","d492c4a013067ca75c48cba914256b8ff3fe732e35921e8bb771ca10ef07bbca","11e3f2c684347c886c3d16cbcf19f0dcb6f5deb7dce4beea2110a5f1dadef7f7","65dcca620f6dc56692bf35db77fcabb0504828e96eaef25a7f615c16c6fabd72","a64cf16274959767522a1e26ddbbcb654f2446a03c7546f74684c7233cb7a960","3386d3365753f6aa9a71a5428a38b941d19bba285dc12f3bb3059e10ba10b2f6","7ef009ec211665257bf89a1e7c59c6f36d51051326b0a41fb4580a1734261b29","e5eb49bd39a609e55189272165ac1f859443276e0fe37daadd8dc5253c9585af","ce59a480bfea95b1d7be8b203ec2ab0cb763b07108aa8c5919c39d0c94f340a0","3e5f34216a0cd811e4e30af4e5a04644952efde27987f791297b63cfbb203c6b","8994158fbee00189b42c46040fe5c2c6f1c30699b573771400a208d22cef3030","2dbca3245c367a4b69afb2a8bd879b6edcc5a5c938e72179c6148abe97452949","7836b445ae76d727209662734b698a3d94c849cea1d0261219204d2231d1b89d","f80ca64818ffe5f31cf67b7dfec8910cbf463cdb7fb3eb45b043dede560ab0cf","df37235b8141b2b0536e8ef35f46d7b865e684442a1e94528672627196410ff1","a6958bde8be297b281746815c5e51661ade8a521de01c15cc5d91fed857d1314","08accfcf0f279bf519ea582053ba17f14110ca8f5aca166a94defd95a8ce7d90","41fa2392512b36800f79d015c75ae705ef48b9e4986d7e330dcf693f5362573f","a8c2c9e339ddda47787ebf748bff23fd5a86c6648ff2e73de90d7b3af90a19c0"]},{"version":"20261029231753","name":"studio_client_package_drafts","rawSha256":"217f7b1548121955ce7228981e5ec5c57fa6576e30b09a7321bab45d1d12d837","canonicalLfSha256":"8d8b7af12081c46cd24d6e50937b546bafbfeb363c5f6c1b53df4e22e45ead26","statements":["-- Quote-context drafts are private; no raw client or service table privileges.\ncreate table private.studio_client_package_drafts(\n quote_version_id uuid primary key references public.quote_versions(id),project_id uuid not null references public.projects(id),\n revision integer not null default 0 check(revision>=0),value jsonb not null,\n document_id uuid references private.studio_client_documents(document_id),\n prepared_intent_id uuid references private.commercial_email_intents(id),prepared_revision integer,\n updated_at timestamptz not null default clock_timestamp()\n)","alter table private.studio_client_package_drafts enable row level security","revoke all on private.studio_client_package_drafts from public,anon,authenticated,service_role","create function private.studio_package_assert(p_quote_version_id uuid,p_actor_user_id uuid) returns uuid\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid;\nbegin\n if not exists(select 1 from public.portal_users where user_id=p_actor_user_id and role in ('staff','admin')) then raise exception 'studio_staff_required' using errcode='42501'; end if;\n select q.project_id into project from public.quote_versions v join public.quotes q on q.id=v.quote_id join private.studio_website_quote_bindings b on b.quote_version_id=v.id where v.id=p_quote_version_id;\n if project is null or not exists(select 1 from private.studio_client_document_control where singleton and enabled and project=any(project_ids)) then raise exception 'studio_package_unavailable'; end if;\n return project;\nend $$","revoke all on function private.studio_package_assert(uuid,uuid) from public,anon,authenticated,service_role","create function public.studio_client_package_read(p_quote_version_id uuid,p_actor_user_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid; draft private.studio_client_package_drafts%rowtype;\nbegin\n project:=private.studio_package_assert(p_quote_version_id,p_actor_user_id);\n select * into draft from private.studio_client_package_drafts where quote_version_id=p_quote_version_id;\n return case when draft.quote_version_id is null then null else jsonb_build_object('revision',draft.revision,'value',draft.value,'documentId',draft.document_id,'preparedIntentId',draft.prepared_intent_id,'preparedRevision',draft.prepared_revision) end;\nend $$","revoke all on function public.studio_client_package_read(uuid,uuid) from public,anon,authenticated","grant execute on function public.studio_client_package_read(uuid,uuid) to service_role","create function public.studio_client_package_save(p_quote_version_id uuid,p_actor_user_id uuid,p_expected_revision integer,p_value jsonb) returns jsonb\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid; draft private.studio_client_package_drafts%rowtype; doc uuid; item jsonb;\nbegin\n project:=private.studio_package_assert(p_quote_version_id,p_actor_user_id);\n perform pg_advisory_xact_lock(hashtextextended('studio-package:'||p_quote_version_id::text,0));\n select * into draft from private.studio_client_package_drafts where quote_version_id=p_quote_version_id for update;\n if coalesce(draft.revision,0) is distinct from p_expected_revision then raise exception 'studio_package_stale' using errcode='PT409'; end if;\n if draft.prepared_intent_id is not null then raise exception 'Cancel the prepared email before editing this package' using errcode='PT409'; end if;\n if jsonb_typeof(p_value) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_value))<>6\n or not(p_value ?& array['to','subject','message','includeBooklet','renderFileIds','fileIds'])\n or jsonb_typeof(p_value->'to')<>'string' or length(p_value->>'to')>320\n or jsonb_typeof(p_value->'subject')<>'string' or length(p_value->>'subject')>200\n or jsonb_typeof(p_value->'message')<>'string' or length(p_value->>'message')>10000\n or jsonb_typeof(p_value->'includeBooklet')<>'boolean' or jsonb_typeof(p_value->'renderFileIds')<>'array' or jsonb_array_length(p_value->'renderFileIds')>8\n or jsonb_typeof(p_value->'fileIds')<>'array' or jsonb_array_length(p_value->'fileIds')>9 then raise exception 'studio_package_invalid'; end if;\n if exists(select 1 from jsonb_array_elements_text(p_value->'renderFileIds') a(id) join jsonb_array_elements_text(p_value->'fileIds') b(id) using(id)) then raise exception 'Rendered views belong inside the design booklet'; end if;\n for item in select value from jsonb_array_elements(p_value->'fileIds') loop\n  if not exists(select 1 from public.file_artifacts where id=(item#>>'{}')::uuid and project_id=project) then raise exception 'studio_package_file_unavailable'; end if;\n end loop;\n doc:=public.studio_client_document_variant_prepare(p_quote_version_id,p_actor_user_id,array(select value::uuid from jsonb_array_elements_text(p_value->'renderFileIds')));\n insert into private.studio_client_package_drafts(quote_version_id,project_id,revision,value,document_id)\n values(p_quote_version_id,project,1,p_value,doc)\n on conflict(quote_version_id) do update set revision=studio_client_package_drafts.revision+1,value=p_value,document_id=doc,updated_at=clock_timestamp();\n return public.studio_client_package_read(p_quote_version_id,p_actor_user_id);\nend $$","revoke all on function public.studio_client_package_save(uuid,uuid,integer,jsonb) from public,anon,authenticated","grant execute on function public.studio_client_package_save(uuid,uuid,integer,jsonb) to service_role","-- Exact immutable source for optional presentation capture, never the mutable estimate.\ncreate function public.studio_client_package_frozen_source(p_quote_version_id uuid,p_actor_user_id uuid) returns jsonb\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid;\nbegin\n project:=private.studio_package_assert(p_quote_version_id,p_actor_user_id);\n return(select s.handoff->'source' from private.studio_website_quote_bindings b join private.studio_website_quote_snapshots s on s.id=b.snapshot_id where b.quote_version_id=p_quote_version_id and s.project_id=project);\nend $$","revoke all on function public.studio_client_package_frozen_source(uuid,uuid) from public,anon,authenticated","grant execute on function public.studio_client_package_frozen_source(uuid,uuid) to service_role","-- Only the exact unattempted preparation may be reopened. Attempted delivery is immutable.\ncreate function public.studio_client_package_cancel(p_quote_version_id uuid,p_actor_user_id uuid,p_expected_revision integer,p_intent_id uuid,p_payload_hash text,p_commercial_revision bigint) returns jsonb\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid; q public.quote_versions%rowtype; draft private.studio_client_package_drafts%rowtype; intent private.commercial_email_intents%rowtype; previous text;\nbegin\n if p_quote_version_id is null or p_actor_user_id is null or p_expected_revision is null or p_expected_revision<1 or p_intent_id is null or p_payload_hash is null or p_payload_hash !~ '^[a-f0-9]{64}$' or p_commercial_revision is null or p_commercial_revision<1 then raise exception 'studio_package_cancel_invalid'; end if;\n project:=private.studio_package_assert(p_quote_version_id,p_actor_user_id);\n select * into strict q from public.quote_versions where id=p_quote_version_id;\n perform pg_advisory_xact_lock(hashtextextended('commercial-quote:'||q.quote_id::text,0));\n select * into strict q from public.quote_versions where id=p_quote_version_id for update;\n select * into strict draft from private.studio_client_package_drafts where quote_version_id=p_quote_version_id for update;\n if draft.revision is distinct from p_expected_revision or draft.prepared_revision is distinct from draft.revision or draft.prepared_intent_id is distinct from p_intent_id or q.commercial_revision is distinct from p_commercial_revision or q.status is distinct from 'DRAFT' then raise exception 'studio_package_stale' using errcode='PT409'; end if;\n select * into strict intent from private.commercial_email_intents where id=p_intent_id for update;\n if intent.kind is distinct from 'quote_send' or intent.subject_id is distinct from q.id or intent.project_id is distinct from project or intent.payload_hash is distinct from p_payload_hash or intent.status is distinct from 'prepared' or intent.attempt_count is distinct from 0 or (intent.protected_payload->>'commercialRevision')::bigint is distinct from p_commercial_revision or intent.provider_message_id is not null or intent.provider_accepted_at is not null then raise exception 'Delivery has already been attempted. Use its existing recovery controls.' using errcode='PT409'; end if;\n previous:=current_setting('sanctuary.studio_package_cancel',true);perform set_config('sanctuary.studio_package_cancel',intent.id::text,true);\n update private.commercial_email_intents set status='cancelled' where id=intent.id;\n perform set_config('sanctuary.studio_package_cancel',coalesce(previous,''),true);\n update private.studio_client_package_drafts set prepared_intent_id=null,prepared_revision=null,revision=revision+1 where quote_version_id=q.id;\n update public.quote_versions set delivery_prepared_at=null,is_current_draft=not exists(select 1 from public.quote_versions newer where newer.quote_id=q.quote_id and newer.id<>q.id and (newer.version_number>q.version_number or newer.is_current_draft)) where id=q.id;\n return public.studio_client_package_read(p_quote_version_id,p_actor_user_id);\nend $$","revoke all on function public.studio_client_package_cancel(uuid,uuid,integer,uuid,text,bigint) from public,anon,authenticated","grant execute on function public.studio_client_package_cancel(uuid,uuid,integer,uuid,text,bigint) to service_role","-- Add narrow quote cancellation without changing the invoice-generation guard.\ndo $patch$\ndeclare definition text; anchor text:='new.status=''cancelled'' and new.kind<>''deposit_invoice_send''';\nbegin\n definition:=pg_get_functiondef('private.invoice_email_generation_guard()'::regprocedure);\n if strpos(definition,anchor)=0 then raise exception 'Email cancellation guard changed'; end if;\n execute replace(definition,anchor,anchor||' and not((new.kind=''quote_send'' and old.status=''prepared'' and old.attempt_count=0 and old.provider_message_id is null and old.provider_accepted_at is null and current_setting(''sanctuary.studio_package_cancel'',true)=old.id::text) is true)');\nend $patch$","-- Bind canonical preparation atomically to the exact persisted package and ready file identities.\ndo $patch$\ndeclare definition text; anchor text:='  select prepared.id'; insertion text;\nbegin\n definition:=pg_get_functiondef('public.commercial_quote_prepare_delivery_email(uuid,bigint,text,text,uuid,uuid,text,jsonb,timestamptz)'::regprocedure);\n if strpos(definition,anchor)=0 then raise exception 'Quote preparation owner changed'; end if;\n insertion:=$body$\n  if p_protected_payload ? 'studioPackage' then\n    perform private.studio_package_assert(p_quote_version_id,(p_protected_payload#>>'{studioPackage,actorUserId}')::uuid);\n    perform 1 from private.studio_client_package_drafts draft\n    where draft.quote_version_id=p_quote_version_id and draft.revision=(p_protected_payload#>>'{studioPackage,revision}')::integer\n      and draft.value=p_protected_payload#>'{studioPackage,value}'\n      and draft.document_id is not distinct from nullif(p_protected_payload#>>'{studioPackage,documentId}','')::uuid\n      and draft.prepared_intent_id is null\n    for update;\n    if not found then raise exception 'studio_package_stale' using errcode='40001'; end if;\n    if p_protected_payload#>'{studioPackage,value,includeBooklet}'='true'::jsonb and not exists(\n      select 1 from private.studio_client_documents d where d.document_id=(p_protected_payload#>>'{studioPackage,documentId}')::uuid\n      and d.quote_version_id=p_quote_version_id and d.file_id is not null\n      and p_protected_payload->'attachmentFileIds'->>1=d.file_id::text\n    ) then raise exception 'The selected design booklet is not ready'; end if;\n    if (p_protected_payload->'attachmentFileIds') is distinct from (\n      jsonb_build_array(p_protected_payload->'attachmentFileIds'->0)\n      ||(case when p_protected_payload#>'{studioPackage,value,includeBooklet}'='true'::jsonb then jsonb_build_array(p_protected_payload->'attachmentFileIds'->1) else '[]'::jsonb end)\n      ||(p_protected_payload#>'{studioPackage,value,fileIds}'))\n    then raise exception 'studio_package_attachments_changed'; end if;\n  end if;\n$body$;\n execute replace(replace(definition,anchor,insertion||chr(10)||anchor),'  return query select v_intent_id;',\n '  if p_protected_payload ? ''studioPackage'' then update private.studio_client_package_drafts set prepared_intent_id=v_intent_id,prepared_revision=revision where quote_version_id=p_quote_version_id; end if;'||chr(10)||'  return query select v_intent_id;');\nend $patch$","notify pgrst,'reload schema'","create function public.studio_client_package_files(p_quote_version_id uuid,p_actor_user_id uuid,p_offset integer default 0) returns jsonb\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid; selected uuid[]; result jsonb; more boolean;\nbegin\n project:=private.studio_package_assert(p_quote_version_id,p_actor_user_id);\n if p_offset is null or p_offset<0 or p_offset>10000 or p_offset%100<>0 then raise exception 'studio_package_file_page_invalid'; end if;\n select array(select value::uuid from jsonb_array_elements_text(draft.value->'fileIds'))||array(select value::uuid from jsonb_array_elements_text(draft.value->'renderFileIds')) into selected from private.studio_client_package_drafts draft where quote_version_id=p_quote_version_id;\n with recent as (select * from public.file_artifacts where project_id=project and content_type in ('application/pdf','image/png','image/jpeg','image/webp') order by created_at desc,id desc offset p_offset limit 100),\n chosen as (select * from recent union select * from public.file_artifacts where project_id=project and id=any(coalesce(selected,'{}'::uuid[])))\n select coalesce(jsonb_agg(jsonb_build_object('id',id,'filename',filename,'contentType',content_type,'sizeBytes',size_bytes,'sha256',encode(sha256(decode(content_base64,'base64')),'hex'),'renderEligible',content_type in ('image/png','image/jpeg') and size_bytes<=2097152) order by created_at desc,id desc),'[]'::jsonb) into result from chosen;\n select exists(select 1 from public.file_artifacts where project_id=project and content_type in ('application/pdf','image/png','image/jpeg','image/webp') order by created_at desc,id desc offset p_offset+100 limit 1) into more;\n return jsonb_build_object('files',result,'hasMore',more,'offset',p_offset);\nend $$","revoke all on function public.studio_client_package_files(uuid,uuid,integer) from public,anon,authenticated","grant execute on function public.studio_client_package_files(uuid,uuid,integer) to service_role","-- A package preview/download/retry must still name the exact desired immutable document.\ncreate function public.studio_client_package_document(p_quote_version_id uuid,p_actor_user_id uuid,p_expected_revision integer,p_document_id uuid,p_download boolean default false,p_retry boolean default false) returns jsonb\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare project uuid; draft private.studio_client_package_drafts%rowtype; base uuid; result jsonb;\nbegin\n project:=private.studio_package_assert(p_quote_version_id,p_actor_user_id);\n if p_expected_revision is null or p_expected_revision<0 or p_document_id is null or p_download is null or p_retry is null then raise exception 'studio_package_document_invalid'; end if;\n select * into draft from private.studio_client_package_drafts where quote_version_id=p_quote_version_id for share;\n if found then\n  if draft.revision is distinct from p_expected_revision or draft.document_id is distinct from p_document_id then raise exception 'studio_package_stale' using errcode='PT409'; end if;\n else\n  select d.document_id into base from private.studio_website_quote_bindings b join private.studio_client_documents d on d.snapshot_id=b.snapshot_id and d.variant_manifest is null where b.quote_version_id=p_quote_version_id;\n  if p_expected_revision<>0 or base is distinct from p_document_id then raise exception 'studio_package_stale' using errcode='PT409'; end if;\n end if;\n if p_retry then result:=public.studio_client_document_variant_retry(p_quote_version_id,p_document_id,p_actor_user_id);\n else result:=public.studio_client_document_variant_status(p_quote_version_id,p_actor_user_id,p_document_id,p_download); end if;\n if result is null or (p_download and result->>'state' is distinct from 'ready') then raise exception 'The selected design booklet is not ready'; end if;\n return result||jsonb_build_object('packageRevision',p_expected_revision);\nend $$","revoke all on function public.studio_client_package_document(uuid,uuid,integer,uuid,boolean,boolean) from public,anon,authenticated","grant execute on function public.studio_client_package_document(uuid,uuid,integer,uuid,boolean,boolean) to service_role"],"statementSha256":["c4b169469e74625c9f31a36d6027a16bd9b00758d70ffae88929b1801a93ea80","d5575308638c78b424a6396e6a2568c490478a1d43935e6d4f2760012b090f24","07ed73817d02599dfd44441a97c6cb1ce45ea8a36466b4589e8cbcf34d54c50b","a8b48abcba506fd86d0dd186387f7a0ad54f40e18cc7cd24458365ee17b57023","a675a40b0ffd24951e249022d3505687f96fa83d1dc4a2a83772a6f21e2154ce","a4dbeee15d0e07637a9420418e9bb7934d5e050f703bbf745593a1907043436c","283fd8ae9f59ab6db49c48e27f6c3a817f14dee5f4189859761b135d65352d38","02dfcbbe74ed4653fa6a960707e05764f5ba6b0f32846bc70e9a23a88aefb1fe","d930412aaa08512cb8266ba9998b50e76e56de3f820b5126c5d2994712c61cc7","ddcf6a4deacfb646e72c58314f8d1c8e8f538bbf8568d476b47d772a86405fbe","5c81e488f3ae5bfef9bc2d48d2537286326c63a9c8e7c81c4e696fbdad57852f","c7fbda4d45d11600eae69180ed4855f6e4705736982d8d82c6ac0321d9eab316","6d8096601449df62b61278cd61322429e1320c0078263403f45a6728ec24623d","0e5e4ed4e932404bb89a3d5c947b50623c7d067437f4f31a069ae42bc79fcad6","34b40f90c0d77459cabc7a077c70f930203d30b175eca53cd97d801834b35c6f","ec5504785575e9970ba084013426409571a09a1d7157562d3b79a72c928e8e64","3ad86faec91da853b94bbe6efd07b312a105f0352ff25312635acb89261ffaaf","eea90a58dfd1709b27b8276afd766649ae2cf4064c165cbc60ed7a49a767a830","0d5ced6a944241d872a6716597e3b1bfe7f85b0067efa959b8f07473f1e6475e","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c","38a52c68fb1c0463c2252f65d09198b49c5d39a163c1e795eeacc2ec2c496ca8","6d843848dbcb7324a99f01997a495d9aa47324bbf3b78eea39533c8f9b70fbe0","f55b304497325ce4806db3341b517b808727b61a3db1b96fa6432f4edca0b852","ae873d04a60815927e59f4f6153cda0e6c7a507183a64c2744c05087b9f535d8","4dd6b25b7d5c3e0258a2f2f34399d5aef23132be6df837aaa122d80dd85f6bf6","e3c2b08b41f9650cec284a14a57e14ea164cf398c1a887f0f0f25fa755a27b3f"]},{"version":"20261030020837","name":"studio_designer_staff_trial_scope","rawSha256":"3669916dfbd1d84d2e42f479bd99847ff4c76b37da1dfbb6da47621935524323","canonicalLfSha256":"3669916dfbd1d84d2e42f479bd99847ff4c76b37da1dfbb6da47621935524323","statements":["-- Forward-only trial admission. Existing explicit-project workers remain the default.\n-- Install the complete Studio chain atomically: its v1 metrics projection protects older workers.\nalter table private.studio_client_document_control\n add column project_scope text not null default 'explicit_projects' check(project_scope in ('explicit_projects','staff_trial')),\n add column customer_send_enabled boolean not null default false","alter table private.studio_client_document_control drop constraint studio_client_document_control_check","alter table private.studio_client_document_control add constraint studio_client_document_control_admission_check\n check(not enabled or project_scope='staff_trial' or cardinality(project_ids)>0)","create function private.studio_client_document_project_enabled(p_project_id uuid) returns boolean\nlanguage sql stable security definer set search_path=pg_catalog,pg_temp as $$\n select p_project_id is not null and exists(select 1 from public.projects where id=p_project_id)\n and exists(select 1 from private.studio_client_document_control where singleton and enabled\n  and (project_scope='staff_trial' or p_project_id=any(project_ids)));\n$$","revoke all on function private.studio_client_document_project_enabled(uuid) from public,anon,authenticated,service_role","-- Replace only the final definitions' original admission predicate. Any drift aborts the batch.\ndo $patch$\ndeclare target record; definition text; anchor text;\nbegin\n for target in select * from (values\n  ('public.studio_client_document_capability(uuid,uuid)','p_project_id'),\n  ('public.studio_client_quote_prepare(uuid,uuid,uuid,uuid,timestamp with time zone,jsonb,jsonb,uuid,text,jsonb,jsonb,jsonb,jsonb)','p_project_id'),\n  ('private.studio_client_document_enqueue(uuid)','d.project_id'),\n  ('public.studio_client_quote_commit(text,uuid,text,jsonb)','s.project_id'),\n  ('private.studio_client_document_owned(uuid,text,uuid)','d.project_id'),\n  ('public.studio_client_quote_create_replay(uuid,uuid,uuid,uuid,jsonb)','p_project_id'),\n  ('public.studio_client_quote_store_pdf(uuid,uuid,uuid,text,bigint,text,jsonb,text,text)','s.project_id'),\n  ('public.studio_client_document_variant_retry(uuid,uuid,uuid)','d.project_id'),\n  ('public.studio_client_document_variant_prepare(uuid,uuid,uuid[])','bound_project'),\n  ('private.studio_package_assert(uuid,uuid)','project')\n ) as targets(signature,project_expression) loop\n  if to_regprocedure(target.signature) is null then raise exception 'Studio admission owner missing: %',target.signature; end if;\n  definition:=pg_get_functiondef(to_regprocedure(target.signature));\n  anchor:='exists(select 1 from private.studio_client_document_control where singleton and enabled and '||target.project_expression||'=any(project_ids))';\n  if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'Studio admission owner changed: %',target.signature; end if;\n  execute replace(definition,anchor,'private.studio_client_document_project_enabled('||target.project_expression||')');\n end loop;\nend $patch$","-- Read-only eligibility is shared by bounded project selection and the final pre-visibility reader.\n-- It does not lease jobs, increment read_ct or hide unsupported queue messages.\ncreate function private.studio_client_document_trial_job_eligible(p_job_id uuid,p_versions jsonb) returns boolean\nlanguage sql stable security definer set search_path=pg_catalog,pg_temp as $$\n select exists(\n  select 1 from public.background_jobs j\n  join pgmq.q_portal_background_jobs q on q.msg_id=j.queue_message_id\n  join private.studio_client_documents doc on doc.job_id=j.id and doc.document_id::text=j.subject_id and doc.project_id=j.project_id\n  join private.studio_client_document_sources source on source.snapshot_id=doc.snapshot_id\n  where j.id=p_job_id and j.kind='studio_design_booklet_v1' and j.contract_version=1\n   and j.subject_type=case when doc.variant_manifest is null then 'studio_snapshot' else 'studio_document' end\n   and j.execution_owner='worker' and j.rollout_mode='worker_enabled'\n   and j.status not in ('succeeded','cancelled','needs_attention','permanent_failed')\n   and (j.next_attempt_at is null or j.next_attempt_at<=clock_timestamp())\n   and (j.lease_expires_at is null or j.lease_expires_at<=clock_timestamp())\n   and q.vt<=clock_timestamp() and jsonb_typeof(q.message)='object'\n   and q.message->>'jobId'=j.id::text and q.message->'contractVersion'='1'::jsonb\n   and q.message-'jobId'-'contractVersion'='{}'::jsonb\n   and p_versions ? (case when doc.variant_manifest is not null then 'studio-booklet-renders.v1'\n    when not(source.drawing_source ? 'layoutVersion') then 'legacy'\n    when jsonb_typeof(source.drawing_source->'layoutVersion')='string'\n     and source.drawing_source->>'layoutVersion' in ('studio-booklet-layout.v2','studio-booklet-layout.v3','studio-booklet-layout.v4')\n    then source.drawing_source->>'layoutVersion' else '' end)\n   and exists(select 1 from private.studio_client_document_control where singleton and enabled and project_scope='staff_trial')\n );\n$$","revoke all on function private.studio_client_document_trial_job_eligible(uuid,jsonb) from public,anon,authenticated,service_role","-- Keep the proven explicit-project reader, adding the trial-only predicate before VT/read_ct.\ndo $patch$\ndeclare definition text; anchor text:='  order by q.msg_id limit p_batch_size for update of q skip locked';\nbegin\n definition:=pg_get_functiondef('private.background_job_read_claim_queue(integer,integer)'::regprocedure);\n if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1 then raise exception 'Document queue reader changed'; end if;\n execute replace(definition,anchor,\n  '  and (current_setting(''sanctuary.studio_document_staff_trial'',true) is distinct from ''true'' or private.studio_client_document_trial_job_eligible(j.id,versions))'||chr(10)||anchor);\nend $patch$","create function public.background_jobs_claim_studio_trial(p_worker_id text,p_batch_size integer,p_visibility_timeout_seconds integer,p_manifest_versions text[])\nreturns table(job_id uuid,kind text,contract_version integer,status public.background_job_status,current_phase text,attempt_number integer,max_attempts integer,queue_message_id bigint,lease_token uuid,lease_expires_at timestamptz,cancellation_requested_at timestamptz,rollout_mode public.background_job_rollout_mode,execution_owner public.background_job_execution_owner)\nlanguage plpgsql security definer set search_path=pg_catalog,pg_temp as $$\ndeclare control private.studio_client_document_control%rowtype; projects uuid[];\n previous_trial text:=current_setting('sanctuary.studio_document_staff_trial',true);\nbegin\n if p_worker_id is null or p_worker_id !~ '^[A-Za-z0-9._:-]{1,128}$'\n  or p_batch_size is null or p_batch_size not between 1 and 100\n  or p_visibility_timeout_seconds is null or p_visibility_timeout_seconds not between 15 and 3600\n  or p_manifest_versions is null or cardinality(p_manifest_versions) not between 1 and 5\n  or array_position(p_manifest_versions,null) is not null\n  or exists(select 1 from unnest(p_manifest_versions) version where version not in ('legacy','studio-booklet-layout.v2','studio-booklet-layout.v3','studio-booklet-layout.v4','studio-booklet-renders.v1'))\n then raise exception 'invalid_studio_trial_claim' using errcode='22023'; end if;\n -- Hold admission through the canonical claim. A concurrent kill switch cannot be raced\n -- using an earlier discovery result; after revocation a new call returns no claims.\n select * into control from private.studio_client_document_control where singleton for share;\n if not found or not control.enabled or control.project_scope<>'staff_trial' then return; end if;\n select array_agg(eligible.project_id order by eligible.first_message) into projects from (\n  select j.project_id,min(q.msg_id) first_message\n  from pgmq.q_portal_background_jobs q join public.background_jobs j on j.queue_message_id=q.msg_id\n  where private.studio_client_document_trial_job_eligible(j.id,to_jsonb(p_manifest_versions))\n  group by j.project_id order by min(q.msg_id),j.project_id limit 32\n ) eligible;\n -- Empty never becomes the unscoped worker path.\n if coalesce(cardinality(projects),0)=0 then return; end if;\n perform set_config('sanctuary.studio_document_staff_trial','true',true);\n return query select * from public.background_jobs_claim_documents(p_worker_id,p_batch_size,p_visibility_timeout_seconds,array['studio_design_booklet_v1']::text[],projects,p_manifest_versions);\n perform set_config('sanctuary.studio_document_staff_trial',coalesce(previous_trial,''),true);\nexception when others then\n perform set_config('sanctuary.studio_document_staff_trial',coalesce(previous_trial,''),true);\n raise;\nend $$","revoke all on function public.background_jobs_claim_studio_trial(text,integer,integer,text[]) from public,anon,authenticated","grant execute on function public.background_jobs_claim_studio_trial(text,integer,integer,text[]) to service_role","-- This canonical transport fence also protects Studio intents after an application rollback.\n-- Preserve cancellation and invoice-generation checks, and freeze no new send permission.\ndo $patch$\ndeclare definition text; anchor text:='  if v_intent.status = ''finalised'' then';\nbegin\n definition:=pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure);\n if (length(definition)-length(replace(definition,anchor,'')))/length(anchor)<>1\n  or strpos(definition,'if v_intent.status = ''cancelled''')=0 then raise exception 'Canonical dispatch owner changed'; end if;\n execute replace(definition,anchor,\n  '  if v_intent.kind in (''quote_send'',''quote_resend'') and ('||chr(10)||\n  '    v_intent.protected_payload ? ''studioPackage'' or exists(select 1 from private.studio_website_quote_bindings where quote_version_id=v_intent.subject_id)'||chr(10)||\n  '  ) and not exists(select 1 from private.studio_client_document_control where singleton and customer_send_enabled) then'||chr(10)||\n  '    raise exception ''Studio customer email sending is disabled'' using errcode=''55000'';'||chr(10)||\n  '  end if;'||chr(10)||anchor);\nend $patch$","notify pgrst,'reload schema'"],"statementSha256":["f868ecea3ca8af812d0fa0f7fff15982956ddbb4ef1b34a9db0e8f554bd68154","2fdaf2037ade9974ece923f495bf87aeb7c8b0660d62176aef6a0a26aa0e4470","4fe02273ea77e6d1eb8de3b23d7c36c6674388291ab41933f74a89d477dee611","3ad976a5f165edfe53fe9d3fe5d92676aa88cbabd59041ead3ac44ff46748523","33f2949787a7e3d2e09628fed3c34d5b7517b12ce610778cba21e3806fdc5466","6159847efda424980808193f88c10ca04fa67ff5db1e9ef9bb42693aefa141b5","d18dc91d154a7b550801c238875e711929b2e8f144635c798ec1755f8dc8ebc6","876cfcf520b8c69c1526c7245b5f0aca4a95e42db5834e8919afd20557b1aab5","58bc69c6d49b9a7ac9858edfd1f8241c78293d5931f9ffbb0585f29748afde70","39da603701996352b363d54395e7792e6c22227273ac6c5ad76e8b7cf3d8fc40","10c3d08ed384781123ea3eee86992691135196e0ba17ce47b3fbfd79da7b93cc","121e1d8f54480f5f8b8e17d21994f92f2567c59a9e4df59c3a8c6aa6a51691a1","a3faba9247858a5d4410386b802e4566258d905dc9cbb31a96ee34e2a8345311","03ec30466ad17e2387450a5d286284f2873b8769a5c7f5de7998fc616d36287c"]}]$sources$::jsonb;
 expected_schema jsonb:=$approved_schema${"tables":[{"acl":[["postgres","postgres","DELETE",false],["postgres","postgres","INSERT",false],["postgres","postgres","MAINTAIN",false],["postgres","postgres","REFERENCES",false],["postgres","postgres","SELECT",false],["postgres","postgres","TRIGGER",false],["postgres","postgres","TRUNCATE",false],["postgres","postgres","UPDATE",false]],"rls":false,"name":"studio_authored_create_receipts","owner":"postgres","columns":[["project_id","uuid",true,null],["request_id","uuid",true,null],["actor_user_id","uuid",true,null],["source_estimate_id","uuid",false,null],["client_request","jsonb",true,null],["source_snapshot","jsonb",false,null],["estimate_id","uuid",true,null],["design_id","text",true,null],["saved_at","timestamp with time zone",true,null]],"indexes":["CREATE UNIQUE INDEX studio_authored_create_receipts_estimate_id_key ON private.studio_authored_create_receipts USING btree (estimate_id)","CREATE UNIQUE INDEX studio_authored_create_receipts_pkey ON private.studio_authored_create_receipts USING btree (project_id, request_id)"],"forceRls":false,"policies":null,"constraints":[["studio_authored_create_receipts_estimate_id_fkey","FOREIGN KEY (estimate_id) REFERENCES estimates(id)"],["studio_authored_create_receipts_estimate_id_key","UNIQUE (estimate_id)"],["studio_authored_create_receipts_pkey","PRIMARY KEY (project_id, request_id)"],["studio_authored_create_receipts_project_id_fkey","FOREIGN KEY (project_id) REFERENCES projects(id)"],["studio_authored_create_receipts_source_estimate_id_fkey","FOREIGN KEY (source_estimate_id) REFERENCES estimates(id)"]]},{"acl":[["postgres","postgres","DELETE",false],["postgres","postgres","INSERT",false],["postgres","postgres","MAINTAIN",false],["postgres","postgres","REFERENCES",false],["postgres","postgres","SELECT",false],["postgres","postgres","TRIGGER",false],["postgres","postgres","TRUNCATE",false],["postgres","postgres","UPDATE",false]],"rls":false,"name":"studio_authored_save_receipts","owner":"postgres","columns":[["estimate_id","uuid",true,null],["request_id","uuid",true,null],["actor_user_id","uuid",true,null],["request_payload","jsonb",true,null],["revision","bigint",true,null],["saved_at","timestamp with time zone",true,null]],"indexes":["CREATE UNIQUE INDEX studio_authored_save_receipts_pkey ON private.studio_authored_save_receipts USING btree (estimate_id, request_id)"],"forceRls":false,"policies":null,"constraints":[["studio_authored_save_receipts_estimate_id_fkey","FOREIGN KEY (estimate_id) REFERENCES estimates(id)"],["studio_authored_save_receipts_pkey","PRIMARY KEY (estimate_id, request_id)"],["studio_authored_save_receipts_revision_check","CHECK ((revision > 0))"]]},{"acl":[["postgres","postgres","DELETE",false],["postgres","postgres","INSERT",false],["postgres","postgres","MAINTAIN",false],["postgres","postgres","REFERENCES",false],["postgres","postgres","SELECT",false],["postgres","postgres","TRIGGER",false],["postgres","postgres","TRUNCATE",false],["postgres","postgres","UPDATE",false]],"rls":true,"name":"studio_client_document_control","owner":"postgres","columns":[["singleton","boolean",true,"true"],["enabled","boolean",true,"false"],["project_ids","uuid[]",true,"'{}'::uuid[]"],["project_scope","text",true,"'explicit_projects'::text"],["customer_send_enabled","boolean",true,"false"]],"indexes":["CREATE UNIQUE INDEX studio_client_document_control_pkey ON private.studio_client_document_control USING btree (singleton)"],"forceRls":false,"policies":null,"constraints":[["studio_client_document_control_admission_check","CHECK (((NOT enabled) OR (project_scope = 'staff_trial'::text) OR (cardinality(project_ids) > 0)))"],["studio_client_document_control_pkey","PRIMARY KEY (singleton)"],["studio_client_document_control_project_scope_check","CHECK ((project_scope = ANY (ARRAY['explicit_projects'::text, 'staff_trial'::text])))"],["studio_client_document_control_singleton_check","CHECK (singleton)"]]},{"acl":[["postgres","postgres","DELETE",