25ead1449fee133fec8c33e40794d60a0e9f5513d936d0b4261b494"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_client_quote_create(uuid, uuid, uuid, uuid, jsonb, jsonb, jsonb, jsonb)","definitionSha256":"61c1054d94ad3967a3475b92157b5cc6964b7e9eda09888660439a5d9e28dda5"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_client_quote_create_replay(uuid, uuid, uuid, uuid, jsonb)","definitionSha256":"30b7f0d2572bab7754916f258165b046c796b688526cb3685c4acb0edb08d5d0"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_client_quote_prepare(uuid, uuid, uuid, uuid, timestamp with time zone, jsonb, jsonb, uuid, text, jsonb, jsonb, jsonb, jsonb)","definitionSha256":"cd26b9cc74da378fda24f01b97bfff3950631fbaeaf5f6a392db79f192a8cbbb"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_client_quote_store_pdf(uuid, uuid, uuid, text, bigint, text, jsonb, text, text)","definitionSha256":"bf00b5914d698409c4a9d7af77d40f969b14d844662ac5f81d97d59f50a46b9c"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_website_quote_commit(text, uuid, text, jsonb)","definitionSha256":"849c1d96d3c067bba4b4715ed37d2229a105208a21dcb76002c1a1322ce75f27"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_website_quote_commit_address(text, uuid, text, jsonb)","definitionSha256":"a3593d275b73709fc347981e083cf0a70ac5092385c82a9f1108a84cd331d9f6"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_website_quote_commit_travel(text, uuid, text, jsonb)","definitionSha256":"1d17fcf736a06dd1e32e7d5b53ff17931ff1a8e145d49b7ab2dc90f3d726c88b"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_website_quote_prepare(uuid, uuid, uuid, uuid, timestamp with time zone, jsonb, jsonb, uuid, text, jsonb, jsonb, jsonb)","definitionSha256":"3b370f3b8412b59e5700767d361f2b5dabe0300d5badaff8ba97dc36043d41ae"},{"acl":[["postgres","postgres","EXECUTE",false],["service_role","postgres","EXECUTE",false]],"owner":"postgres","signature":"public.studio_website_quote_view(uuid)","definitionSha256":"0bf763e63afe06e64e6a8c0c978c75ed499a1cff529449059a429b0878be093d"}]$approved_postconditions$::jsonb;
 source_item jsonb; sql_text text; item jsonb; hist record; present_count integer;
 ledger_before text; ledger_after text; control_before text; control_after text; installed_new boolean:=false; actual_functions jsonb; excluded_oids oid[];
 protected_before jsonb; catalog_before text; access_before jsonb; metrics_before jsonb; metrics_after jsonb; function_oids_before oid[]; rehearsal_summary jsonb;
begin
 if expected_schema is null or jsonb_typeof(expected_schema)<>'object' or expected_functions is null or jsonb_typeof(expected_functions)<>'array' or jsonb_array_length(expected_functions)=0 then raise exception 'Review-only candidate: bind successful exact17 rollback function postconditions before application'; end if;
 if current_user not in ('postgres','supabase_admin') then raise exception 'Existing administrator connection required'; end if;
 if not exists(select 1 from pg_attribute where attrelid='supabase_migrations.schema_migrations'::regclass and attname='version' and atttypid='text'::regtype)
  or not exists(select 1 from pg_attribute where attrelid='supabase_migrations.schema_migrations'::regclass and attname='name' and atttypid='text'::regtype)
  or not exists(select 1 from pg_attribute where attrelid='supabase_migrations.schema_migrations'::regclass and attname='statements' and atttypid='text[]'::regtype) then raise exception 'Migration ledger schema changed'; end if;
 lock table supabase_migrations.schema_migrations in share row exclusive mode;
 select count(*) into present_count from supabase_migrations.schema_migrations h where h.version in(select s->>'version' from jsonb_array_elements(sources)s);
 if present_count not in (0,17) then raise exception 'Partial Studio source ledger; refuse installation or history repair'; end if;
 if present_count=17 then
  select md5(to_jsonb(c)::text) into control_before from private.studio_client_document_control c where singleton for share;
  if control_before is null then raise exception 'Installed Studio control row missing'; end if;
 end if;
 select md5(coalesce(string_agg(md5(to_jsonb(h)::text),',' order by h.version),'')) into ledger_before from supabase_migrations.schema_migrations h where h.version not in(select s->>'version' from jsonb_array_elements(sources)s);
 protected_before:=pg_temp.studio_metadata_fingerprint();
 access_before:=pg_temp.studio_canonical_access();
 select array_agg(oid) into function_oids_before from pg_proc;
 select to_jsonb(m)-'measured_at' into metrics_before from public.background_jobs_runtime_metrics() m;
 if present_count=0 then

 if current_user not in ('postgres','supabase_admin') then raise exception 'Migration rehearsal requires existing administrator connection'; end if;
 if current_setting('server_version_num')::int not between 170000 and 179999 or pg_is_in_recovery() then raise exception 'Unexpected production PostgreSQL identity'; end if;
 if not exists(select 1 from pg_extension where extname='pgmq' and extversion='1.5.1') then raise exception 'Expected PGMQ 1.5.1'; end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and left(c.relname,7)='studio_') then raise exception 'Studio is already installed; inspect target/history first'; end if;
 if to_regclass('public.projects') is null or to_regclass('public.estimates') is null or to_regclass('public.quote_versions') is null or to_regclass('public.file_artifacts') is null or to_regclass('pgmq.q_portal_background_jobs') is null then raise exception 'Required owner schema missing'; end if;
 if exists(select 1 from pg_trigger where tgrelid='public.background_job_kinds'::regclass and not tgisinternal and tgenabled<>'D') or exists(select 1 from pg_rewrite where ev_class='public.background_job_kinds'::regclass and rulename<>'_RETURN') then raise exception 'Unexpected registry insert trigger/rule; inspect its side effects before rehearsal'; end if;
 if md5(replace(pg_get_functiondef('public.commercial_quote_prepare_delivery_email(uuid,bigint,text,text,uuid,uuid,text,jsonb,timestamptz)'::regprocedure),chr(13),'')) is distinct from '00d7f34b4c763cf6c646cbee1f3501f8' then raise exception 'Canonical owner drift: commercial_quote_prepare_delivery_email'; end if;
 if md5(replace(pg_get_functiondef('private.invoice_email_generation_guard()'::regprocedure),chr(13),'')) is distinct from '31b6a70a13162889a5dd9dc22b93a309' then raise exception 'Canonical owner drift: invoice_email_generation_guard'; end if;
 if md5(replace(pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure),chr(13),'')) is distinct from '595243906227e46ec3b3027abc337c7a' then raise exception 'Canonical owner drift: commercial_email_mark_dispatching'; end if;
 if md5(replace((select prosrc from pg_proc where oid='public.background_jobs_claim(text,integer,integer)'::regprocedure),chr(13),'')) is distinct from '153ee6ca1c8d3580a0b78b0aa60dcb24' then raise exception 'Production generic claim differs from retained foundation07; inspect before replacing active enquiry/Xero worker owner'; end if;
 if md5(replace((select prosrc from pg_proc where oid='public.background_jobs_runtime_metrics()'::regprocedure),chr(13),'')) is distinct from 'c4f80cea01f2996c52e2daeb2252dc06' then raise exception 'Production worker metrics differ from retained foundation06'; end if;
  for source_item in select value from jsonb_array_elements(sources) loop
   for sql_text in select value from jsonb_array_elements_text(source_item->'statements') loop execute sql_text; end loop;
   insert into supabase_migrations.schema_migrations(version,name,statements)
    values(source_item->>'version',source_item->>'name',array(select value from jsonb_array_elements_text(source_item->'statements')));
  end loop;
  installed_new:=true;
  if exists(select 1 from private.studio_client_document_control where enabled or cardinality(project_ids)<>0 or project_scope<>'explicit_projects' or customer_send_enabled) then raise exception 'Install must remain default-dark/default-explicit/customer-send-off'; end if;
 end if;
 for source_item in select value from jsonb_array_elements(sources) loop
  select * into strict hist from supabase_migrations.schema_migrations where version=source_item->>'version';
  if hist.name is distinct from source_item->>'name' or hist.statements is null
   or to_jsonb(array(select encode(sha256(convert_to(replace(replace(s,chr(13)||chr(10),chr(10)),chr(13),chr(10)),'UTF8')),'hex') from unnest(hist.statements) with ordinality a(s,n) order by n)) is distinct from source_item->'statementSha256'
  then raise exception 'Canonical source ledger differs: %',source_item->>'version'; end if;
 end loop;

 select to_jsonb(m)-'measured_at' into metrics_after from public.background_jobs_runtime_metrics() m;
 if metrics_after is distinct from metrics_before then raise exception 'Existing legacy metrics projection changed (excluding scrape timestamp)'; end if;
 if jsonb_typeof(metrics_after->'kind_counts') is distinct from 'object' or metrics_after->'kind_counts' ? 'studio_design_booklet_v1' or exists(select 1 from jsonb_object_keys(metrics_after->'kind_counts') k where k<>all(array['ai_synthetic_v1','automation_event','deposit_invoice_prepare_and_send','email_outbox_deliver','job_pack_generate','quote_resend','quote_send','xero_invoice_draft_v1']::text[])) then raise exception 'Legacy208c installed-kind projection contains an unsupported key'; end if;
 if pg_temp.studio_metadata_fingerprint() is distinct from protected_before then raise exception 'Protected existing scalar metadata changed in rehearsal'; end if;
 if (select count(*) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname=any(array['studio_client_document_control','studio_client_document_sources','studio_client_documents','studio_client_document_pages','studio_client_package_drafts']) and c.relkind='r')<>5 then raise exception 'Required document/package tables missing'; end if;
 if pg_temp.studio_canonical_access() is distinct from access_before then raise exception 'Existing invoice/quote/worker owner, grant or search_path changed'; end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join unnest(array['anon','authenticated','service_role']) role_name where n.nspname='private' and left(c.relname,7)='studio_' and c.relkind='r' and (has_table_privilege(role_name,c.oid,'SELECT') or has_table_privilege(role_name,c.oid,'INSERT') or has_table_privilege(role_name,c.oid,'UPDATE') or has_table_privilege(role_name,c.oid,'DELETE'))) then raise exception 'Raw Studio table privilege exposure'; end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and c.relname=any(array['studio_client_document_control','studio_client_document_sources','studio_client_documents','studio_client_document_pages','studio_client_package_drafts']) and not c.relrowsecurity) then raise exception 'Required document/package RLS missing'; end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (left(p.proname,7)='studio_' or left(p.proname,length('background_jobs_claim_scoped'))='background_jobs_claim_scoped' or not(p.oid=any(function_oids_before))) and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or not has_function_privilege('service_role',p.oid,'EXECUTE') or not p.prosecdef or not(coalesce(p.proconfig,'{}')@>array['search_path=pg_catalog, pg_temp']))) then raise exception 'Studio RPC ACL/search_path/definer contract violated'; end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join unnest(array['anon','authenticated','service_role']) role_name where n.nspname='private' and (left(p.proname,7)='studio_' or not(p.oid=any(function_oids_before))) and has_function_privilege(role_name,p.oid,'EXECUTE')) then raise exception 'Private Studio helper exposed'; end if;
 if not exists(select 1 from public.background_job_kinds where kind='studio_design_booklet_v1' and not has_external_side_effect and default_rollout_mode='disabled') then raise exception 'Document kind must remain effect-free and default-dark'; end if;
 if strpos(pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure),'v_intent.status = ''cancelled''')=0 or strpos(pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure),'commercial-project-invoice:')=0 then raise exception 'Cancelled dispatch/invoice locking protection lost'; end if;
 if strpos(pg_get_functiondef('private.invoice_email_generation_guard()'::regprocedure),'sanctuary.studio_package_cancel')=0 or strpos(pg_get_functiondef('private.invoice_email_generation_guard()'::regprocedure),'commercial-project-invoice:')=0 then raise exception 'Package cancellation or invoice advisory owner missing'; end if;
 if strpos(pg_get_functiondef('public.commercial_quote_prepare_delivery_email(uuid,bigint,text,text,uuid,uuid,text,jsonb,timestamptz)'::regprocedure),'studio_package_assert')=0 then raise exception 'Canonical package preparation guard missing'; end if;
 select jsonb_build_object('privateStudioTables',count(*),'allRawTableAccessDenied',true,'requiredDocumentRls',true,'publicRpcServiceOnly',true,'legacyKnownKindProjectionCompatible',true,'legacyInstalledKindCount',(select count(*) from jsonb_object_keys(metrics_after->'kind_counts')),'legacyInstalledKeys',to_jsonb(array(select jsonb_object_keys(metrics_after->'kind_counts') order by 1)),'otherLegacyMetricsUnchanged',true,'producerEnabled',(select enabled from private.studio_client_document_control where singleton),'documentProviderEffects',false,'functionPostconditions',pg_temp.studio_function_manifest(function_oids_before),'schemaPostconditions',pg_temp.studio_schema_manifest()) into rehearsal_summary from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='private' and left(c.relname,7)='studio_' and c.relkind='r';

 if to_regprocedure('public.background_jobs_claim_studio_trial(text,integer,integer,text[])') is null then raise exception 'Trial claim owner missing'; end if;
 if strpos(pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure),'customer_send_enabled')=0 or strpos(pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure),'studio_website_quote_bindings')=0 or strpos(pg_get_functiondef('public.commercial_email_mark_dispatching(uuid)'::regprocedure),'studioPackage')=0 then raise exception 'Rollback-safe canonical Studio no-send fence missing'; end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and (left(p.proname,7)='studio_' or p.proname='studio_package_assert') and p.proname<>'studio_client_document_project_enabled' and strpos(p.prosrc,'=any(project_ids)')>0) then raise exception 'Final Studio owner retains stale explicit-project admission'; end if;
 rehearsal_summary:=rehearsal_summary||jsonb_build_object('trialInstalled',true,'customerSendingDisabled',true,'canonicalRollbackSendFencePresent',true);
 if installed_new and exists(select 1 from private.studio_client_document_control where customer_send_enabled) then raise exception 'New Studio installation must leave customer sending disabled'; end if;
 if not installed_new then
  select md5(to_jsonb(c)::text) into control_after from private.studio_client_document_control c where singleton;
  if control_before is distinct from control_after then raise exception 'No-op changed operator-controlled Studio settings'; end if;
 end if;
 select array_agg(p.oid) into excluded_oids from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where not exists(select 1 from jsonb_array_elements(expected_functions) e where e->>'signature'=n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')');
 if pg_temp.studio_schema_manifest() is distinct from expected_schema then raise exception 'Approved Studio table/constraint/index/RLS/ACL/trigger structure differs'; end if;
 actual_functions:=pg_temp.studio_function_manifest(coalesce(excluded_oids,'{}'::oid[]));
 if actual_functions is distinct from expected_functions then raise exception 'Approved post-install function body/ACL/owner/defaults/search_path differs'; end if;
 select md5(coalesce(string_agg(md5(to_jsonb(h)::text),',' order by h.version),'')) into ledger_after from supabase_migrations.schema_migrations h where h.version not in(select s->>'version' from jsonb_array_elements(sources)s);
 if ledger_before is distinct from ledger_after then raise exception 'Pre-existing migration history changed'; end if;
 insert into studio_rehearsal_result values(jsonb_build_object('mode',case when installed_new then 'installed17' else 'verified_noop' end,'canonicalSourceRows',17,'preExistingLedgerUnchanged',true,'customerSendingDisabled',not coalesce((select customer_send_enabled from private.studio_client_document_control where singleton),false),'operatorControlsUnchanged',not installed_new,'allPostconditionsVerified',true));
end $studio_atomic_install$;
-- The MCP response intentionally omits SQL result rows. Root records actual tool-assigned
-- batch version with a read-only history postflight and retains THIS EXACT QUERY as that file.
